(380565,42285,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, ha egy liba ... a szárnyait, mindenki hátrál, komolyan.'::text,'kitárja'::text,'kitárni'::text,'ki fogja tárni'::text,'Tesó, ha egy liba kitárja a szárnyait, mindenki hátrál, komolyan.'::text),
(380604,42290,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Süße, er hat zugegeben, dass er vor allen vor einer Gans ...'::text,'zurückgewichen ist'::text,'zurückzuweichen'::text,'zurückgewichen ist'::text,'Süße, er hat zugegeben, dass er vor allen vor einer Gans zurückgewichen ist.'::text),
(380608,42290,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, він зізнався, що ... від гуски на очах у всіх.'::text,'відступив'::text,'відступити'::text,'відступив'::text,'Подруго, він зізнався, що відступив від гуски на очах у всіх.'::text),
(380607,42290,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tía, él admitió ... ante un ganso delante de todos.'::text,'haber retrocedido'::text,'retroceder'::text,'que retrocedió'::text,'Tía, él admitió haber retrocedido ante un ganso delante de todos.'::text),
(380606,42290,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Meuf, il a avoué ... face à une oie devant tout le monde.'::text,'avoir reculé'::text,'reculer'::text,'qu''il a reculé'::text,'Meuf, il a avoué avoir reculé face à une oie devant tout le monde.'::text),
