(380658,42296,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ihre Rückkehr war lowkey ikonisch: Sie ... barfuß im Kreis, als die Kamera sie erwischte.'::text,'drehte sich gerade'::text,'drehte sich'::text,'hat sich gedreht'::text,'Ihre Rückkehr war lowkey ikonisch: Sie drehte sich gerade barfuß im Kreis, als die Kamera sie erwischte.'::text),
(380662,42296,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Її повернення було трохи легендарним: вона ... босоніж, коли її зняла камера.'::text,'крутилася'::text,'крутнулася'::text,'крутнулася'::text,'Її повернення було трохи легендарним: вона крутилася босоніж, коли її зняла камера.'::text),
(380661,42296,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Su regreso fue bastante icónico: ella ... descalza cuando la cámara la pilló.'::text,'estaba girando'::text,'giró'::text,'ha girado'::text,'Su regreso fue bastante icónico: ella estaba girando descalza cuando la cámara la pilló.'::text),
(380660,42296,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Son retour était grave iconique : elle ... pieds nus quand la caméra l''a filmée.'::text,'tournoyait'::text,'a tournoyé'::text,'a tournoyé'::text,'Son retour était grave iconique : elle tournoyait pieds nus quand la caméra l''a filmée.'::text),
(380663,42296,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Onun dönüşü resmen ikonikti: kamera onu yakaladığında o yalınayak ...'::text,'dönüyordu'::text,'döndü'::text,'dönmüş'::text,'Onun dönüşü resmen ikonikti: kamera onu yakaladığında o yalınayak dönüyordu.'::text),
(380664,42296,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A visszatérése lowkey ikonikus volt: ő éppen mezítláb ..., amikor a kamera elkapta.'::text,'pörgött'::text,'megpördült'::text,'megpördült'::text,'A visszatérése lowkey ikonikus volt: ő éppen mezítláb pörgött, amikor a kamera elkapta.'::text),
(380730,42304,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Süße, ich habe gehört, dass ... unserer Lieblingsreisenden heute passiert ist.'::text,'die Rückkehr'::text,'eine Rückkehr'::text,'Rückkehr'::text,'Süße, ich habe gehört, dass die Rückkehr unserer Lieblingsreisenden heute passiert ist.'::text),
(380734,42304,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, я чула, що ... нашої улюбленої мандрівниці відбулося сьогодні.'::text,'повернення'::text,'повернення'::text,'повернення'::text,'Подруго, я чула, що повернення нашої улюбленої мандрівниці відбулося сьогодні.'::text),
(380733,42304,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tía, yo he oído que ... de nuestra viajera favorita fue hoy.'::text,'el regreso'::text,'un regreso'::text,'regreso'::text,'Tía, yo he oído que el regreso de nuestra viajera favorita fue hoy.'::text),
(380732,42304,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Meuf, j''ai entendu dire que ... de notre voyageuse préférée a eu lieu aujourd''hui.'::text,'le retour'::text,'un retour'::text,'retour'::text,'Meuf, j''ai entendu dire que le retour de notre voyageuse préférée a eu lieu aujourd''hui.'::text),
(380735,42304,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, ben duydum ki en sevdiğimiz gezginin ... bugün gerçekleşmiş.'::text,'dönüşü'::text,'bir dönüşü'::text,'dönüşü'::text,'Kızım, ben duydum ki en sevdiğimiz gezginin dönüşü bugün gerçekleşmiş.'::text),
