(378378,42042,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A vasúti peron tele van boldog emberekkel, ...?'::text,'nem igaz'::text,'ugye'::text,'igaz'::text,'A vasúti peron tele van boldog emberekkel, nem igaz?'::text),
(378444,42050,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Später bestritt sie, dass sie den Bahnsteig entlang ..., was natürlich total glaubwürdig war.'::text,'gerannt ist'::text,'zu rennen'::text,'rannte'::text,'Später bestritt sie, dass sie den Bahnsteig entlang gerannt ist, was natürlich total glaubwürdig war.'::text),
(378448,42050,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Пізніше вона заперечила, що ... по залізничній платформі, що було, звісно, дуже правдоподібно.'::text,'бігла'::text,'бігти'::text,'бігла'::text,'Пізніше вона заперечила, що бігла по залізничній платформі, що було, звісно, дуже правдоподібно.'::text),
(378447,42050,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Más tarde ella negó ... por el andén, lo cual era claramente muy creíble.'::text,'haber corrido'::text,'correr'::text,'que corrió'::text,'Más tarde ella negó haber corrido por el andén, lo cual era claramente muy creíble.'::text),
