(393294,43700,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Spaziergang, ... du über den Blumenmarkt gemacht hast? Ziemlich perfekt.'::text,'den'::text,'der'::text,'dessen'::text,'Der Spaziergang, den du über den Blumenmarkt gemacht hast? Ziemlich perfekt.'::text),
(393298,43700,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Прогулянка, ... ти зробила квітковим ринком? Майже ідеальна.'::text,'яку'::text,'хто'::text,'чия'::text,'Прогулянка, яку ти зробила квітковим ринком? Майже ідеальна.'::text),
(393297,43700,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¿El paseo ... tú diste por el mercado de flores? Bastante perfecto.'::text,'que'::text,'quien'::text,'cuyo'::text,'¿El paseo que tú diste por el mercado de flores? Bastante perfecto.'::text),
