(393299,43700,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Çiçek pazarında ... senin yaptığın yürüyüş mü? Resmen mükemmel.'::text,''::text,NULL::text,NULL::text,'Çiçek pazarında senin yaptığın yürüyüş mü? Resmen mükemmel.'::text),
(393300,43700,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A séta, ... te a virágpiacon tettél? Elég tökéletes.'::text,'amit'::text,'aki'::text,'akinek a'::text,'A séta, amit te a virágpiacon tettél? Elég tökéletes.'::text),
(393330,43704,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gerade ... sie ihren Spaziergang auf einem Dach über der Stadt.'::text,'beendet'::text,'beendet'::text,'hat beendet'::text,'Gerade beendet sie ihren Spaziergang auf einem Dach über der Stadt.'::text),
(393334,43704,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Саме зараз вона ... свою прогулянку на даху над містом.'::text,'завершує'::text,'завершує'::text,'завершила'::text,'Саме зараз вона завершує свою прогулянку на даху над містом.'::text),
(393333,43704,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ahora mismo ella ... su paseo en una azotea sobre la ciudad.'::text,'está terminando'::text,'termina'::text,'ha terminado'::text,'Ahora mismo ella está terminando su paseo en una azotea sobre la ciudad.'::text),
(393332,43704,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En ce moment, elle ... sa balade sur un toit au-dessus de la ville.'::text,'est en train de finir'::text,'finit'::text,'a fini'::text,'En ce moment, elle est en train de finir sa balade sur un toit au-dessus de la ville.'::text),
(393335,43704,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Şu anda o, şehrin üstündeki bir çatıda yürüyüşünü ...'::text,'bitiriyor'::text,'bitirir'::text,'bitirdi'::text,'Şu anda o, şehrin üstündeki bir çatıda yürüyüşünü bitiriyor.'::text),
(393336,43704,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Éppen most ő ... a sétáját egy tetőn a város felett.'::text,'fejezi be'::text,'befejezi'::text,'befejezte'::text,'Éppen most ő fejezi be a sétáját egy tetőn a város felett.'::text),
(382125,42459,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mein Mitbewohner hat bei Schere-Stein-Papier verloren, also ... er den Müll raus! Absoluter Verrat!'::text,'brachte'::text,'brachte gerade'::text,'hat gebracht'::text,'Mein Mitbewohner hat bei Schere-Stein-Papier verloren, also brachte er den Müll raus! Absoluter Verrat!'::text),
(382129,42459,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Мій сусід по кімнаті програв у камінь-ножиці-папір, тож він ... сміття! Абсолютна зрада!'::text,'виніс'::text,'виносив'::text,'виніс'::text,'Мій сусід по кімнаті програв у камінь-ножиці-папір, тож він виніс сміття! Абсолютна зрада!'::text),
(382128,42459,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Mi compañero de piso perdió a piedra, papel o tijera, así que él ... la basura! ¡Traición total!'::text,'sacó'::text,'estaba sacando'::text,'ha sacado'::text,'¡Mi compañero de piso perdió a piedra, papel o tijera, así que él sacó la basura! ¡Traición total!'::text),
(382127,42459,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mon coloc a perdu à pierre-feuille-ciseaux, donc il ... la poubelle ! Trahison totale !'::text,'a sorti'::text,'sortait'::text,'a sorti'::text,'Mon coloc a perdu à pierre-feuille-ciseaux, donc il a sorti la poubelle ! Trahison totale !'::text),
(382130,42459,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oda arkadaşım taş-kağıt-makasta kaybetti, o yüzden çöpü o ...! Tam bir ihanet!'::text,'çıkardı'::text,'çıkarıyordu'::text,'çıkarmış'::text,'Oda arkadaşım taş-kağıt-makasta kaybetti, o yüzden çöpü o çıkardı! Tam bir ihanet!'::text),
(382131,42459,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A lakótársam vesztett kő-papír-ollóban, így ő ... a szemetet! Totális árulás!'::text,'vitte ki'::text,'vitte ki éppen'::text,'kivitte'::text,'A lakótársam vesztett kő-papír-ollóban, így ő vitte ki a szemetet! Totális árulás!'::text),
(340572,37842,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Heute Morgen hat der Gärtner bisher sechs Rosen mit der alten Eisenschere ...'::text,'abgeschnitten'::text,'geschnitten'::text,'am Schneiden'::text,'Heute Morgen hat der Gärtner bisher sechs Rosen mit der alten Eisenschere abgeschnitten.'::text),
(340576,37842,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Цього ранку садівник уже ... шість троянд старими залізними ножицями.'::text,'зрізав'::text,'зрізав'::text,'зрізає'::text,'Цього ранку садівник уже зрізав шість троянд старими залізними ножицями.'::text),
(340575,37842,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En lo que va de mañana, el jardinero ... seis rosas con las viejas tijeras de hierro.'::text,'ha cortado'::text,'ha estado cortando'::text,'está cortando'::text,'En lo que va de mañana, el jardinero ha cortado seis rosas con las viejas tijeras de hierro.'::text),
