(340577,37842,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu sabah şimdiye kadar bahçıvan eski demir makasla altı gül ...'::text,'kesti'::text,'kesip duruyor'::text,'kesiyor'::text,'Bu sabah şimdiye kadar bahçıvan eski demir makasla altı gül kesti.'::text),
(340578,37842,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ma reggel eddig a kertész ... hat rózsát a régi vasollóval.'::text,'vágott le'::text,'vágott le'::text,'vág le'::text,'Ma reggel eddig a kertész vágott le hat rózsát a régi vasollóval.'::text),
(402906,44768,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Während der Wanderer den gewundenen Pfad entlang ..., kreisten Vögel über dem See.'::text,'ging'::text,'ging'::text,'gegangen ist'::text,'Während der Wanderer den gewundenen Pfad entlang ging, kreisten Vögel über dem See.'::text),
(402910,44768,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Поки мандрівник ... звивистою стежкою, птахи кружляли над озером.'::text,'ішов'::text,'пройшов'::text,'пройшов'::text,'Поки мандрівник ішов звивистою стежкою, птахи кружляли над озером.'::text),
(402909,44768,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mientras el viajero ... por el sendero sinuoso, unos pájaros volaban en círculos sobre el lago.'::text,'caminaba'::text,'caminó'::text,'ha caminado'::text,'Mientras el viajero caminaba por el sendero sinuoso, unos pájaros volaban en círculos sobre el lago.'::text),
(402908,44768,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Pendant que le voyageur ... le long du sentier sinueux, des oiseaux tournaient au-dessus du lac.'::text,'marchait'::text,'a marché'::text,'a marché'::text,'Pendant que le voyageur marchait le long du sentier sinueux, des oiseaux tournaient au-dessus du lac.'::text),
(402911,44768,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gezgin kıvrımlı patikada ..., kuşlar gölün üzerinde daireler çiziyordu.'::text,'yürürken'::text,'yürüdüğünde'::text,'yürümüşken'::text,'Gezgin kıvrımlı patikada yürürken, kuşlar gölün üzerinde daireler çiziyordu.'::text),
(402912,44768,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Miközben az utazó a kanyargós ösvényen ..., madarak köröztek a tó felett.'::text,'sétált'::text,'végigsétált'::text,'végigsétált'::text,'Miközben az utazó a kanyargós ösvényen sétált, madarak köröztek a tó felett.'::text),
(392106,43568,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Du liebst diese steilen Stufen, und ehrlich gesagt ...'::text,'ich auch'::text,'ich auch'::text,'ich auch nicht'::text,'Du liebst diese steilen Stufen, und ehrlich gesagt ich auch.'::text),
(392110,43568,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ти обожнюєш ці круті сходи, і, чесно, ...'::text,'я теж'::text,'я теж'::text,'я теж ні'::text,'Ти обожнюєш ці круті сходи, і, чесно, я теж.'::text),
(392109,43568,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Te encantan estas escaleras empinadas y, sinceramente, ...'::text,'a mí también'::text,'a mí también'::text,'a mí tampoco'::text,'Te encantan estas escaleras empinadas y, sinceramente, a mí también.'::text),
(392108,43568,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tu adores ces marches raides et, franchement, ...'::text,'moi aussi'::text,'moi aussi'::text,'moi non plus'::text,'Tu adores ces marches raides et, franchement, moi aussi.'::text),
(392111,43568,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sen bu dik basamakları seviyorsun ve açıkçası ...'::text,'ben de'::text,'ben de'::text,'ben de sevmiyorum'::text,'Sen bu dik basamakları seviyorsun ve açıkçası ben de.'::text),
(392112,43568,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Te imádod ezeket a meredek lépcsőket, és őszintén ...'::text,'én is'::text,'én is'::text,'én sem'::text,'Te imádod ezeket a meredek lépcsőket, és őszintén én is.'::text),
(392124,43570,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis Mittag wird sie jede einzelne Stufe am Berg ..., ein leicht fauler Tag.'::text,'erklommen haben'::text,'erklimmen'::text,'am Erklimmen sein'::text,'Bis Mittag wird sie jede einzelne Stufe am Berg erklommen haben, ein leicht fauler Tag.'::text),
(392128,43570,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До полудня вона ... кожну сходинку на горі, трохи лінивий день.'::text,'вже подолає'::text,'подолає'::text,'долатиме'::text,'До полудня вона вже подолає кожну сходинку на горі, трохи лінивий день.'::text),
(392127,43570,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para el mediodía, ella ... cada escalón de la montaña, un día un poco vago.'::text,'habrá subido'::text,'subirá'::text,'estará subiendo'::text,'Para el mediodía, ella habrá subido cada escalón de la montaña, un día un poco vago.'::text),
(392126,43570,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici midi, elle ... chaque marche de la montagne, une journée légèrement paresseuse.'::text,'aura gravi'::text,'gravira'::text,'sera en train de gravir'::text,'D''ici midi, elle aura gravi chaque marche de la montagne, une journée légèrement paresseuse.'::text),
(392129,43570,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Öğlene kadar o dağdaki her bir basamağı ..., biraz tembel bir gün.'::text,'çıkmış olacak'::text,'çıkacak'::text,'çıkıyor olacak'::text,'Öğlene kadar o dağdaki her bir basamağı çıkmış olacak, biraz tembel bir gün.'::text),
(392130,43570,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Délre ő ... a hegy minden egyes lépcsőfokát, egy enyhén lusta nap.'::text,'már megmássza'::text,'meg fogja mászni'::text,'mászni fogja'::text,'Délre ő már megmássza a hegy minden egyes lépcsőfokát, egy enyhén lusta nap.'::text),
(382422,42492,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Natürlich ließ sie die Route auf einer Karte ..., nur für den Fall, dass sie ihren eigenen Plan vergisst.'::text,'einzeichnen'::text,'einzeichnen'::text,'einzuzeichnen'::text,'Natürlich ließ sie die Route auf einer Karte einzeichnen, nur für den Fall, dass sie ihren eigenen Plan vergisst.'::text),
(382426,42492,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Звісно, вона попросила, щоб їй ... маршрут на карті, на випадок, якщо вона забуде власний план.'::text,'намалювали'::text,'намалювати'::text,'намалювати'::text,'Звісно, вона попросила, щоб їй намалювали маршрут на карті, на випадок, якщо вона забуде власний план.'::text),
(382425,42492,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Obviamente, ella mandó ... la ruta en un mapa, por si se le olvidaba su propio plan.'::text,'dibujar'::text,'dibujar'::text,'dibujar'::text,'Obviamente, ella mandó dibujar la ruta en un mapa, por si se le olvidaba su propio plan.'::text),
(382424,42492,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Évidemment, elle a fait ... l''itinéraire sur une carte, au cas où elle oublierait son propre plan.'::text,'dessiner'::text,'dessiner'::text,'dessiner'::text,'Évidemment, elle a fait dessiner l''itinéraire sur une carte, au cas où elle oublierait son propre plan.'::text),
(382427,42492,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tabii ki o, kendi planını unutursa diye rotayı bir haritaya ...'::text,'çizdirdi'::text,'çizdirdi'::text,'çizdirmek'::text,'Tabii ki o, kendi planını unutursa diye rotayı bir haritaya çizdirdi.'::text),
(382428,42492,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Persze ő ... az útvonalat egy térképre, arra az esetre, ha elfelejtené a saját tervét.'::text,'felrajzoltatta'::text,'felrajzoltatta'::text,'felrajzoltatni'::text,'Persze ő felrajzoltatta az útvonalat egy térképre, arra az esetre, ha elfelejtené a saját tervét.'::text),
(338538,37616,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... neben den Waggons her, als der Zug losfuhr.'::text,'rannte'::text,'rannte'::text,'ist gerannt'::text,'Er rannte neben den Waggons her, als der Zug losfuhr.'::text),
(338542,37616,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він ... поруч із вагонами, коли потяг рушив.'::text,'біг'::text,'пробіг'::text,'пробіг'::text,'Він біг поруч із вагонами, коли потяг рушив.'::text),
(338541,37616,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Él ... junto a los vagones cuando el tren empezó a moverse.'::text,'estaba corriendo'::text,'corrió'::text,'ha corrido'::text,'Él estaba corriendo junto a los vagones cuando el tren empezó a moverse.'::text),
(338540,37616,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... à côté des wagons quand le train a commencé à rouler.'::text,'courait'::text,'a couru'::text,'a couru'::text,'Il courait à côté des wagons quand le train a commencé à rouler.'::text),
(338543,37616,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tren hareket etmeye başladığında o vagonların yanında ...'::text,'koşuyordu'::text,'koştu'::text,'koşmuş'::text,'Tren hareket etmeye başladığında o vagonların yanında koşuyordu.'::text),
(338544,37616,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő ... a kocsik mellett, amikor a vonat elindult.'::text,'futott'::text,'elfutott'::text,'elfutott'::text,'Ő futott a kocsik mellett, amikor a vonat elindult.'::text),
(338619,37625,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... der Zug schon fuhr, kletterte er in den Waggon.'::text,'Obwohl'::text,'Trotz'::text,'Ungeachtet'::text,'Obwohl der Zug schon fuhr, kletterte er in den Waggon.'::text),
(338623,37625,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... потяг уже рухався, він заліз у вагон.'::text,'Хоча'::text,'Попри'::text,'Незважаючи на'::text,'Хоча потяг уже рухався, він заліз у вагон.'::text),
(338622,37625,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... el tren ya estaba en marcha, él se subió al vagón.'::text,'Aunque'::text,'A pesar de'::text,'Pese a'::text,'Aunque el tren ya estaba en marcha, él se subió al vagón.'::text),
(338621,37625,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... le train roulait déjà, il est monté dans le wagon.'::text,'Même si'::text,'Malgré'::text,'En dépit de'::text,'Même si le train roulait déjà, il est monté dans le wagon.'::text),
(338624,37625,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tren zaten hareket ediyor ..., o vagona tırmandı.'::text,'olsa da'::text,'olmasına rağmen'::text,'olmasına karşın'::text,'Tren zaten hareket ediyor olsa da, o vagona tırmandı.'::text),
(338625,37625,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... a vonat már mozgott, ő felmászott a kocsiba.'::text,'Habár'::text,'Ellenére'::text,'Dacára'::text,'Habár a vonat már mozgott, ő felmászott a kocsiba.'::text),
(385230,42804,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mehrere Hunde ... ihr, weil sie vor ihnen war.'::text,'folgten'::text,'wurden gefolgt'::text,'folgend'::text,'Mehrere Hunde folgten ihr, weil sie vor ihnen war.'::text),
(385234,42804,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Кілька собак ... за нею, бо вона була перед ними.'::text,'ішли'::text,'були переслідувані'::text,'ідучи'::text,'Кілька собак ішли за нею, бо вона була перед ними.'::text),
(385233,42804,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Varios perros la ... porque ella estaba delante de ellos.'::text,'siguieron'::text,'fueron seguidos'::text,'siguiendo'::text,'Varios perros la siguieron porque ella estaba delante de ellos.'::text),
(385232,42804,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Plusieurs chiens ... parce qu''elle était devant eux.'::text,'l''ont suivie'::text,'ont été suivis'::text,'la suivant'::text,'Plusieurs chiens l''ont suivie parce qu''elle était devant eux.'::text),
(385235,42804,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Birkaç köpek onu ..., çünkü o onların önündeydi.'::text,'takip etti'::text,'takip edildi'::text,'takip ederek'::text,'Birkaç köpek onu takip etti, çünkü o onların önündeydi.'::text),
(385236,42804,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Több kutya ... őt, mert ő előttük volt.'::text,'követte'::text,'követve volt'::text,'követve'::text,'Több kutya követte őt, mert ő előttük volt.'::text),
(385239,42805,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mehrere Hunde ... der Läuferin jetzt, was typischerweise bei sozialen Arten beobachtet wird.'::text,'folgen'::text,'folgen'::text,'sind gefolgt'::text,'Mehrere Hunde folgen der Läuferin jetzt, was typischerweise bei sozialen Arten beobachtet wird.'::text),
(385243,42805,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Кілька собак зараз ... за бігункою, що типово спостерігається в соціальних видів.'::text,'біжать'::text,'бігають'::text,'побігли'::text,'Кілька собак зараз біжать за бігункою, що типово спостерігається в соціальних видів.'::text),
(385242,42805,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Varios perros ... a la corredora ahora, lo cual se observa típicamente en especies sociales.'::text,'están siguiendo'::text,'siguen'::text,'han seguido'::text,'Varios perros están siguiendo a la corredora ahora, lo cual se observa típicamente en especies sociales.'::text),
(385241,42805,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Plusieurs chiens ... la coureuse en ce moment, ce qui s''observe typiquement chez les espèces sociales.'::text,'suivent'::text,'suivent'::text,'ont suivi'::text,'Plusieurs chiens suivent la coureuse en ce moment, ce qui s''observe typiquement chez les espèces sociales.'::text),
(385244,42805,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Birkaç köpek şu anda koşucuyu ..., ki bu sosyal türlerde tipik olarak gözlemlenir.'::text,'takip ediyor'::text,'takip eder'::text,'takip etti'::text,'Birkaç köpek şu anda koşucuyu takip ediyor, ki bu sosyal türlerde tipik olarak gözlemlenir.'::text),
(385245,42805,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Több kutya most ... a futót, ami jellemzően megfigyelhető a társas fajoknál.'::text,'követi'::text,'követi'::text,'követte'::text,'Több kutya most követi a futót, ami jellemzően megfigyelhető a társas fajoknál.'::text),
(359229,39915,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Sonne ... über dem Platz, als sie eine Handvoll Schnee in die Luft warf.'::text,'schien'::text,'schien'::text,'hat geschienen'::text,'Die Sonne schien über dem Platz, als sie eine Handvoll Schnee in die Luft warf.'::text),
(359233,39915,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Сонце ... над площею, коли вона підкинула жменю снігу в повітря.'::text,'світило'::text,'засвітило'::text,'засвітило'::text,'Сонце світило над площею, коли вона підкинула жменю снігу в повітря.'::text),
(359232,39915,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El sol ... sobre la plaza cuando ella lanzó un puñado de nieve al aire.'::text,'brillaba'::text,'brilló'::text,'ha brillado'::text,'El sol brillaba sobre la plaza cuando ella lanzó un puñado de nieve al aire.'::text),
(359231,39915,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le soleil ... sur la place quand elle a lancé une poignée de neige en l''air.'::text,'brillait'::text,'brilla'::text,'a brillé'::text,'Le soleil brillait sur la place quand elle a lancé une poignée de neige en l''air.'::text),
(359234,39915,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O havaya bir avuç kar attığında güneş meydanın üzerinde ...'::text,'parlıyordu'::text,'parladı'::text,'parlamış'::text,'O havaya bir avuç kar attığında güneş meydanın üzerinde parlıyordu.'::text),
(359235,39915,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A nap ... a tér felett, amikor ő egy maréknyi havat dobott a levegőbe.'::text,'sütött'::text,'kisütött'::text,'kisütött'::text,'A nap sütött a tér felett, amikor ő egy maréknyi havat dobott a levegőbe.'::text),
(361092,40122,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Selten ... so herzliche Gastfreundschaft an einem einzigen Samowar.'::text,'genossen Gäste'::text,'Gäste genossen'::text,'genossen Gäste'::text,'Selten genossen Gäste so herzliche Gastfreundschaft an einem einzigen Samowar.'::text),
(361096,40122,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Рідко ... таку теплу гостинність біля одного самовара.'::text,'гості відчували'::text,'гості відчували'::text,'гості відчували'::text,'Рідко гості відчували таку теплу гостинність біля одного самовара.'::text),
(361095,40122,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Pocas veces ... una hospitalidad tan cálida alrededor de un solo samovar.'::text,'han disfrutado los invitados'::text,'los invitados han disfrutado'::text,'disfrutaron los invitados'::text,'Pocas veces han disfrutado los invitados una hospitalidad tan cálida alrededor de un solo samovar.'::text),
(361094,40122,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rarement ... une hospitalité aussi chaleureuse autour d''un seul samovar.'::text,'des invités ont-ils connu'::text,'des invités ont connu'::text,'des invités connurent'::text,'Rarement des invités ont-ils connu une hospitalité aussi chaleureuse autour d''un seul samovar.'::text),
(361097,40122,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Konuklar nadiren tek bir semaverin başında bu kadar sıcak bir misafirperverliğin ...'::text,'tadını çıkarmıştır'::text,'tadını çıkarmıştır'::text,'tadını çıkardı'::text,'Konuklar nadiren tek bir semaverin başında bu kadar sıcak bir misafirperverliğin tadını çıkarmıştır.'::text),
(361098,40122,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ritkán ... a vendégek ilyen meleg vendégszeretetet egyetlen szamovár körül.'::text,'élveztek'::text,'élveztek'::text,'élvezték'::text,'Ritkán élveztek a vendégek ilyen meleg vendégszeretetet egyetlen szamovár körül.'::text),
(404013,44891,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Fjord, ... die Jacht durchquert, ist von steilen Bergen umgeben.'::text,'den'::text,'der'::text,'wo'::text,'Der Fjord, den die Jacht durchquert, ist von steilen Bergen umgeben.'::text),
(404017,44891,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Фіорд, ... перетинає яхта, оточений крутими горами.'::text,'який'::text,'хто'::text,'де'::text,'Фіорд, який перетинає яхта, оточений крутими горами.'::text),
(404016,44891,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El fiordo ... cruza el yate está rodeado de montañas empinadas.'::text,'que'::text,'quien'::text,'donde'::text,'El fiordo que cruza el yate está rodeado de montañas empinadas.'::text),
(404015,44891,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le fjord ... le yacht traverse est entouré de montagnes escarpées.'::text,'que'::text,'qui'::text,'où'::text,'Le fjord que le yacht traverse est entouré de montagnes escarpées.'::text),
(404018,44891,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yatın ... geçtiği fiyort dik dağlarla çevrili.'::text,''::text,NULL::text,NULL::text,'Yatın geçtiği fiyort dik dağlarla çevrili.'::text),
(404019,44891,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A fjord, ... a jacht átszel, meredek hegyekkel van körülvéve.'::text,'amelyet'::text,'aki'::text,'ahol'::text,'A fjord, amelyet a jacht átszel, meredek hegyekkel van körülvéve.'::text),
(404067,44897,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Jacht ... schon stundenlang über den Fjord, als sie endlich vor Freude schrie!'::text,'segelte'::text,'segelte'::text,'segelte'::text,'Die Jacht segelte schon stundenlang über den Fjord, als sie endlich vor Freude schrie!'::text),
(404071,44897,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Яхта вже кілька годин ... фіордом, коли вона нарешті закричала від радості!'::text,'пливла'::text,'пливла'::text,'пливла'::text,'Яхта вже кілька годин пливла фіордом, коли вона нарешті закричала від радості!'::text),
(404070,44897,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡El yate ... por el fiordo durante horas cuando ella por fin gritó de alegría!'::text,'había estado navegando'::text,'navegó'::text,'estaba navegando'::text,'¡El yate había estado navegando por el fiordo durante horas cuando ella por fin gritó de alegría!'::text),
(404069,44897,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le yacht ... sur le fjord depuis des heures quand elle a enfin crié de joie !'::text,'naviguait'::text,'a navigué'::text,'naviguait'::text,'Le yacht naviguait sur le fjord depuis des heures quand elle a enfin crié de joie !'::text),
(404072,44897,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O sonunda sevinçle çığlık attığında yat saatlerdir fiyortta ...!'::text,'seyrediyordu'::text,'seyretti'::text,'seyrediyordu'::text,'O sonunda sevinçle çığlık attığında yat saatlerdir fiyortta seyrediyordu!'::text),
(404073,44897,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A jacht már órák óta ... a fjordon, amikor ő végre felsikoltott örömében!'::text,'hajózott'::text,'hajózott'::text,'hajózott'::text,'A jacht már órák óta hajózott a fjordon, amikor ő végre felsikoltott örömében!'::text),
(368931,40993,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Salut wird von Militäroffizieren ..., also sieht er sehr militärisch aus.'::text,'ausgeführt'::text,'ausführen'::text,'ausführend'::text,'Der Salut wird von Militäroffizieren ausgeführt, also sieht er sehr militärisch aus.'::text),
(368935,40993,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Салют ... військовими офіцерами, тому він виглядає дуже по-військовому.'::text,'віддається'::text,'віддає'::text,'віддає'::text,'Салют віддається військовими офіцерами, тому він виглядає дуже по-військовому.'::text),
(368934,40993,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El saludo ... por oficiales militares, así que parece muy militar.'::text,'es hecho'::text,'hace'::text,'está haciendo'::text,'El saludo es hecho por oficiales militares, así que parece muy militar.'::text),
(368933,40993,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le salut ... par des officiers militaires, donc ça fait très militaire.'::text,'est fait'::text,'fait'::text,'est en train de faire'::text,'Le salut est fait par des officiers militaires, donc ça fait très militaire.'::text),
(368936,40993,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Selam askeri subaylar tarafından ..., bu yüzden çok askeri görünüyor.'::text,'verilir'::text,'verir'::text,'veriyor'::text,'Selam askeri subaylar tarafından verilir, bu yüzden çok askeri görünüyor.'::text),
(368937,40993,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A tisztelgést katonatisztek ..., így nagyon katonásnak tűnik.'::text,'végzik'::text,'végzi'::text,'végzi éppen'::text,'A tisztelgést katonatisztek végzik, így nagyon katonásnak tűnik.'::text),
(378615,42069,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bestie, es heißt, dass sie morgen um diese Zeit wieder in der ersten Reihe ...'::text,'stehen wird'::text,'stehen wird'::text,'steht'::text,'Bestie, es heißt, dass sie morgen um diese Zeit wieder in der ersten Reihe stehen wird.'::text),
(378619,42069,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подружко, кажуть, завтра в цей час вона знову ... в першій шерензі.'::text,'стоятиме'::text,'стоятиме'::text,'стоїть'::text,'Подружко, кажуть, завтра в цей час вона знову стоятиме в першій шерензі.'::text),
(378618,42069,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bestie, dicen que mañana a esta hora ella ... otra vez en la primera fila.'::text,'estará formando'::text,'formará'::text,'forma'::text,'Bestie, dicen que mañana a esta hora ella estará formando otra vez en la primera fila.'::text),
(378617,42069,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ma belle, il paraît que demain à la même heure, elle ... de nouveau au premier rang.'::text,'se tiendra'::text,'se tiendra'::text,'se tient'::text,'Ma belle, il paraît que demain à la même heure, elle se tiendra de nouveau au premier rang.'::text),
(378620,42069,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, duyduğuma göre yarın bu saatte o yine ön sırada ...'::text,'duruyor olacak'::text,'duracak'::text,'duruyor'::text,'Kanka, duyduğuma göre yarın bu saatte o yine ön sırada duruyor olacak.'::text),
(378621,42069,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bestie, azt mondják, holnap ilyenkor ő megint az első sorban ...'::text,'fog állni'::text,'áll majd'::text,'áll'::text,'Bestie, azt mondják, holnap ilyenkor ő megint az első sorban fog állni.'::text),
(378687,42077,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn sich eine Frau bewegt hätte, ... die ganze Reihe komplett ruiniert gewesen!'::text,'wäre'::text,'wird'::text,'war'::text,'Wenn sich eine Frau bewegt hätte, wäre die ganze Reihe komplett ruiniert gewesen!'::text),
(378691,42077,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби одна жінка поворухнулася, уся шеренга ... повністю зіпсована!'::text,'була б'::text,'буде'::text,'була'::text,'Якби одна жінка поворухнулася, уся шеренга була б повністю зіпсована!'::text),
(378690,42077,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Si una mujer se hubiera movido, toda la fila ... completamente arruinada!'::text,'habría quedado'::text,'quedará'::text,'quedó'::text,'¡Si una mujer se hubiera movido, toda la fila habría quedado completamente arruinada!'::text),
(378689,42077,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si une femme avait bougé, toute la rangée ... complètement fichue !'::text,'aurait été'::text,'sera'::text,'était'::text,'Si une femme avait bougé, toute la rangée aurait été complètement fichue !'::text),
(378692,42077,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bir kadın kıpırdasaydı, bütün sıra tamamen ...!'::text,'mahvolmuş olurdu'::text,'mahvolacak'::text,'mahvoldu'::text,'Bir kadın kıpırdasaydı, bütün sıra tamamen mahvolmuş olurdu!'::text),
(378693,42077,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha egy nő megmozdult volna, az egész sor teljesen ...!'::text,'tönkrement volna'::text,'tönkremegy majd'::text,'tönkrement'::text,'Ha egy nő megmozdult volna, az egész sor teljesen tönkrement volna!'::text),
(338430,37604,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... gerade die letzte Frachtkiste, als ein Kran über ihr einen Container herabließ.'::text,'stempelte'::text,'stempelte ab'::text,'hat abgestempelt'::text,'Sie stempelte gerade die letzte Frachtkiste, als ein Kran über ihr einen Container herabließ.'::text),
(338434,37604,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона ... останній ящик з вантажем, коли кран опустив над нею контейнер.'::text,'штампувала'::text,'проштампувала'::text,'проштампувала'::text,'Вона штампувала останній ящик з вантажем, коли кран опустив над нею контейнер.'::text),
(338433,37604,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ella ... la última caja de carga cuando una grúa bajó un contenedor por encima.'::text,'estaba sellando'::text,'selló'::text,'ha sellado'::text,'Ella estaba sellando la última caja de carga cuando una grúa bajó un contenedor por encima.'::text),
(338432,37604,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ... la dernière caisse de fret quand une grue a descendu un conteneur au-dessus d''elle.'::text,'tamponnait'::text,'a tamponné'::text,'a tamponné'::text,'Elle tamponnait la dernière caisse de fret quand une grue a descendu un conteneur au-dessus d''elle.'::text),
(338435,37604,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bir vinç başının üstünden bir konteyner indirdiğinde o son kargo sandığını ...'::text,'damgalıyordu'::text,'damgaladı'::text,'damgalamış'::text,'Bir vinç başının üstünden bir konteyner indirdiğinde o son kargo sandığını damgalıyordu.'::text),
(338436,37604,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő éppen ... az utolsó rakományládát, amikor egy daru leeresztett felette egy konténert.'::text,'pecsételte'::text,'lepecsételte'::text,'lepecsételte'::text,'Ő éppen pecsételte az utolsó rakományládát, amikor egy daru leeresztett felette egy konténert.'::text),
(348042,38672,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Als die Sonne unterging, ... er erst die Hälfte der Strecke zur Stadt gegangen.'::text,'war'::text,'ist'::text,'geht'::text,'Als die Sonne unterging, war er erst die Hälfte der Strecke zur Stadt gegangen.'::text),
(348046,38672,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коли сонце сіло, він ... лише половину відстані до міста.'::text,'пройшов'::text,'пройшов'::text,'проходить'::text,'Коли сонце сіло, він пройшов лише половину відстані до міста.'::text),
(348045,38672,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para cuando se puso el sol, él ... solo la mitad de la distancia hasta la ciudad.'::text,'había recorrido'::text,'ha recorrido'::text,'recorre'::text,'Para cuando se puso el sol, él había recorrido solo la mitad de la distancia hasta la ciudad.'::text),
(348044,38672,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Au moment où le soleil s''est couché, il ... seulement la moitié de la distance jusqu''à la ville.'::text,'avait parcouru'::text,'a parcouru'::text,'parcourt'::text,'Au moment où le soleil s''est couché, il avait parcouru seulement la moitié de la distance jusqu''à la ville.'::text),
(348047,38672,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Güneş battığında o şehre olan mesafenin sadece yarısını ...'::text,'yürümüştü'::text,'yürüdü'::text,'yürüyor'::text,'Güneş battığında o şehre olan mesafenin sadece yarısını yürümüştü.'::text),
(348048,38672,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mire lement a nap, ő a városig tartó távnak csak a felét ...'::text,'tette meg'::text,'tette meg'::text,'teszi meg'::text,'Mire lement a nap, ő a városig tartó távnak csak a felét tette meg.'::text),
(349491,38833,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn der Wind stark ..., bewegt sich der Sand auf der Düne.'::text,'weht'::text,'wehen wird'::text,'wehte'::text,'Wenn der Wind stark weht, bewegt sich der Sand auf der Düne.'::text),
(349495,38833,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо вітер ... сильно, пісок на дюні рухається.'::text,'дме'::text,'дутиме'::text,'дув'::text,'Якщо вітер дме сильно, пісок на дюні рухається.'::text),
(349494,38833,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si el viento ... fuerte, la arena de la duna se mueve.'::text,'sopla'::text,'soplará'::text,'sopló'::text,'Si el viento sopla fuerte, la arena de la duna se mueve.'::text),
(349493,38833,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si le vent ... fort, le sable de la dune bouge.'::text,'souffle'::text,'soufflera'::text,'soufflait'::text,'Si le vent souffle fort, le sable de la dune bouge.'::text),
(349496,38833,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rüzgâr sert ..., kumuldaki kum hareket eder.'::text,'eserse'::text,'esecekse'::text,'estiyse'::text,'Rüzgâr sert eserse, kumuldaki kum hareket eder.'::text),
(349497,38833,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a szél erősen ..., a homok mozog a dűnén.'::text,'fúj'::text,'fújni fog'::text,'fújt'::text,'Ha a szél erősen fúj, a homok mozog a dűnén.'::text),
(349527,38837,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... eine Stunde lang auf der Düne, bevor er zu den gemeißelten Felsen ging.'::text,'filmte'::text,'filmt schon'::text,'filmt gerade'::text,'Er filmte eine Stunde lang auf der Düne, bevor er zu den gemeißelten Felsen ging.'::text),
(349531,38837,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він ... на дюні годину, перш ніж пішов до різьблених скель.'::text,'знімав'::text,'знімає'::text,'знімає'::text,'Він знімав на дюні годину, перш ніж пішов до різьблених скель.'::text),
(349530,38837,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Él ... en la duna durante una hora antes de ir hasta las rocas talladas.'::text,'había estado grabando'::text,'ha estado grabando'::text,'está grabando'::text,'Él había estado grabando en la duna durante una hora antes de ir hasta las rocas talladas.'::text),
(349529,38837,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... sur la dune pendant une heure avant de marcher vers les rochers sculptés.'::text,'avait filmé'::text,'a filmé'::text,'filme'::text,'Il avait filmé sur la dune pendant une heure avant de marcher vers les rochers sculptés.'::text),
(349532,38837,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O oyma kayalara yürümeden önce bir saat boyunca kumulda ...'::text,'çekim yapıyordu'::text,'çekim yapıyor'::text,'çekim yapıyor'::text,'O oyma kayalara yürümeden önce bir saat boyunca kumulda çekim yapıyordu.'::text),
(349533,38837,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő egy órán át ... a dűnén, mielőtt a faragott sziklákhoz sétált.'::text,'filmezett'::text,'filmez'::text,'filmez'::text,'Ő egy órán át filmezett a dűnén, mielőtt a faragott sziklákhoz sétált.'::text),
(379929,42215,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Falkner ... die Freilassung des Falken schon seit Wochen.'::text,'plant'::text,'hat geplant'::text,'plant gerade'::text,'Der Falkner plant die Freilassung des Falken schon seit Wochen.'::text),
(379933,42215,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Сокольник ... випуск сокола вже кілька тижнів.'::text,'планує'::text,'спланував'::text,'планує'::text,'Сокольник планує випуск сокола вже кілька тижнів.'::text),
(379932,42215,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El halconero ... la suelta del halcón durante semanas.'::text,'ha estado planeando'::text,'ha planeado'::text,'está planeando'::text,'El halconero ha estado planeando la suelta del halcón durante semanas.'::text),
(379931,42215,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le fauconnier ... la libération du faucon depuis des semaines.'::text,'prépare'::text,'a préparé'::text,'est en train de préparer'::text,'Le fauconnier prépare la libération du faucon depuis des semaines.'::text),
(379934,42215,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Şahinci haftalardır şahinin salınmasını ...'::text,'planlıyor'::text,'planladı'::text,'planlıyor'::text,'Şahinci haftalardır şahinin salınmasını planlıyor.'::text),
(379935,42215,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A solymász hetek óta ... a sólyom szabadon engedését.'::text,'tervezi'::text,'megtervezte'::text,'tervezi'::text,'A solymász hetek óta tervezi a sólyom szabadon engedését.'::text),
(403050,44784,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Du bist unter diesen breiten Flügeln ruhig geblieben, und ehrlich gesagt ...'::text,'der Falke auch'::text,'der Falke auch'::text,'der Falke auch'::text,'Du bist unter diesen breiten Flügeln ruhig geblieben, und ehrlich gesagt der Falke auch.'::text),
(403054,44784,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ти залишався спокійним під цими широкими крилами, і, чесно, ...'::text,'сокіл теж'::text,'сокіл теж'::text,'сокіл теж'::text,'Ти залишався спокійним під цими широкими крилами, і, чесно, сокіл теж.'::text),
(403053,44784,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tú mantuviste la calma bajo esas alas enormes y, sinceramente, ...'::text,'el halcón también'::text,'el halcón también'::text,'el halcón también'::text,'Tú mantuviste la calma bajo esas alas enormes y, sinceramente, el halcón también.'::text),
(403052,44784,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tu es resté calme sous ces grandes ailes et, franchement, ...'::text,'le faucon aussi'::text,'le faucon aussi'::text,'le faucon aussi'::text,'Tu es resté calme sous ces grandes ailes et, franchement, le faucon aussi.'::text),
(403055,44784,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sen o geniş kanatların altında sakin kaldın ve açıkçası ...'::text,'şahin de'::text,'şahin de'::text,'şahin de'::text,'Sen o geniş kanatların altında sakin kaldın ve açıkçası şahin de.'::text),
(403056,44784,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Te nyugodt maradtál azok alatt a széles szárnyak alatt, és őszintén ...'::text,'a sólyom is'::text,'a sólyom is'::text,'a sólyom is'::text,'Te nyugodt maradtál azok alatt a széles szárnyak alatt, és őszintén a sólyom is.'::text),
(403140,44794,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Süße, er hat mir erzählt, dass der Falke bis nächsten Sommer in 100 Shows seine Flügel ...'::text,'ausgebreitet haben wird'::text,'ausbreiten wird'::text,'ausbreitet'::text,'Süße, er hat mir erzählt, dass der Falke bis nächsten Sommer in 100 Shows seine Flügel ausgebreitet haben wird.'::text),
(403144,44794,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, він сказав мені, що до наступного літа сокіл ... крила в 100 шоу.'::text,'розправить'::text,'розправить'::text,'розправляє'::text,'Подруго, він сказав мені, що до наступного літа сокіл розправить крила в 100 шоу.'::text),
(403143,44794,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tía, él me dijo que para el próximo verano el halcón ... las alas en 100 espectáculos.'::text,'habrá extendido'::text,'extenderá'::text,'extiende'::text,'Tía, él me dijo que para el próximo verano el halcón habrá extendido las alas en 100 espectáculos.'::text),
(403142,44794,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Meuf, il m''a dit que d''ici l''été prochain, le faucon ... ses ailes dans 100 spectacles.'::text,'aura déployé'::text,'déploiera'::text,'déploie'::text,'Meuf, il m''a dit que d''ici l''été prochain, le faucon aura déployé ses ailes dans 100 spectacles.'::text),
(403145,44794,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, o bana şahinin gelecek yaza kadar 100 gösteride kanatlarını ... söyledi.'::text,'açmış olacağını'::text,'açacağını'::text,'açtığını'::text,'Kızım, o bana şahinin gelecek yaza kadar 100 gösteride kanatlarını açmış olacağını söyledi.'::text),
(403146,44794,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, ő azt mondta nekem, hogy jövő nyárig a sólyom 100 műsorban ... a szárnyait.'::text,'kitárja majd'::text,'ki fogja tárni'::text,'kitárja'::text,'Csajszi, ő azt mondta nekem, hogy jövő nyárig a sólyom 100 műsorban kitárja majd a szárnyait.'::text),
(339150,37684,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'In fünf Minuten wird die Frau immer noch in der leuchtenden Kammer ...'::text,'liegen'::text,'sich hinlegen'::text,'liegt'::text,'In fünf Minuten wird die Frau immer noch in der leuchtenden Kammer liegen.'::text),
(339154,37684,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Через п''ять хвилин жінка ... все ще всередині сяючої камери.'::text,'лежатиме'::text,'ляже'::text,'лежить'::text,'Через п''ять хвилин жінка лежатиме все ще всередині сяючої камери.'::text),
(339153,37684,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dentro de cinco minutos, la mujer ... todavía dentro de la cámara brillante.'::text,'estará tumbada'::text,'se tumbará'::text,'está tumbada'::text,'Dentro de cinco minutos, la mujer estará tumbada todavía dentro de la cámara brillante.'::text),
(339152,37684,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dans cinq minutes, la femme ... toujours dans la chambre lumineuse.'::text,'sera allongée'::text,'s''allongera'::text,'est allongée'::text,'Dans cinq minutes, la femme sera allongée toujours dans la chambre lumineuse.'::text),
(339155,37684,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Beş dakika sonra kadın hâlâ parlayan odanın içinde ...'::text,'yatıyor olacak'::text,'yatacak'::text,'yatıyor'::text,'Beş dakika sonra kadın hâlâ parlayan odanın içinde yatıyor olacak.'::text),
(339156,37684,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Öt perc múlva a nő még mindig a világító kamrában ...'::text,'fog feküdni'::text,'fekszik majd'::text,'fekszik'::text,'Öt perc múlva a nő még mindig a világító kamrában fog feküdni.'::text),
(350094,38900,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Jedes andere Outfit ist ruiniert! Dieser Morgenmantel ist absolut elegant, ...?'::text,'nicht wahr'::text,'oder'::text,'war er nicht'::text,'Jedes andere Outfit ist ruiniert! Dieser Morgenmantel ist absolut elegant, nicht wahr?'::text),
(350098,38900,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Кожен інший образ зіпсований! Цей халат абсолютно елегантний, ...?'::text,'чи не так'::text,'хіба ні'::text,'чи не був'::text,'Кожен інший образ зіпсований! Цей халат абсолютно елегантний, чи не так?'::text),
(350097,38900,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Cualquier otro conjunto queda arruinado! Esa bata es absolutamente elegante, ¿...?'::text,'verdad'::text,'no'::text,'no era'::text,'¡Cualquier otro conjunto queda arruinado! Esa bata es absolutamente elegante, ¿verdad?'::text),
(350096,38900,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Toutes les autres tenues sont gâchées ! Ce peignoir est absolument élégant, ... ?'::text,'n''est-ce pas'::text,'non'::text,'n''était-ce pas'::text,'Toutes les autres tenues sont gâchées ! Ce peignoir est absolument élégant, n''est-ce pas ?'::text),
(350099,38900,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Diğer bütün kombinler mahvoldu! O sabahlık kesinlikle çok zarif, ...?'::text,'değil mi'::text,'değil mi'::text,'değil miydi'::text,'Diğer bütün kombinler mahvoldu! O sabahlık kesinlikle çok zarif, değil mi?'::text),
(350100,38900,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Minden más szett tönkrement! Az a köntös abszolút elegáns, ...?'::text,'nem igaz'::text,'ugye'::text,'nem volt az'::text,'Minden más szett tönkrement! Az a köntös abszolút elegáns, nem igaz?'::text),
(350112,38902,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ok also, anscheinend ... sie stundenlang Parfüms, bevor sie das elegante gefunden hat.'::text,'testete'::text,'testet'::text,'testete gerade'::text,'Ok also, anscheinend testete sie stundenlang Parfüms, bevor sie das elegante gefunden hat.'::text),
(350116,38902,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Отже, кажуть, вона ... парфуми годинами, перш ніж знайшла ті елегантні.'::text,'тестувала'::text,'тестує'::text,'тестувала'::text,'Отже, кажуть, вона тестувала парфуми годинами, перш ніж знайшла ті елегантні.'::text),
(350115,38902,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Vale, pues al parecer ella ... perfumes durante horas antes de encontrar ese tan elegante.'::text,'había estado probando'::text,'ha estado probando'::text,'estaba probando'::text,'Vale, pues al parecer ella había estado probando perfumes durante horas antes de encontrar ese tan elegante.'::text),
(350114,38902,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ok alors, apparemment elle ... des parfums pendant des heures avant de trouver ce parfum élégant.'::text,'avait testé'::text,'a testé'::text,'testait'::text,'Ok alors, apparemment elle avait testé des parfums pendant des heures avant de trouver ce parfum élégant.'::text),
(350117,38902,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tamam, duyduğuma göre o, o zarif parfümü bulmadan önce saatlerce parfüm ...'::text,'denemiş'::text,'deniyor'::text,'deniyordu'::text,'Tamam, duyduğuma göre o, o zarif parfümü bulmadan önce saatlerce parfüm denemiş.'::text),
(350118,38902,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oké, szóval állítólag ő órákig ... parfümöket, mielőtt megtalálta azt az elegánsat.'::text,'tesztelt'::text,'tesztel'::text,'tesztelt'::text,'Oké, szóval állítólag ő órákig tesztelt parfümöket, mielőtt megtalálta azt az elegánsat.'::text),
(383844,42650,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn sie weniger Termine einplanen würde, ... sie mehr Freizeit.'::text,'hätte'::text,'wird haben'::text,'hat'::text,'Wenn sie weniger Termine einplanen würde, hätte sie mehr Freizeit.'::text),
(383848,42650,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби вона планувала менше подій, вона ... більше вільного часу.'::text,'мала б'::text,'матиме'::text,'має'::text,'Якби вона планувала менше подій, вона мала б більше вільного часу.'::text),
(383847,42650,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si programara menos eventos, ella ... más tiempo libre.'::text,'tendría'::text,'tendrá'::text,'tiene'::text,'Si programara menos eventos, ella tendría más tiempo libre.'::text),
(383846,42650,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si elle planifiait moins d''événements, elle ... plus de temps libre.'::text,'aurait'::text,'aura'::text,'a'::text,'Si elle planifiait moins d''événements, elle aurait plus de temps libre.'::text),
(383849,42650,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Daha az etkinlik planlasa, o daha fazla boş zamana ...'::text,'sahip olurdu'::text,'sahip olacak'::text,'sahip'::text,'Daha az etkinlik planlasa, o daha fazla boş zamana sahip olurdu.'::text),
(383850,42650,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha kevesebb programot tervezne be, ő ... több szabad idővel.'::text,'rendelkezne'::text,'rendelkezni fog'::text,'rendelkezik'::text,'Ha kevesebb programot tervezne be, ő rendelkezne több szabad idővel.'::text),
(339933,37771,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie denken, dass die lila Chemikalie bald aus dem Kolben ...'::text,'sprudeln wird'::text,'am Sprudeln sein wird'::text,'sprudelt'::text,'Sie denken, dass die lila Chemikalie bald aus dem Kolben sprudeln wird.'::text),
(339937,37771,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вони думають, що фіолетова хімічна речовина скоро ... з колби.'::text,'вибулькне'::text,'булькотітиме'::text,'булькоче'::text,'Вони думають, що фіолетова хімічна речовина скоро вибулькне з колби.'::text),
(339936,37771,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ellos creen que la sustancia química morada pronto ... del matraz.'::text,'burbujeará'::text,'estará burbujeando'::text,'está burbujeando'::text,'Ellos creen que la sustancia química morada pronto burbujeará del matraz.'::text),
(339935,37771,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ils pensent que le produit chimique violet ... bientôt hors du flacon.'::text,'bouillonnera'::text,'sera en train de bouillonner'::text,'bouillonne'::text,'Ils pensent que le produit chimique violet bouillonnera bientôt hors du flacon.'::text),
(339938,37771,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Onlar mor kimyasalın yakında şişeden köpürerek ... düşünüyor.'::text,'taşacağını'::text,'taşıyor olacağını'::text,'taştığını'::text,'Onlar mor kimyasalın yakında şişeden köpürerek taşacağını düşünüyor.'::text),
(339939,37771,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ők azt gondolják, hogy a lila vegyszer hamarosan ... a lombikból.'::text,'kibugyog majd'::text,'bugyogni fog'::text,'kibugyog'::text,'Ők azt gondolják, hogy a lila vegyszer hamarosan kibugyog majd a lombikból.'::text),
(354243,39361,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Süße, anscheinend ... sie gerade den Kolben über der Heizplatte, als ihr Kollege rüberkam.'::text,'schwenkte'::text,'schwenkte'::text,'hat geschwenkt'::text,'Süße, anscheinend schwenkte sie gerade den Kolben über der Heizplatte, als ihr Kollege rüberkam.'::text),
(354247,39361,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, кажуть, вона ... колбу над плиткою, коли підійшов її колега.'::text,'крутила'::text,'крутнула'::text,'крутнула'::text,'Подруго, кажуть, вона крутила колбу над плиткою, коли підійшов її колега.'::text),
(354246,39361,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tía, al parecer ella ... el matraz sobre la placa cuando se acercó su compañero.'::text,'estaba agitando'::text,'agitó'::text,'ha agitado'::text,'Tía, al parecer ella estaba agitando el matraz sobre la placa cuando se acercó su compañero.'::text),
(354245,39361,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Meuf, apparemment elle ... le flacon au-dessus de la plaque chauffante quand son collègue est arrivé.'::text,'faisait tourner'::text,'a fait tourner'::text,'a fait tourner'::text,'Meuf, apparemment elle faisait tourner le flacon au-dessus de la plaque chauffante quand son collègue est arrivé.'::text),
(354248,39361,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, duyduğuma göre iş arkadaşı geldiğinde o şişeyi ocağın üstünde ...'::text,'çalkalıyormuş'::text,'çalkaladı'::text,'çalkalamış'::text,'Kızım, duyduğuma göre iş arkadaşı geldiğinde o şişeyi ocağın üstünde çalkalıyormuş.'::text),
(354249,39361,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, állítólag ő éppen ... a lombikot a főzőlap felett, amikor odajött a kollégája.'::text,'forgatta'::text,'megforgatta'::text,'megforgatta'::text,'Csajszi, állítólag ő éppen forgatta a lombikot a főzőlap felett, amikor odajött a kollégája.'::text),
(354288,39366,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Laborleitung ließ vor dem Audit 50 Kolben ...'::text,'reinigen'::text,'reinigen'::text,'reinigend'::text,'Die Laborleitung ließ vor dem Audit 50 Kolben reinigen.'::text),
(354292,39366,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Завідувач лабораторії звелів ... 50 колб перед аудитом.'::text,'почистити'::text,'почистити'::text,'чищення'::text,'Завідувач лабораторії звелів почистити 50 колб перед аудитом.'::text),
(354291,39366,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El jefe del laboratorio mandó ... 50 matraces antes de la auditoría.'::text,'limpiar'::text,'limpiar'::text,'limpiando'::text,'El jefe del laboratorio mandó limpiar 50 matraces antes de la auditoría.'::text),
(354290,39366,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le responsable du labo a fait ... 50 flacons avant l''audit.'::text,'nettoyer'::text,'nettoyer'::text,'nettoyant'::text,'Le responsable du labo a fait nettoyer 50 flacons avant l''audit.'::text),
(354293,39366,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Laboratuvar müdürü denetimden önce 50 şişeyi ...'::text,'temizletti'::text,'temizledi'::text,'temizleyerek'::text,'Laboratuvar müdürü denetimden önce 50 şişeyi temizletti.'::text),
(354294,39366,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A laborvezető az audit előtt ... 50 lombikot.'::text,'kitisztíttatott'::text,'kitisztított'::text,'tisztítva'::text,'A laborvezető az audit előtt kitisztíttatott 50 lombikot.'::text),
(355692,39522,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die schlammigen Fußabdrücke wurden von den Stiefeln des jungen Mannes ..., wie der Schlamm zeigt.'::text,'hinterlassen'::text,'hinterließen'::text,'hinterlassend'::text,'Die schlammigen Fußabdrücke wurden von den Stiefeln des jungen Mannes hinterlassen, wie der Schlamm zeigt.'::text),
(355696,39522,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Брудні сліди ... чоботами молодого чоловіка, як свідчить багнюка.'::text,'були залишені'::text,'залишили'::text,'залишаючи'::text,'Брудні сліди були залишені чоботами молодого чоловіка, як свідчить багнюка.'::text),
(355695,39522,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Las huellas de barro ... por las botas del joven, como indica el barro.'::text,'fueron dejadas'::text,'dejaron'::text,'dejando'::text,'Las huellas de barro fueron dejadas por las botas del joven, como indica el barro.'::text),
(355694,39522,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les empreintes boueuses ... par les bottes du jeune homme, comme l''indique la boue.'::text,'ont été laissées'::text,'ont laissé'::text,'laissant'::text,'Les empreintes boueuses ont été laissées par les bottes du jeune homme, comme l''indique la boue.'::text),
(355697,39522,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Çamurlu ayak izleri, çamurun gösterdiği gibi, genç adamın botları tarafından ...'::text,'bırakıldı'::text,'bıraktı'::text,'bırakarak'::text,'Çamurlu ayak izleri, çamurun gösterdiği gibi, genç adamın botları tarafından bırakıldı.'::text),
(355698,39522,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A sáros lábnyomokat a fiatalember csizmája ..., ahogy a sár is mutatja.'::text,'hagyta'::text,'hagyták'::text,'hagyva'::text,'A sáros lábnyomokat a fiatalember csizmája hagyta, ahogy a sár is mutatja.'::text),
(398820,44314,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie verspricht dem Kunden, dass sie das reifste tropische Obst ...'::text,'aussuchen wird'::text,'aussuchen wird'::text,'aussucht'::text,'Sie verspricht dem Kunden, dass sie das reifste tropische Obst aussuchen wird.'::text),
(398824,44314,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона обіцяє покупцеві, що ... найстигліші тропічні фрукти.'::text,'вибере'::text,'вибиратиме'::text,'вибирає'::text,'Вона обіцяє покупцеві, що вибере найстигліші тропічні фрукти.'::text),
(398823,44314,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ella le promete al cliente que ... la fruta tropical más madura.'::text,'elegirá'::text,'estará eligiendo'::text,'está eligiendo'::text,'Ella le promete al cliente que elegirá la fruta tropical más madura.'::text),
(398822,44314,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle promet au client qu''elle ... les fruits tropicaux les plus mûrs.'::text,'choisira'::text,'sera en train de choisir'::text,'choisit'::text,'Elle promet au client qu''elle choisira les fruits tropicaux les plus mûrs.'::text),
(398825,44314,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O müşteriye en olgun tropik meyveyi ... söz veriyor.'::text,'seçeceğine'::text,'seçiyor olacağına'::text,'seçtiğine'::text,'O müşteriye en olgun tropik meyveyi seçeceğine söz veriyor.'::text),
(398826,44314,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő megígéri a vevőnek, hogy ... a legérettebb trópusi gyümölcsöt.'::text,'kiválasztja'::text,'válogatni fogja'::text,'válogatja'::text,'Ő megígéri a vevőnek, hogy kiválasztja a legérettebb trópusi gyümölcsöt.'::text),
(398856,44318,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... das tropische Obst eine Stunde lang, bevor der erste Kunde kam, leicht langsam.'::text,'stapelte'::text,'stapelte'::text,'stapelte gerade'::text,'Sie stapelte das tropische Obst eine Stunde lang, bevor der erste Kunde kam, leicht langsam.'::text),
(398860,44318,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона ... тропічні фрукти годину, перш ніж прийшов перший покупець, трохи повільно.'::text,'складала'::text,'склала'::text,'складала'::text,'Вона складала тропічні фрукти годину, перш ніж прийшов перший покупець, трохи повільно.'::text),
(398859,44318,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ella ... la fruta tropical durante una hora antes de que llegara el primer cliente, un pelín lento.'::text,'había estado apilando'::text,'apiló'::text,'estaba apilando'::text,'Ella había estado apilando la fruta tropical durante una hora antes de que llegara el primer cliente, un pelín lento.'::text),
(398858,44318,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ... les fruits tropicaux pendant une heure avant l''arrivée du premier client, un poil lent.'::text,'avait empilé'::text,'a empilé'::text,'empilait'::text,'Elle avait empilé les fruits tropicaux pendant une heure avant l''arrivée du premier client, un poil lent.'::text),
(398861,44318,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'İlk müşteri gelmeden önce o tropik meyveleri bir saat boyunca ..., biraz yavaş.'::text,'diziyordu'::text,'dizdi'::text,'diziyordu'::text,'İlk müşteri gelmeden önce o tropik meyveleri bir saat boyunca diziyordu, biraz yavaş.'::text),
(398862,44318,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő egy órán át ... a trópusi gyümölcsöt, mielőtt jött az első vevő, kicsit lassú.'::text,'pakolta'::text,'felpakolta'::text,'pakolta'::text,'Ő egy órán át pakolta a trópusi gyümölcsöt, mielőtt jött az első vevő, kicsit lassú.'::text),
(359175,39909,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, wenn du jemanden für schuldig ..., wird der ganze Gerichtssaal still.'::text,'erklärst'::text,'erklärtest'::text,'erklären wirst'::text,'Ehrlich, wenn du jemanden für schuldig erklärst, wird der ganze Gerichtssaal still.'::text),
(359179,39909,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, якщо ти ... когось винним, уся зала суду замовкає.'::text,'визнаєш'::text,'визнав'::text,'визнаватимеш'::text,'Чесно, якщо ти визнаєш когось винним, уся зала суду замовкає.'::text),
(359178,39909,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sinceramente, si tú ... culpable a alguien, toda la sala se queda en silencio.'::text,'declaras'::text,'declaraste'::text,'declararás'::text,'Sinceramente, si tú declaras culpable a alguien, toda la sala se queda en silencio.'::text),
(359177,39909,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, si tu ... quelqu''un coupable, toute la salle se tait.'::text,'déclares'::text,'déclarais'::text,'déclareras'::text,'Franchement, si tu déclares quelqu''un coupable, toute la salle se tait.'::text),
(359180,39909,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası, sen birini suçlu ..., bütün mahkeme susuyor.'::text,'bulursan'::text,'buldun'::text,'bulacaksan'::text,'Açıkçası, sen birini suçlu bulursan, bütün mahkeme susuyor.'::text),
(359181,39909,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, ha te ... valakit bűnösnek, az egész tárgyalóterem elcsendesedik.'::text,'találsz'::text,'találtál'::text,'találni fogsz'::text,'Őszintén, ha te találsz valakit bűnösnek, az egész tárgyalóterem elcsendesedik.'::text),
(359193,39911,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Eindeutig ein toller Morgen für ihn: Die Richterin ... ihn gerade schuldig.'::text,'spricht'::text,'spricht'::text,'hat gesprochen'::text,'Eindeutig ein toller Morgen für ihn: Die Richterin spricht ihn gerade schuldig.'::text),
(359197,39911,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Явно чудовий ранок для нього: суддя прямо зараз ... його винним.'::text,'визнає'::text,'визнає'::text,'визнала'::text,'Явно чудовий ранок для нього: суддя прямо зараз визнає його винним.'::text),
(359196,39911,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Claramente una gran mañana para él: la jueza lo ... culpable ahora mismo.'::text,'está declarando'::text,'declara'::text,'ha declarado'::text,'Claramente una gran mañana para él: la jueza lo está declarando culpable ahora mismo.'::text),
(359195,39911,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Clairement une super matinée pour lui : la juge ... coupable en ce moment même.'::text,'le déclare'::text,'le déclare'::text,'l''a déclaré'::text,'Clairement une super matinée pour lui : la juge le déclare coupable en ce moment même.'::text),
(359198,39911,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Onun için açıkça harika bir sabah: hâkim şu anda onu suçlu ...'::text,'ilan ediyor'::text,'ilan eder'::text,'ilan etti'::text,'Onun için açıkça harika bir sabah: hâkim şu anda onu suçlu ilan ediyor.'::text),
(359199,39911,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Egyértelműen remek reggel neki: a bírónő éppen most ... bűnösnek.'::text,'nyilvánítja'::text,'nyilvánítja'::text,'nyilvánította'::text,'Egyértelműen remek reggel neki: a bírónő éppen most nyilvánítja bűnösnek.'::text),
(329259,36585,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, der Typ in der ersten Reihe wünscht sich, dass der Richter endlich ..., zum Saal zu sprechen, echt.'::text,'aufhören würde'::text,'aufhört'::text,'aufhören wird'::text,'Bro, der Typ in der ersten Reihe wünscht sich, dass der Richter endlich aufhören würde, zum Saal zu sprechen, echt.'::text),
(329263,36585,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, хлопець у першому ряду хоче, щоб суддя вже ... говорити до зали, чесно.'::text,'перестав'::text,'перестав'::text,'перестане'::text,'Бро, хлопець у першому ряду хоче, щоб суддя вже перестав говорити до зали, чесно.'::text),
(329262,36585,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, el tío de la primera fila desea que el juez ... de hablarle a la sala ya, en serio.'::text,'dejara'::text,'deja'::text,'dejará'::text,'Bro, el tío de la primera fila desea que el juez dejara de hablarle a la sala ya, en serio.'::text),
(329261,36585,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, le mec au premier rang aimerait que le juge ... de parler à la salle, sérieux.'::text,'arrête'::text,'arrête'::text,'arrêtera'::text,'Frérot, le mec au premier rang aimerait que le juge arrête de parler à la salle, sérieux.'::text),
(329264,36585,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, ön sıradaki adam hâkimin artık salona konuşmayı ... istiyor, cidden.'::text,'bırakmasını'::text,'bırakmasını'::text,'bırakacağını'::text,'Kanka, ön sıradaki adam hâkimin artık salona konuşmayı bırakmasını istiyor, cidden.'::text),
(329265,36585,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, az első sorban ülő srác azt szeretné, ha a bíró már ... beszélni a teremhez, komolyan.'::text,'abbahagyná'::text,'abbahagyja'::text,'abba fogja hagyni'::text,'Tesó, az első sorban ülő srác azt szeretné, ha a bíró már abbahagyná beszélni a teremhez, komolyan.'::text),
(337170,37464,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn ein Gast um Tee ..., bringt der Butler ihn auf einem Silbertablett.'::text,'bittet'::text,'bitten wird'::text,'bat'::text,'Wenn ein Gast um Tee bittet, bringt der Butler ihn auf einem Silbertablett.'::text),
(337174,37464,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо гість ... чаю, дворецький приносить його на срібній таці.'::text,'просить'::text,'попросить'::text,'попросив'::text,'Якщо гість просить чаю, дворецький приносить його на срібній таці.'::text),
(337173,37464,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si un invitado ... té, el mayordomo lo trae en una bandeja de plata.'::text,'pide'::text,'pedirá'::text,'pidió'::text,'Si un invitado pide té, el mayordomo lo trae en una bandeja de plata.'::text),
(337172,37464,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si un invité ... du thé, le majordome l''apporte sur un plateau d''argent.'::text,'demande'::text,'demandera'::text,'demandait'::text,'Si un invité demande du thé, le majordome l''apporte sur un plateau d''argent.'::text),
(337175,37464,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bir misafir çay ..., uşak onu gümüş tepside getirir.'::text,'isterse'::text,'isteyecekse'::text,'istediyse'::text,'Bir misafir çay isterse, uşak onu gümüş tepside getirir.'::text),
(337176,37464,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha egy vendég teát ..., a komornyik ezüsttálcán hozza.'::text,'kér'::text,'kérni fog'::text,'kért'::text,'Ha egy vendég teát kér, a komornyik ezüsttálcán hozza.'::text),
(357006,39668,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der große Hund ... höflich sein nasses Fell direkt neben ihrem Kaffee. Super Timing.'::text,'schüttelte'::text,'wurde geschüttelt'::text,'schüttelnd'::text,'Der große Hund schüttelte höflich sein nasses Fell direkt neben ihrem Kaffee. Super Timing.'::text),
(357010,39668,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Великий пес чемно ... мокру шерсть просто біля її кави. Чудовий таймінг.'::text,'обтрусив'::text,'був обтрушений'::text,'обтрушуючи'::text,'Великий пес чемно обтрусив мокру шерсть просто біля її кави. Чудовий таймінг.'::text),
(357009,39668,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El perro grande ... educadamente su pelo mojado justo al lado de su café. Qué buen momento.'::text,'sacudió'::text,'fue sacudido'::text,'sacudiendo'::text,'El perro grande sacudió educadamente su pelo mojado justo al lado de su café. Qué buen momento.'::text),
(357008,39668,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le gros chien ... poliment son pelage mouillé juste à côté de son café. Super timing.'::text,'a secoué'::text,'a été secoué'::text,'secouant'::text,'Le gros chien a secoué poliment son pelage mouillé juste à côté de son café. Super timing.'::text),
(357011,39668,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Büyük köpek kibarca ... ıslak tüylerini, hem de tam onun kahvesinin yanında. Harika zamanlama.'::text,'silkeledi'::text,'silkelendi'::text,'silkeleyerek'::text,'Büyük köpek kibarca silkeledi ıslak tüylerini, hem de tam onun kahvesinin yanında. Harika zamanlama.'::text),
(357012,39668,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A nagy kutya udvariasan ... a vizes bundáját közvetlenül a kávéja mellett. Remek időzítés.'::text,'kirázta'::text,'ki lett rázva'::text,'rázva'::text,'A nagy kutya udvariasan kirázta a vizes bundáját közvetlenül a kávéja mellett. Remek időzítés.'::text),
(385527,42837,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alter, wenn sie den leeren Teller sieht, ... du vor Scham, echt.'::text,'stirbst'::text,'würdest sterben'::text,'starbst'::text,'Alter, wenn sie den leeren Teller sieht, stirbst du vor Scham, echt.'::text),
(385531,42837,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чувак, якщо вона побачить порожню тарілку, ти ... від сорому, чесно.'::text,'помреш'::text,'помер би'::text,'помер'::text,'Чувак, якщо вона побачить порожню тарілку, ти помреш від сорому, чесно.'::text),
(385530,42837,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, si ve el plato vacío, tú te ... de vergüenza, en serio.'::text,'morirás'::text,'morirías'::text,'moriste'::text,'Tío, si ve el plato vacío, tú te morirás de vergüenza, en serio.'::text),
(385529,42837,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mec, si elle voit l''assiette vide, tu ... de honte, sérieux.'::text,'vas mourir'::text,'mourrais'::text,'es mort'::text,'Mec, si elle voit l''assiette vide, tu vas mourir de honte, sérieux.'::text),
(385532,42837,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, boş tabağı görürse sen utançtan ..., cidden.'::text,'öleceksin'::text,'ölürdün'::text,'öldün'::text,'Kanka, boş tabağı görürse sen utançtan öleceksin, cidden.'::text),
(385533,42837,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, ha meglátja az üres tányért, te ... a szégyentől, komolyan.'::text,'meghalsz'::text,'meghalnál'::text,'meghaltál'::text,'Tesó, ha meglátja az üres tányért, te meghalsz a szégyentől, komolyan.'::text),
(385635,42849,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, der Jogger hat sich seinen Anteil Pizza genommen, und die Hundeausführerin ..., ohne Witz.'::text,'auch'::text,'auch'::text,'auch'::text,'Bro, der Jogger hat sich seinen Anteil Pizza genommen, und die Hundeausführerin auch, ohne Witz.'::text),
(385639,42849,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, бігун узяв свою частку піци, і жінка з собаками ..., без жартів.'::text,'теж'::text,'теж'::text,'теж'::text,'Бро, бігун узяв свою частку піци, і жінка з собаками теж, без жартів.'::text),
(385638,42849,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, el corredor cogió su parte de pizza, y la paseadora de perros ..., en serio.'::text,'también'::text,'también'::text,'también'::text,'Bro, el corredor cogió su parte de pizza, y la paseadora de perros también, en serio.'::text),
(385637,42849,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, le joggeur a pris sa part de pizza, et la promeneuse de chiens ..., sans mentir.'::text,'aussi'::text,'aussi'::text,'aussi'::text,'Frérot, le joggeur a pris sa part de pizza, et la promeneuse de chiens aussi, sans mentir.'::text),
(385640,42849,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, koşucu pizzadan payını aldı, köpek gezdiren kadın ..., yemin ederim.'::text,'da'::text,'da'::text,'da'::text,'Kanka, koşucu pizzadan payını aldı, köpek gezdiren kadın da, yemin ederim.'::text),
(385641,42849,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, a kocogó elvette a pizzarészét, és a kutyasétáltató ..., komolyan.'::text,'is'::text,'is'::text,'is'::text,'Tesó, a kocogó elvette a pizzarészét, és a kutyasétáltató is, komolyan.'::text),
(385725,42859,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ließ eine Freundin die Pizza in gleiche Stücke ...'::text,'teilen'::text,'zu teilen'::text,'geteilt'::text,'Sie ließ eine Freundin die Pizza in gleiche Stücke teilen.'::text),
(385729,42859,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона попросила друга ... піцу на рівні частини.'::text,'поділити'::text,'поділити'::text,'поділив'::text,'Вона попросила друга поділити піцу на рівні частини.'::text),
(385728,42859,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ella hizo que un amigo ... la pizza en partes iguales.'::text,'dividiera'::text,'dividir'::text,'dividió'::text,'Ella hizo que un amigo dividiera la pizza en partes iguales.'::text),
(385727,42859,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle a fait ... la pizza en parts égales à un ami.'::text,'couper'::text,'de couper'::text,'coupé'::text,'Elle a fait couper la pizza en parts égales à un ami.'::text),
(385730,42859,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O pizzayı bir arkadaşına eşit dilimlere ...'::text,'böldürdü'::text,'bölmek'::text,'bölünmüş'::text,'O pizzayı bir arkadaşına eşit dilimlere böldürdü.'::text),
(385731,42859,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő egy barátjával ... a pizzát egyenlő részekre.'::text,'osztatta fel'::text,'felosztani'::text,'felosztott'::text,'Ő egy barátjával osztatta fel a pizzát egyenlő részekre.'::text),
(391089,43455,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Als sie zurücksprang, ... das Regal, das so stabil aussah, schon von der Halterung gefallen.'::text,'war'::text,'ist'::text,'fällt'::text,'Als sie zurücksprang, war das Regal, das so stabil aussah, schon von der Halterung gefallen.'::text),
(391093,43455,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Поки вона відскочила назад, полиця, що виглядала такою стійкою, ... з кронштейна.'::text,'вже впала'::text,'впала'::text,'падає'::text,'Поки вона відскочила назад, полиця, що виглядала такою стійкою, вже впала з кронштейна.'::text),
(391092,43455,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para cuando ella saltó hacia atrás, la estantería que parecía tan estable ... de su soporte.'::text,'se había caído'::text,'se ha caído'::text,'se cae'::text,'Para cuando ella saltó hacia atrás, la estantería que parecía tan estable se había caído de su soporte.'::text),
(391091,43455,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Au moment où elle a reculé d''un bond, l''étagère qui avait l''air si stable ... de son support.'::text,'était tombée'::text,'est tombée'::text,'tombe'::text,'Au moment où elle a reculé d''un bond, l''étagère qui avait l''air si stable était tombée de son support.'::text),
(391094,43455,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O geriye sıçradığında, o kadar sağlam görünen raf desteğinden ...'::text,'düşmüştü'::text,'düştü'::text,'düşüyor'::text,'O geriye sıçradığında, o kadar sağlam görünen raf desteğinden düşmüştü.'::text),
(391095,43455,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mire ő hátraugrott, a polc, amely olyan stabilnak tűnt, ... a tartójáról.'::text,'már leesett'::text,'leesett'::text,'leesik'::text,'Mire ő hátraugrott, a polc, amely olyan stabilnak tűnt, már leesett a tartójáról.'::text),
(385923,42881,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie hat das Sofa heute dreimal ..., eindeutig eine feste Entscheidung.'::text,'verschoben'::text,'herumgeschoben'::text,'am Verschieben'::text,'Sie hat das Sofa heute dreimal verschoben, eindeutig eine feste Entscheidung.'::text),
(385927,42881,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона сьогодні ... диван тричі, явно тверде рішення.'::text,'пересунула'::text,'пересувала'::text,'пересуває'::text,'Вона сьогодні пересунула диван тричі, явно тверде рішення.'::text),
(385926,42881,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ella ... el sofá tres veces hoy, claramente una decisión firme.'::text,'ha movido'::text,'ha estado moviendo'::text,'está moviendo'::text,'Ella ha movido el sofá tres veces hoy, claramente una decisión firme.'::text),
(385925,42881,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ... le canapé trois fois aujourd''hui, clairement une décision ferme.'::text,'a déplacé'::text,'a déplacé'::text,'déplace'::text,'Elle a déplacé le canapé trois fois aujourd''hui, clairement une décision ferme.'::text),
(385928,42881,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O bugün kanepenin yerini üç kez ..., belli ki kesin bir karar.'::text,'değiştirdi'::text,'değiştirip duruyor'::text,'değiştiriyor'::text,'O bugün kanepenin yerini üç kez değiştirdi, belli ki kesin bir karar.'::text),
(385929,42881,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő ma háromszor ... a kanapét, egyértelműen határozott döntés.'::text,'tolta arrébb'::text,'tologatta'::text,'tolja arrébb'::text,'Ő ma háromszor tolta arrébb a kanapét, egyértelműen határozott döntés.'::text),
(385968,42886,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Derzeit ... das Subjekt den Couchtisch auf den Teppich, ein Vorgang, der Sorgfalt erfordert.'::text,'schiebt'::text,'schiebt'::text,'hat geschoben'::text,'Derzeit schiebt das Subjekt den Couchtisch auf den Teppich, ein Vorgang, der Sorgfalt erfordert.'::text),
(385972,42886,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Наразі суб''єкт ... журнальний столик на килим, процес, що вимагає обережності.'::text,'пересуває'::text,'пересуває'::text,'пересунув'::text,'Наразі суб''єкт пересуває журнальний столик на килим, процес, що вимагає обережності.'::text),
(385971,42886,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Actualmente, el sujeto ... la mesa de centro sobre la alfombra, un proceso que requiere cuidado.'::text,'está moviendo'::text,'mueve'::text,'ha movido'::text,'Actualmente, el sujeto está moviendo la mesa de centro sobre la alfombra, un proceso que requiere cuidado.'::text),
(385970,42886,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Actuellement, le sujet ... la table basse sur le tapis, un processus qui exige du soin.'::text,'est en train de déplacer'::text,'déplace'::text,'a déplacé'::text,'Actuellement, le sujet est en train de déplacer la table basse sur le tapis, un processus qui exige du soin.'::text),
(385973,42886,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Şu anda denek sehpayı halının üstüne ..., dikkat gerektiren bir süreç.'::text,'kaydırıyor'::text,'kaydırır'::text,'kaydırdı'::text,'Şu anda denek sehpayı halının üstüne kaydırıyor, dikkat gerektiren bir süreç.'::text),
(385974,42886,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Jelenleg az alany ... a dohányzóasztalt a szőnyegre, ami gondosságot igénylő folyamat.'::text,'tolja'::text,'tolja'::text,'tolta'::text,'Jelenleg az alany tolja a dohányzóasztalt a szőnyegre, ami gondosságot igénylő folyamat.'::text),
(381063,42341,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... den Gewehrkolben in ihre Schulter und schoss auf die Ziele.'::text,'drückte'::text,'wurde gedrückt'::text,'drückend'::text,'Sie drückte den Gewehrkolben in ihre Schulter und schoss auf die Ziele.'::text),
(381067,42341,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона ... приклад гвинтівки до плеча і вистрілила по мішенях.'::text,'притиснула'::text,'була притиснута'::text,'притискаючи'::text,'Вона притиснула приклад гвинтівки до плеча і вистрілила по мішенях.'::text),
(381066,42341,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ella ... la culata del rifle contra el hombro y disparó a los blancos.'::text,'apoyó'::text,'fue apoyada'::text,'apoyando'::text,'Ella apoyó la culata del rifle contra el hombro y disparó a los blancos.'::text),
(381065,42341,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ... la crosse du fusil contre son épaule et a tiré sur les cibles.'::text,'a calé'::text,'a été calée'::text,'calant'::text,'Elle a calé la crosse du fusil contre son épaule et a tiré sur les cibles.'::text),
(381068,42341,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O tüfeğin dipçiğini omzuna ... ve hedeflere ateş etti.'::text,'bastırdı'::text,'bastırıldı'::text,'bastırarak'::text,'O tüfeğin dipçiğini omzuna bastırdı ve hedeflere ateş etti.'::text),
(381069,42341,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő a vállához ... a puskatust, és rálőtt a célokra.'::text,'szorította'::text,'szorítva lett'::text,'szorítva'::text,'Ő a vállához szorította a puskatust, és rálőtt a célokra.'::text),
(381117,42347,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie schoss mit ihrem Gewehr live ..., ein leicht privater Moment.'::text,'im Fernsehen'::text,'im Fernseher'::text,'in einem Fernseher'::text,'Sie schoss mit ihrem Gewehr live im Fernsehen, ein leicht privater Moment.'::text),
(381121,42347,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона стріляла з гвинтівки в прямому ефірі ..., трохи приватний момент.'::text,'по телевізору'::text,'по телевізору'::text,'по телевізору'::text,'Вона стріляла з гвинтівки в прямому ефірі по телевізору, трохи приватний момент.'::text),
(381120,42347,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ella disparó con su rifle en directo en ..., un momento un pelín privado.'::text,'televisión'::text,'la televisión'::text,'una televisión'::text,'Ella disparó con su rifle en directo en televisión, un momento un pelín privado.'::text),
(381119,42347,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle a tiré avec son fusil en direct à ..., un moment légèrement privé.'::text,'la télé'::text,'la télé'::text,'une télé'::text,'Elle a tiré avec son fusil en direct à la télé, un moment légèrement privé.'::text),
(381122,42347,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O tüfeğiyle ... canlı yayında ateş etti, biraz özel bir an.'::text,'televizyonda'::text,'televizyonda'::text,'bir televizyonda'::text,'O tüfeğiyle televizyonda canlı yayında ateş etti, biraz özel bir an.'::text),
(381123,42347,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő élőben lőtt a puskájával ..., egy kissé privát pillanat.'::text,'a tévében'::text,'a tévében'::text,'egy tévében'::text,'Ő élőben lőtt a puskájával a tévében, egy kissé privát pillanat.'::text),
(377535,41949,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis heute Abend wird sie eine Tafel Schokolade, einen Mantel und ein Geschenk ...'::text,'gekauft haben'::text,'kaufen'::text,'am Kaufen sein'::text,'Bis heute Abend wird sie eine Tafel Schokolade, einen Mantel und ein Geschenk gekauft haben.'::text),
(377539,41949,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До сьогоднішнього вечора вона ... шоколадку, пальто і подарунок.'::text,'купить'::text,'купить'::text,'купуватиме'::text,'До сьогоднішнього вечора вона купить шоколадку, пальто і подарунок.'::text),
(377538,41949,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para esta noche, ella ... una tableta de chocolate, un abrigo y un regalo.'::text,'habrá comprado'::text,'comprará'::text,'estará comprando'::text,'Para esta noche, ella habrá comprado una tableta de chocolate, un abrigo y un regalo.'::text),
(377537,41949,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici ce soir, elle ... une tablette de chocolat, un manteau et un cadeau.'::text,'aura acheté'::text,'achètera'::text,'sera en train d''acheter'::text,'D''ici ce soir, elle aura acheté une tablette de chocolat, un manteau et un cadeau.'::text),
(377540,41949,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu akşama kadar o bir çikolata, bir mont ve bir hediye ...'::text,'almış olacak'::text,'alacak'::text,'alıyor olacak'::text,'Bu akşama kadar o bir çikolata, bir mont ve bir hediye almış olacak.'::text),
(377541,41949,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ma estére ő ... egy tábla csokit, egy kabátot és egy ajándékot.'::text,'már megvesz'::text,'meg fog venni'::text,'vásárolni fog'::text,'Ma estére ő már megvesz egy tábla csokit, egy kabátot és egy ajándékot.'::text),
(360039,40005,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, während du über den Canyon ..., hat sich jeder Wanderer auf dem Weg umgedreht.'::text,'riefst'::text,'riefst'::text,'gerufen hast'::text,'Ehrlich, während du über den Canyon riefst, hat sich jeder Wanderer auf dem Weg umgedreht.'::text),
(360043,40005,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, поки ти ... над каньйоном, кожен турист на стежці обернувся.'::text,'кричала'::text,'крикнула'::text,'крикнула'::text,'Чесно, поки ти кричала над каньйоном, кожен турист на стежці обернувся.'::text),
(360042,40005,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sinceramente, mientras tú ... sobre el cañón, todos los excursionistas del sendero se dieron la vuelta.'::text,'gritabas'::text,'gritaste'::text,'has gritado'::text,'Sinceramente, mientras tú gritabas sobre el cañón, todos los excursionistas del sendero se dieron la vuelta.'::text),
(360041,40005,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, pendant que tu ... au-dessus du canyon, tous les randonneurs du sentier se sont retournés.'::text,'criais'::text,'as crié'::text,'as crié'::text,'Franchement, pendant que tu criais au-dessus du canyon, tous les randonneurs du sentier se sont retournés.'::text),
(360044,40005,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası, sen kanyonun üzerinden ..., patikadaki her yürüyüşçü döndü.'::text,'bağırırken'::text,'bağırdın'::text,'bağırmışken'::text,'Açıkçası, sen kanyonun üzerinden bağırırken, patikadaki her yürüyüşçü döndü.'::text),
(360045,40005,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, miközben te ... a kanyon fölött, az ösvényen minden túrázó megfordult.'::text,'kiabáltál'::text,'felkiáltottál'::text,'kiabáltál'::text,'Őszintén, miközben te kiabáltál a kanyon fölött, az ösvényen minden túrázó megfordult.'::text),
(360111,40013,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Im Moment ... die drei Wanderer ihre Arme über dem Canyon in die Luft.'::text,'strecken'::text,'strecken'::text,'haben gestreckt'::text,'Im Moment strecken die drei Wanderer ihre Arme über dem Canyon in die Luft.'::text),
(360115,40013,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Зараз троє туристів ... руки в повітря над каньйоном.'::text,'піднімають'::text,'піднімають'::text,'підняли'::text,'Зараз троє туристів піднімають руки в повітря над каньйоном.'::text),
(360114,40013,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En este momento, los tres excursionistas ... los brazos sobre el cañón.'::text,'están levantando'::text,'levantan'::text,'han levantado'::text,'En este momento, los tres excursionistas están levantando los brazos sobre el cañón.'::text),
(360113,40013,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En ce moment, les trois randonneurs ... les bras en l''air au-dessus du canyon.'::text,'lèvent'::text,'lèvent'::text,'ont levé'::text,'En ce moment, les trois randonneurs lèvent les bras en l''air au-dessus du canyon.'::text),
(360116,40013,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Şu anda üç yürüyüşçü kanyonun üstünde kollarını havaya ...'::text,'kaldırıyor'::text,'kaldırır'::text,'kaldırdı'::text,'Şu anda üç yürüyüşçü kanyonun üstünde kollarını havaya kaldırıyor.'::text),
(360117,40013,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Épp most a három túrázó ... a karját a levegőbe a kanyon fölött.'::text,'emeli'::text,'emeli'::text,'felemelte'::text,'Épp most a három túrázó emeli a karját a levegőbe a kanyon fölött.'::text),
(369471,41053,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, wenn ich wie das Model laufen würde, ... ich auch ziemlich ikonisch aus.'::text,'sähe'::text,'werde'::text,'sehe'::text,'Bro, wenn ich wie das Model laufen würde, sähe ich auch ziemlich ikonisch aus.'::text),
(369475,41053,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, якби я ходив як ця модель, я теж ... досить легендарно.'::text,'виглядав би'::text,'виглядатиму'::text,'виглядаю'::text,'Бро, якби я ходив як ця модель, я теж виглядав би досить легендарно.'::text),
(369474,41053,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, si caminara como ese modelo, yo también ... bastante icónico.'::text,'me vería'::text,'me veré'::text,'me veo'::text,'Bro, si caminara como ese modelo, yo también me vería bastante icónico.'::text),
(369473,41053,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, si je marchais comme ce mannequin, je ... trop iconique aussi.'::text,'serais'::text,'serai'::text,'suis'::text,'Frérot, si je marchais comme ce mannequin, je serais trop iconique aussi.'::text),
(369476,41053,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, o model gibi yürüsem ben de epey ikonik ...'::text,'görünürdüm'::text,'görüneceğim'::text,'görünüyorum'::text,'Kanka, o model gibi yürüsem ben de epey ikonik görünürdüm.'::text),
(369477,41053,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, ha úgy járnék, mint az a modell, én is elég ikonikusan ...'::text,'néznék ki'::text,'fogok kinézni'::text,'nézek ki'::text,'Tesó, ha úgy járnék, mint az a modell, én is elég ikonikusan néznék ki.'::text),
(369552,41062,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Perfektes Timing: Das Model ... zweimal auf seine Uhr geschaut, bevor es das Ende des Laufstegs erreichte.'::text,'hatte'::text,'hat'::text,'schaut'::text,'Perfektes Timing: Das Model hatte zweimal auf seine Uhr geschaut, bevor es das Ende des Laufstegs erreichte.'::text),
(369556,41062,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бездоганний таймінг: модель ... годинник двічі, перш ніж дійшла до кінця подіуму.'::text,'перевірила'::text,'перевірила'::text,'перевіряє'::text,'Бездоганний таймінг: модель перевірила годинник двічі, перш ніж дійшла до кінця подіуму.'::text),
(369555,41062,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Timing perfecto: el modelo ... su reloj dos veces antes de llegar al final de la pasarela.'::text,'había mirado'::text,'ha mirado'::text,'mira'::text,'Timing perfecto: el modelo había mirado su reloj dos veces antes de llegar al final de la pasarela.'::text),
(369554,41062,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Timing parfait : le mannequin ... sa montre deux fois avant d''arriver au bout du podium.'::text,'avait regardé'::text,'a regardé'::text,'regarde'::text,'Timing parfait : le mannequin avait regardé sa montre deux fois avant d''arriver au bout du podium.'::text),
(369557,41062,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kusursuz zamanlama: model podyumun sonuna varmadan önce saatine iki kez ...'::text,'bakmıştı'::text,'baktı'::text,'bakıyor'::text,'Kusursuz zamanlama: model podyumun sonuna varmadan önce saatine iki kez bakmıştı.'::text),
(369558,41062,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tökéletes időzítés: a modell kétszer ... az óráját, mielőtt a kifutó végére ért.'::text,'nézte meg'::text,'megnézte'::text,'megnézi'::text,'Tökéletes időzítés: a modell kétszer nézte meg az óráját, mielőtt a kifutó végére ért.'::text),
(389019,43225,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ist von Kopf bis Fuß klatschnass, ...?'::text,'nicht wahr'::text,'oder'::text,'war er nicht'::text,'Er ist von Kopf bis Fuß klatschnass, nicht wahr?'::text),
(389023,43225,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він промок з голови до ніг, ...?'::text,'чи не так'::text,'хіба ні'::text,'чи не був'::text,'Він промок з голови до ніг, чи не так?'::text),
(389022,43225,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Él está empapado de pies a cabeza, ¿...?'::text,'verdad'::text,'no'::text,'no estaba'::text,'Él está empapado de pies a cabeza, ¿verdad?'::text),
(389021,43225,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il est trempé de la tête aux pieds, ... ?'::text,'n''est-ce pas'::text,'non'::text,'n''était-il pas'::text,'Il est trempé de la tête aux pieds, n''est-ce pas ?'::text),
(389024,43225,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O tepeden tırnağa sırılsıklam, ...?'::text,'değil mi'::text,'değil mi'::text,'değil miydi'::text,'O tepeden tırnağa sırılsıklam, değil mi?'::text),
(389025,43225,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő tetőtől talpig csuromvizes, ...?'::text,'nem igaz'::text,'ugye'::text,'nem volt az'::text,'Ő tetőtől talpig csuromvizes, nem igaz?'::text),
(389073,43231,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Süße, anscheinend hat er die Dusche ... lassen, damit er schneller nass wird.'::text,'reparieren'::text,'reparieren'::text,'zu reparieren'::text,'Süße, anscheinend hat er die Dusche reparieren lassen, damit er schneller nass wird.'::text),
(389077,43231,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, кажуть, він попросив ... душ, щоб швидше промокнути.'::text,'полагодити'::text,'полагодити'::text,'полагодити'::text,'Подруго, кажуть, він попросив полагодити душ, щоб швидше промокнути.'::text),
(389076,43231,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tía, al parecer él mandó ... la ducha para poder empaparse más rápido.'::text,'arreglar'::text,'arreglar'::text,'arreglar'::text,'Tía, al parecer él mandó arreglar la ducha para poder empaparse más rápido.'::text),
(389075,43231,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Meuf, apparemment il a fait ... la douche pour pouvoir être trempé plus vite.'::text,'réparer'::text,'réparer'::text,'réparer'::text,'Meuf, apparemment il a fait réparer la douche pour pouvoir être trempé plus vite.'::text),
(389078,43231,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, duyduğuma göre o daha hızlı ıslanabilmek için duşu ...'::text,'tamir ettirmiş'::text,'tamir etmiş'::text,'tamir etmeyi'::text,'Kızım, duyduğuma göre o daha hızlı ıslanabilmek için duşu tamir ettirmiş.'::text),
(389079,43231,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, állítólag ő ... a zuhanyt, hogy gyorsabban bőrig ázhasson.'::text,'megjavíttatta'::text,'megjavította'::text,'megjavíttatni'::text,'Csajszi, állítólag ő megjavíttatta a zuhanyt, hogy gyorsabban bőrig ázhasson.'::text),
(384672,42742,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Morgen um diese Zeit ... die zwei egoistischen Kinder wieder um die Fernbedienung.'::text,'streiten sich'::text,'werden sich streiten'::text,'streiten sich'::text,'Morgen um diese Zeit streiten sich die zwei egoistischen Kinder wieder um die Fernbedienung.'::text),
(384676,42742,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Завтра в цей час двоє егоїстичних дітей знову ... за пульт.'::text,'битимуться'::text,'поб''ються'::text,'б''ються'::text,'Завтра в цей час двоє егоїстичних дітей знову битимуться за пульт.'::text),
(384675,42742,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mañana a esta hora, los dos niños egoístas ... otra vez por el mando.'::text,'estarán peleando'::text,'pelearán'::text,'pelean'::text,'Mañana a esta hora, los dos niños egoístas estarán peleando otra vez por el mando.'::text),
(384674,42742,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Demain à la même heure, les deux enfants égoïstes ... encore pour la télécommande.'::text,'se disputeront'::text,'se disputeront'::text,'se disputent'::text,'Demain à la même heure, les deux enfants égoïstes se disputeront encore pour la télécommande.'::text),
(384677,42742,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yarın bu saatte iki bencil çocuk yine kumanda için ...'::text,'kavga ediyor olacak'::text,'kavga edecek'::text,'kavga ediyor'::text,'Yarın bu saatte iki bencil çocuk yine kumanda için kavga ediyor olacak.'::text),
(384678,42742,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Holnap ilyenkor a két önző gyerek megint ... a távirányítón.'::text,'fog veszekedni'::text,'veszekszik majd'::text,'veszekszik'::text,'Holnap ilyenkor a két önző gyerek megint fog veszekedni a távirányítón.'::text),
(386760,42974,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn ein Geschwisterkind den letzten Keks nimmt, ... das andere sehr wütend.'::text,'wird'::text,'wäre'::text,'war'::text,'Wenn ein Geschwisterkind den letzten Keks nimmt, wird das andere sehr wütend.'::text),
(386764,42974,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо один з братів чи сестер візьме останнє печиво, інший ... дуже злий.'::text,'буде'::text,'був би'::text,'був'::text,'Якщо один з братів чи сестер візьме останнє печиво, інший буде дуже злий.'::text),
(386763,42974,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si un hermano se queda con la última galleta, el otro ... muy enfadado.'::text,'estará'::text,'estaría'::text,'estaba'::text,'Si un hermano se queda con la última galleta, el otro estará muy enfadado.'::text),
(386762,42974,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si un frère ou une sœur prend le dernier cookie, l''autre ... très en colère.'::text,'sera'::text,'serait'::text,'était'::text,'Si un frère ou une sœur prend le dernier cookie, l''autre sera très en colère.'::text),
(386765,42974,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kardeşlerden biri son kurabiyeyi alırsa, diğeri çok kızgın ...'::text,'olacak'::text,'olurdu'::text,'oldu'::text,'Kardeşlerden biri son kurabiyeyi alırsa, diğeri çok kızgın olacak.'::text),
(386766,42974,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha az egyik testvér elveszi az utolsó kekszet, a másik nagyon mérges ...'::text,'lesz'::text,'lenne'::text,'volt'::text,'Ha az egyik testvér elveszi az utolsó kekszet, a másik nagyon mérges lesz.'::text),
(386769,42975,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Jedes Geschwisterkind wünscht sich, es ... den ganzen Keks für sich allein.'::text,'hätte'::text,'hat'::text,'wird haben'::text,'Jedes Geschwisterkind wünscht sich, es hätte den ganzen Keks für sich allein.'::text),
(386773,42975,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Кожна з сестер хоче, щоб у неї ... ціле печиво для себе.'::text,'було'::text,'є'::text,'буде'::text,'Кожна з сестер хоче, щоб у неї було ціле печиво для себе.'::text),
(386772,42975,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cada hermana desearía que ella ... la galleta entera para sí.'::text,'tuviera'::text,'tiene'::text,'tendrá'::text,'Cada hermana desearía que ella tuviera la galleta entera para sí.'::text),
(386771,42975,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Chaque sœur aimerait qu''elle ... le cookie entier pour elle toute seule.'::text,'ait'::text,'a'::text,'aura'::text,'Chaque sœur aimerait qu''elle ait le cookie entier pour elle toute seule.'::text),
(386774,42975,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Her kardeş bütün kurabiyenin kendisinin ... diliyor.'::text,'olmasını'::text,'olduğunu'::text,'olacağını'::text,'Her kardeş bütün kurabiyenin kendisinin olmasını diliyor.'::text),
(386775,42975,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Minden testvér azt kívánja, bárcsak ... neki az egész keksz.'::text,'lenne'::text,'van'::text,'lesz'::text,'Minden testvér azt kívánja, bárcsak lenne neki az egész keksz.'::text),
(384339,42705,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rate mal, er hat sich anscheinend geweigert, die riesige Schriftrolle mit einem normalen Stift ...'::text,'zu unterschreiben'::text,'Unterschreiben'::text,'unterschreiben'::text,'Rate mal, er hat sich anscheinend geweigert, die riesige Schriftrolle mit einem normalen Stift zu unterschreiben.'::text),
(384343,42705,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Уяви, він, кажуть, відмовився ... гігантський сувій звичайною ручкою.'::text,'підписати'::text,'підписування'::text,'підписати'::text,'Уяви, він, кажуть, відмовився підписати гігантський сувій звичайною ручкою.'::text),
(384342,42705,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Adivina qué: al parecer, él se negó a ... el pergamino gigante con un boli normal.'::text,'firmar'::text,'firmando'::text,'firmar'::text,'Adivina qué: al parecer, él se negó a firmar el pergamino gigante con un boli normal.'::text),
(384341,42705,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Devine quoi, il a refusé ... le parchemin géant avec un stylo normal, apparemment.'::text,'de signer'::text,'signer'::text,'signe'::text,'Devine quoi, il a refusé de signer le parchemin géant avec un stylo normal, apparemment.'::text),
(384344,42705,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bil bakalım, duyduğuma göre o dev parşömeni normal bir kalemle ... reddetmiş.'::text,'imzalamayı'::text,'imzalamayı'::text,'imzala'::text,'Bil bakalım, duyduğuma göre o dev parşömeni normal bir kalemle imzalamayı reddetmiş.'::text),
(384345,42705,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Képzeld, ő állítólag nem volt hajlandó ... az óriási tekercset egy sima tollal.'::text,'aláírni'::text,'aláírást'::text,'aláír'::text,'Képzeld, ő állítólag nem volt hajlandó aláírni az óriási tekercset egy sima tollal.'::text),
(384357,42707,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hör zu, anscheinend ... er stundenlang Papiere, bevor sie die Schriftrolle brachten.'::text,'unterschrieb'::text,'unterschreibt'::text,'unterschrieb gerade'::text,'Hör zu, anscheinend unterschrieb er stundenlang Papiere, bevor sie die Schriftrolle brachten.'::text),
(384361,42707,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, кажуть, він ... папери годинами, перш ніж винесли сувій.'::text,'підписував'::text,'підписує'::text,'підписував'::text,'Слухай, кажуть, він підписував папери годинами, перш ніж винесли сувій.'::text),
(384360,42707,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Escucha, al parecer él ... papeles durante horas antes de que sacaran el pergamino.'::text,'había estado firmando'::text,'ha estado firmando'::text,'estaba firmando'::text,'Escucha, al parecer él había estado firmando papeles durante horas antes de que sacaran el pergamino.'::text),
(384359,42707,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, apparemment il ... des papiers pendant des heures avant qu''ils sortent le parchemin.'::text,'avait signé'::text,'a signé'::text,'signait'::text,'Écoute, apparemment il avait signé des papiers pendant des heures avant qu''ils sortent le parchemin.'::text),
(384362,42707,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, duyduğuma göre parşömeni getirmeden önce o saatlerce evrak ...'::text,'imzalıyormuş'::text,'imzalıyor'::text,'imzalıyordu'::text,'Dinle, duyduğuma göre parşömeni getirmeden önce o saatlerce evrak imzalıyormuş.'::text),
(384363,42707,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, állítólag ő órákig ... papírokat, mielőtt kihozták a tekercset.'::text,'írt alá'::text,'ír alá'::text,'írt alá'::text,'Figyelj, állítólag ő órákig írt alá papírokat, mielőtt kihozták a tekercset.'::text),
(387399,43045,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Eindeutig ein Meisterwerk: Dieser Wegweiser ... vor etwa hundert Jahren von Hand bemalt.'::text,'wurde'::text,'wird'::text,'bemalte'::text,'Eindeutig ein Meisterwerk: Dieser Wegweiser wurde vor etwa hundert Jahren von Hand bemalt.'::text),
(387403,43045,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Явно шедевр: цей дороговказ ... вручну близько ста років тому.'::text,'був намальований'::text,'намальований'::text,'намалював'::text,'Явно шедевр: цей дороговказ був намальований вручну близько ста років тому.'::text),
(387402,43045,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Claramente una obra maestra: esta señal ... a mano hace unos cien años.'::text,'fue pintada'::text,'es pintada'::text,'pintó'::text,'Claramente una obra maestra: esta señal fue pintada a mano hace unos cien años.'::text),
(387401,43045,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Clairement un chef-d''œuvre : ce panneau ... à la main il y a environ cent ans.'::text,'a été peint'::text,'est peint'::text,'a peint'::text,'Clairement un chef-d''œuvre : ce panneau a été peint à la main il y a environ cent ans.'::text),
(387404,43045,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkça bir başyapıt: bu tabela yaklaşık yüz yıl önce elle ...'::text,'boyandı'::text,'boyanır'::text,'boyadı'::text,'Açıkça bir başyapıt: bu tabela yaklaşık yüz yıl önce elle boyandı.'::text),
(387405,43045,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Egyértelműen mestermű: ezt az útjelző táblát kb. száz éve kézzel ...'::text,'festették'::text,'festik'::text,'festette'::text,'Egyértelműen mestermű: ezt az útjelző táblát kb. száz éve kézzel festették.'::text),
(368706,40968,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Ritter ... schon seit Stunden in seiner schweren Metallrüstung.'::text,'steht'::text,'steht gerade'::text,'steht'::text,'Der Ritter steht schon seit Stunden in seiner schweren Metallrüstung.'::text),
(368710,40968,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Лицар ... у своїх важких металевих обладунках уже кілька годин.'::text,'стоїть'::text,'стоїть'::text,'стоїть'::text,'Лицар стоїть у своїх важких металевих обладунках уже кілька годин.'::text),
(368709,40968,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El caballero ... con su pesada armadura de metal durante horas.'::text,'ha estado de pie'::text,'está de pie'::text,'está de pie'::text,'El caballero ha estado de pie con su pesada armadura de metal durante horas.'::text),
(368708,40968,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le chevalier ... dans sa lourde armure en métal depuis des heures.'::text,'se tient debout'::text,'se tient debout'::text,'se tient debout'::text,'Le chevalier se tient debout dans sa lourde armure en métal depuis des heures.'::text),
(368711,40968,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Şövalye saatlerdir ağır metal zırhının içinde ...'::text,'duruyor'::text,'duruyor'::text,'durur'::text,'Şövalye saatlerdir ağır metal zırhının içinde duruyor.'::text),
(368712,40968,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A lovag órák óta ... a nehéz fémpáncéljában.'::text,'áll'::text,'áll'::text,'áll'::text,'A lovag órák óta áll a nehéz fémpáncéljában.'::text),
(369696,41078,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Künstlerin ... gerade die trockene Haut, als sie dem Bild einen Tropfen Feuchtigkeit hinzufügte.'::text,'malte'::text,'malte'::text,'hat gemalt'::text,'Die Künstlerin malte gerade die trockene Haut, als sie dem Bild einen Tropfen Feuchtigkeit hinzufügte.'::text),
(369700,41078,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Художниця ... суху шкіру, коли додала до малюнка краплю вологи.'::text,'малювала'::text,'намалювала'::text,'намалювала'::text,'Художниця малювала суху шкіру, коли додала до малюнка краплю вологи.'::text),
(369699,41078,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La artista ... la piel seca cuando añadió una gota de humedad al cuadro.'::text,'estaba pintando'::text,'pintó'::text,'ha pintado'::text,'La artista estaba pintando la piel seca cuando añadió una gota de humedad al cuadro.'::text),
(369698,41078,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''artiste ... la peau sèche quand elle a ajouté une goutte d''humidité au tableau.'::text,'peignait'::text,'a peint'::text,'a peint'::text,'L''artiste peignait la peau sèche quand elle a ajouté une goutte d''humidité au tableau.'::text),
(369701,41078,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sanatçı resme bir damla nem eklediğinde kuru cildi ...'::text,'çiziyordu'::text,'çizdi'::text,'çizmiş'::text,'Sanatçı resme bir damla nem eklediğinde kuru cildi çiziyordu.'::text),
(369702,41078,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A művész éppen a száraz bőrt ..., amikor egy csepp nedvességet adott a képhez.'::text,'festette'::text,'megfestette'::text,'megfestette'::text,'A művész éppen a száraz bőrt festette, amikor egy csepp nedvességet adott a képhez.'::text),
(387705,43079,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, dein Trenchcoat sieht ikonisch aus unter einem Wolkenkratzer, ... Spitze den Himmel berührt.'::text,'dessen'::text,'der'::text,'wer'::text,'Ehrlich, dein Trenchcoat sieht ikonisch aus unter einem Wolkenkratzer, dessen Spitze den Himmel berührt.'::text),
(387709,43079,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, твій тренч виглядає легендарно під хмарочосом, ... вершина торкається неба.'::text,'чия'::text,'який'::text,'хто'::text,'Чесно, твій тренч виглядає легендарно під хмарочосом, чия вершина торкається неба.'::text),
(387708,43079,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sinceramente, tu gabardina se ve icónica bajo un rascacielos ... cima toca el cielo.'::text,'cuya'::text,'que'::text,'quien'::text,'Sinceramente, tu gabardina se ve icónica bajo un rascacielos cuya cima toca el cielo.'::text),
(387707,43079,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, ton trench-coat a l''air iconique sous un gratte-ciel ... le sommet touche le ciel.'::text,'dont'::text,'qui'::text,'qui'::text,'Franchement, ton trench-coat a l''air iconique sous un gratte-ciel dont le sommet touche le ciel.'::text),
(387710,43079,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası, trençkotun ... tepesi gökyüzüne değen bir gökdelenin altında ikonik görünüyor.'::text,''::text,NULL::text,NULL::text,'Açıkçası, trençkotun tepesi gökyüzüne değen bir gökdelenin altında ikonik görünüyor.'::text),
(387711,43079,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, a ballonkabátod ikonikusan néz ki egy felhőkarcoló alatt, ... csúcsa az eget érinti.'::text,'amelynek a'::text,'amely'::text,'aki'::text,'Őszintén, a ballonkabátod ikonikusan néz ki egy felhőkarcoló alatt, amelynek a csúcsa az eget érinti.'::text),
(387777,43087,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis Mittag wird der Besucher die Fassaden des Wolkenkratzers etwa zwei Stunden lang ...'::text,'beobachtet haben'::text,'beobachten'::text,'beobachtet'::text,'Bis Mittag wird der Besucher die Fassaden des Wolkenkratzers etwa zwei Stunden lang beobachtet haben.'::text),
(387781,43087,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До полудня відвідувач ... фасади хмарочоса приблизно дві години.'::text,'спостерігатиме'::text,'спостерігатиме'::text,'спостерігав'::text,'До полудня відвідувач спостерігатиме фасади хмарочоса приблизно дві години.'::text),
(387780,43087,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para el mediodía, el visitante ... las fachadas del rascacielos durante aproximadamente dos horas.'::text,'habrá estado observando'::text,'estará observando'::text,'ha observado'::text,'Para el mediodía, el visitante habrá estado observando las fachadas del rascacielos durante aproximadamente dos horas.'::text),
(387779,43087,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici midi, le visiteur ... les façades du gratte-ciel pendant environ deux heures.'::text,'aura observé'::text,'sera en train d''observer'::text,'a observé'::text,'D''ici midi, le visiteur aura observé les façades du gratte-ciel pendant environ deux heures.'::text),
(387782,43087,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Öğlene kadar ziyaretçi gökdelen cephelerini yaklaşık iki saattir ...'::text,'gözlemliyor olacak'::text,'gözlemliyor olacak'::text,'gözlemledi'::text,'Öğlene kadar ziyaretçi gökdelen cephelerini yaklaşık iki saattir gözlemliyor olacak.'::text),
(387783,43087,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Délre a látogató körülbelül két órája ... a felhőkarcoló homlokzatait.'::text,'fogja figyelni'::text,'fogja figyelni'::text,'figyelte'::text,'Délre a látogató körülbelül két órája fogja figyelni a felhőkarcoló homlokzatait.'::text),
(376950,41884,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er schläft auf seinem Buch, also ist er nicht sehr produktiv, ...?'::text,'oder'::text,'nicht wahr'::text,'tut er'::text,'Er schläft auf seinem Buch, also ist er nicht sehr produktiv, oder?'::text),
(376954,41884,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він спить на своїй книжці, тож він не дуже продуктивний, ...?'::text,'так'::text,'чи не так'::text,'хіба'::text,'Він спить на своїй книжці, тож він не дуже продуктивний, так?'::text),
(376953,41884,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Él está dormido sobre su libro, así que no es muy productivo, ¿...?'::text,'verdad'::text,'no'::text,'sí'::text,'Él está dormido sobre su libro, así que no es muy productivo, ¿verdad?'::text),
(376952,41884,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il dort sur son livre, donc il n''est pas très productif, ... ?'::text,'hein'::text,'n''est-ce pas'::text,'si'::text,'Il dort sur son livre, donc il n''est pas très productif, hein ?'::text),
(376955,41884,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O kitabının üstünde uyuyor, yani pek verimli değil, ...?'::text,'öyle mi'::text,'değil mi'::text,'mi'::text,'O kitabının üstünde uyuyor, yani pek verimli değil, öyle mi?'::text),
(376956,41884,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő a könyvén alszik, szóval nem túl produktív, ...?'::text,'ugye'::text,'nem igaz'::text,'igaz'::text,'Ő a könyvén alszik, szóval nem túl produktív, ugye?'::text),
(376995,41889,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Süße, anscheinend ... er letzte Nacht überhaupt nicht geschlafen haben; niemand, der so müde ist, ist produktiv.'::text,'kann'::text,'darf'::text,'sollte'::text,'Süße, anscheinend kann er letzte Nacht überhaupt nicht geschlafen haben; niemand, der so müde ist, ist produktiv.'::text),
(376999,41889,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, він, мабуть, ... вночі зовсім; ніхто такий втомлений не буває продуктивним.'::text,'не міг спати'::text,'не мав права спати'::text,'не мав би спати'::text,'Подруго, він, мабуть, не міг спати вночі зовсім; ніхто такий втомлений не буває продуктивним.'::text),
(376998,41889,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tía, al parecer él ... dormido nada anoche; nadie tan cansado es productivo.'::text,'no puede haber'::text,'no debe haber'::text,'no debería haber'::text,'Tía, al parecer él no puede haber dormido nada anoche; nadie tan cansado es productivo.'::text),
(376997,41889,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Meuf, apparemment il ... dormi du tout la nuit dernière ; personne d''aussi fatigué n''est productif.'::text,'ne peut pas avoir'::text,'ne doit pas avoir'::text,'n''aurait pas dû'::text,'Meuf, apparemment il ne peut pas avoir dormi du tout la nuit dernière ; personne d''aussi fatigué n''est productif.'::text),
(377000,41889,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, duyduğuma göre o dün gece hiç ...; o kadar yorgun olan kimse verimli değildir.'::text,'uyumuş olamaz'::text,'uyumuş olmamalı'::text,'uyumamalıydı'::text,'Kızım, duyduğuma göre o dün gece hiç uyumuş olamaz; o kadar yorgun olan kimse verimli değildir.'::text),
(377001,41889,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, ő állítólag tegnap éjjel egyáltalán ...; senki sem produktív, aki ennyire fáradt.'::text,'nem aludhatott'::text,'nem volt szabad aludnia'::text,'nem kellett volna aludnia'::text,'Csajszi, ő állítólag tegnap éjjel egyáltalán nem aludhatott; senki sem produktív, aki ennyire fáradt.'::text),
(361056,40118,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Hirte ... sein Horn am Hang schon seit dem frühen Morgen.'::text,'bläst'::text,'hat geblasen'::text,'bläst'::text,'Der Hirte bläst sein Horn am Hang schon seit dem frühen Morgen.'::text),
(361060,40118,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Пастух ... у свій ріг на схилі з раннього ранку.'::text,'сурмить'::text,'засурмив'::text,'сурмить'::text,'Пастух сурмить у свій ріг на схилі з раннього ранку.'::text),
(361059,40118,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El pastor ... su cuerno en la ladera desde primera hora de la mañana.'::text,'lleva tocando'::text,'ha tocado'::text,'toca'::text,'El pastor lleva tocando su cuerno en la ladera desde primera hora de la mañana.'::text),
(361058,40118,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le berger ... dans sa corne sur la colline depuis tôt ce matin.'::text,'souffle'::text,'a soufflé'::text,'souffle'::text,'Le berger souffle dans sa corne sur la colline depuis tôt ce matin.'::text),
(361061,40118,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Çoban sabahın erken saatlerinden beri yamaçta borusunu ...'::text,'çalıyor'::text,'çaldı'::text,'çalar'::text,'Çoban sabahın erken saatlerinden beri yamaçta borusunu çalıyor.'::text),
(361062,40118,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A pásztor kora reggel óta ... a kürtjét a domboldalon.'::text,'fújja'::text,'megfújta'::text,'fújja'::text,'A pásztor kora reggel óta fújja a kürtjét a domboldalon.'::text),
(382980,42554,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Burg, ... Mauern jetzt eine Ruine sind, steht auf einem Hügel über der Stadt.'::text,'deren'::text,'die'::text,'die'::text,'Die Burg, deren Mauern jetzt eine Ruine sind, steht auf einem Hügel über der Stadt.'::text),
(382984,42554,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Замок, ... стіни тепер руїна, стоїть на пагорбі над містом.'::text,'чиї'::text,'який'::text,'що'::text,'Замок, чиї стіни тепер руїна, стоїть на пагорбі над містом.'::text),
(382983,42554,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El castillo, ... muros son ahora una ruina, se alza sobre una colina por encima del pueblo.'::text,'cuyos'::text,'que'::text,'que'::text,'El castillo, cuyos muros son ahora una ruina, se alza sobre una colina por encima del pueblo.'::text),
(382982,42554,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le château, ... les murs sont aujourd''hui en ruine, se dresse sur une colline au-dessus de la ville.'::text,'dont'::text,'qui'::text,'que'::text,'Le château, dont les murs sont aujourd''hui en ruine, se dresse sur une colline au-dessus de la ville.'::text),
(382985,42554,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... duvarları artık yıkıntı olan kale, kasabanın üstündeki bir tepede duruyor.'::text,''::text,NULL::text,NULL::text,'Duvarları artık yıkıntı olan kale, kasabanın üstündeki bir tepede duruyor.'::text),
(382986,42554,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A vár, ... falai mára romok, egy dombon áll a város felett.'::text,'amelynek a'::text,'amely'::text,'ami'::text,'A vár, amelynek a falai mára romok, egy dombon áll a város felett.'::text),
(335028,37226,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Frau, ... Blazer beige ist, riecht an einem Papierteststreifen.'::text,'deren'::text,'die'::text,'welche'::text,'Die Frau, deren Blazer beige ist, riecht an einem Papierteststreifen.'::text),
(335032,37226,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Жінка, ... блейзер бежевий, нюхає паперову тест-смужку.'::text,'чий'::text,'яка'::text,'який'::text,'Жінка, чий блейзер бежевий, нюхає паперову тест-смужку.'::text),
(335031,37226,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La mujer ... blazer es beige huele una tira de papel de prueba.'::text,'cuyo'::text,'que'::text,'el cual'::text,'La mujer cuyo blazer es beige huele una tira de papel de prueba.'::text),
(335030,37226,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La femme ... le blazer est beige sent une mouillette en papier.'::text,'dont'::text,'qui'::text,'lequel'::text,'La femme dont le blazer est beige sent une mouillette en papier.'::text),
(335033,37226,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... blazerı bej olan kadın bir kâğıt test şeridini kokluyor.'::text,''::text,NULL::text,NULL::text,'Blazerı bej olan kadın bir kâğıt test şeridini kokluyor.'::text),
(335034,37226,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A nő, ... a blézere bézs, egy papír tesztcsíkot szagol.'::text,'akinek'::text,'aki'::text,'amely'::text,'A nő, akinek a blézere bézs, egy papír tesztcsíkot szagol.'::text),
(335064,37230,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... gerade in diesem Blazer an ihrer dritten Flasche. Leicht unentschlossen.'::text,'riecht'::text,'riecht'::text,'hat gerochen'::text,'Sie riecht gerade in diesem Blazer an ihrer dritten Flasche. Leicht unentschlossen.'::text),
(335068,37230,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона ... свій третій флакон у цьому блейзері прямо зараз. Трохи нерішуча.'::text,'нюхає'::text,'нюхає'::text,'понюхала'::text,'Вона нюхає свій третій флакон у цьому блейзері прямо зараз. Трохи нерішуча.'::text),
(335067,37230,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ella ... su tercer frasco con ese blazer ahora mismo. Levemente indecisa.'::text,'está oliendo'::text,'huele'::text,'ha olido'::text,'Ella está oliendo su tercer frasco con ese blazer ahora mismo. Levemente indecisa.'::text),
(335066,37230,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ... son troisième flacon dans ce blazer en ce moment. Légèrement indécise.'::text,'est en train de sentir'::text,'sent'::text,'a senti'::text,'Elle est en train de sentir son troisième flacon dans ce blazer en ce moment. Légèrement indécise.'::text),
(335069,37230,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O şu anda o blazerla ... üçüncü şişesini. Hafif kararsız.'::text,'kokluyor'::text,'koklar'::text,'kokladı'::text,'O şu anda o blazerla kokluyor üçüncü şişesini. Hafif kararsız.'::text),
(335070,37230,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő éppen most ... a harmadik üvegét abban a blézerben. Enyhén határozatlan.'::text,'szagolja'::text,'szagolja'::text,'megszagolta'::text,'Ő éppen most szagolja a harmadik üvegét abban a blézerben. Enyhén határozatlan.'::text),
(396381,44043,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Schlange ist eine echte Bedrohung, und sie ... jeden, der näher kommt.'::text,'beißt'::text,'wird beißen'::text,'beißt gerade'::text,'Die Schlange ist eine echte Bedrohung, und sie beißt jeden, der näher kommt.'::text),
(396385,44043,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Змія — справжня загроза, і вона ... кожного, хто підійде ближче.'::text,'вкусить'::text,'кусатиме'::text,'кусає'::text,'Змія — справжня загроза, і вона вкусить кожного, хто підійде ближче.'::text),
(396384,44043,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La serpiente es una amenaza real, y ... a cualquiera que se acerque.'::text,'morderá'::text,'estará mordiendo'::text,'está mordiendo'::text,'La serpiente es una amenaza real, y morderá a cualquiera que se acerque.'::text),
(396383,44043,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le serpent est une vraie menace, et il ... quiconque s''approche.'::text,'mordra'::text,'sera en train de mordre'::text,'mord'::text,'Le serpent est une vraie menace, et il mordra quiconque s''approche.'::text),
(396386,44043,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yılan gerçek bir tehdit ve yaklaşan herkesi ...'::text,'ısıracak'::text,'ısırıyor olacak'::text,'ısırıyor'::text,'Yılan gerçek bir tehdit ve yaklaşan herkesi ısıracak.'::text),
