(335451,37273,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Blüte bringt ihn zum Niesen, ...?'::text,'oder'::text,'nicht'::text,'nicht wahr'::text,'Die Blüte bringt ihn zum Niesen, oder?'::text),
