(389202,43245,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para cuando ella se seque las manos, el jabón ... toda la suciedad.'::text,'habrá quitado'::text,'quitará'::text,'quita'::text,'Para cuando ella se seque las manos, el jabón habrá quitado toda la suciedad.'::text),
