(389752,43306,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Простора канапа, ... він хотів лише для себе, була повністю захоплена!'::text,'яку'::text,'хто'::text,'де'::text,'Простора канапа, яку він хотів лише для себе, була повністю захоплена!'::text),
(389751,43306,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡El sofá espacioso ... él quería para sí mismo fue completamente invadido!'::text,'que'::text,'quien'::text,'donde'::text,'¡El sofá espacioso que él quería para sí mismo fue completamente invadido!'::text),
(389750,43306,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le canapé spacieux ... voulait pour lui tout seul a été complètement envahi !'::text,'qu''il'::text,'qui'::text,'où il'::text,'Le canapé spacieux qu''il voulait pour lui tout seul a été complètement envahi !'::text),
(389753,43306,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... onun kendisi için istediği geniş kanepe tamamen işgal edildi!'::text,''::text,NULL::text,NULL::text,'Onun kendisi için istediği geniş kanepe tamamen işgal edildi!'::text),
(389754,43306,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A tágas kanapé, ... ő magának akart, teljesen megszállás alá került!'::text,'amit'::text,'aki'::text,'ahol'::text,'A tágas kanapé, amit ő magának akart, teljesen megszállás alá került!'::text),
(389811,43313,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... eine Minute allein auf dem geräumigen Sofa, bevor seine Freunde hereinstürmten.'::text,'saß'::text,'sitzt schon'::text,'sitzt'::text,'Er saß eine Minute allein auf dem geräumigen Sofa, bevor seine Freunde hereinstürmten.'::text),
(389815,43313,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він ... сам на просторій канапі хвилину, перш ніж забігли друзі.'::text,'сидів'::text,'сидить'::text,'сидить'::text,'Він сидів сам на просторій канапі хвилину, перш ніж забігли друзі.'::text),
(389814,43313,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Él ... solo en el sofá espacioso durante un minuto antes de que entraran corriendo sus amigos.'::text,'había estado sentado'::text,'ha estado sentado'::text,'está sentado'::text,'Él había estado sentado solo en el sofá espacioso durante un minuto antes de que entraran corriendo sus amigos.'::text),
(389813,43313,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... seul sur le canapé spacieux pendant une minute avant que ses amis n''entrent en courant.'::text,'était resté assis'::text,'est resté assis'::text,'est assis'::text,'Il était resté assis seul sur le canapé spacieux pendant une minute avant que ses amis n''entrent en courant.'::text),
