(337458,37496,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Du ... ihre Hand, als sie plötzlich ruhig wurde. Ehrlich, das ist echt cool.'::text,'hieltest gerade'::text,'hieltest'::text,'hast gehalten'::text,'Du hieltest gerade ihre Hand, als sie plötzlich ruhig wurde. Ehrlich, das ist echt cool.'::text),
(337462,37496,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ти ... її за руку, коли вона раптом заспокоїлася. Чесно, це реально круто.'::text,'тримав'::text,'взяв'::text,'взяв'::text,'Ти тримав її за руку, коли вона раптом заспокоїлася. Чесно, це реально круто.'::text),
(337461,37496,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tú le ... la mano cuando de repente se calmó. Sinceramente, eso es muy guay.'::text,'estabas cogiendo'::text,'cogiste'::text,'has cogido'::text,'Tú le estabas cogiendo la mano cuando de repente se calmó. Sinceramente, eso es muy guay.'::text),
(337460,37496,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tu lui ... la main quand elle s''est soudain calmée. Franchement, c''est vraiment cool.'::text,'tenais'::text,'as tenu'::text,'as tenu'::text,'Tu lui tenais la main quand elle s''est soudain calmée. Franchement, c''est vraiment cool.'::text),
(337463,37496,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O aniden sakinleştiğinde sen ... onun elini. Açıkçası, bu gerçekten havalı.'::text,'tutuyordun'::text,'tuttun'::text,'tuttun'::text,'O aniden sakinleştiğinde sen tutuyordun onun elini. Açıkçası, bu gerçekten havalı.'::text),
