(337552,37506,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, до півночі ти знову її ...; ти в цьому якийсь неймовірний.'::text,'заспокоїш'::text,'заспокоїш'::text,'заспокоюєш'::text,'Чесно, до півночі ти знову її заспокоїш; ти в цьому якийсь неймовірний.'::text),
(337551,37506,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sinceramente, para medianoche tú la ... otra vez; eres increíble en esto.'::text,'habrás calmado'::text,'calmarás'::text,'calmas'::text,'Sinceramente, para medianoche tú la habrás calmado otra vez; eres increíble en esto.'::text),
(337550,37506,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, d''ici minuit, tu ... de nouveau ; t''es grave doué pour ça.'::text,'l''auras calmée'::text,'la calmeras'::text,'la calmes'::text,'Franchement, d''ici minuit, tu l''auras calmée de nouveau ; t''es grave doué pour ça.'::text),
(337553,37506,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası, gece yarısına kadar sen onu yine ...; bu konuda resmen harikasın.'::text,'sakinleştirmiş olacaksın'::text,'sakinleştireceksin'::text,'sakinleştiriyorsun'::text,'Açıkçası, gece yarısına kadar sen onu yine sakinleştirmiş olacaksın; bu konuda resmen harikasın.'::text),
(337554,37506,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, éjfélre te újra ... őt; valahogy elképesztő vagy ebben.'::text,'megnyugtatod'::text,'meg fogod nyugtatni'::text,'megnyugtatod'::text,'Őszintén, éjfélre te újra megnyugtatod őt; valahogy elképesztő vagy ebben.'::text),
(332706,36968,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er hat bisher vier Spieße im Garten ...'::text,'gegrillt'::text,'gegrillt'::text,'am Grillen'::text,'Er hat bisher vier Spieße im Garten gegrillt.'::text),
(332710,36968,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він уже ... чотири шашлички на подвір''ї.'::text,'засмажив'::text,'смажив'::text,'смажить'::text,'Він уже засмажив чотири шашлички на подвір''ї.'::text),
(332709,36968,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Él ... cuatro brochetas en el patio hasta ahora.'::text,'ha asado'::text,'ha estado asando'::text,'está asando'::text,'Él ha asado cuatro brochetas en el patio hasta ahora.'::text),
(332708,36968,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... quatre brochettes dans le jardin jusqu''ici.'::text,'a grillé'::text,'a grillé'::text,'grille'::text,'Il a grillé quatre brochettes dans le jardin jusqu''ici.'::text),
(332711,36968,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O şimdiye kadar arka bahçede dört şiş ...'::text,'pişirdi'::text,'pişirip duruyor'::text,'pişiriyor'::text,'O şimdiye kadar arka bahçede dört şiş pişirdi.'::text),
(332712,36968,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő eddig négy nyársat ... a hátsó udvarban.'::text,'grillezett meg'::text,'grillezett'::text,'grillez'::text,'Ő eddig négy nyársat grillezett meg a hátsó udvarban.'::text),
(332760,36974,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gerade ... du die beste Wurst in diesem Garten, ehrlich.'::text,'grillst'::text,'grillst'::text,'hast gegrillt'::text,'Gerade grillst du die beste Wurst in diesem Garten, ehrlich.'::text),
(332764,36974,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Прямо зараз ти ... найкращу ковбаску на цьому подвір''ї, чесно.'::text,'смажиш'::text,'смажиш'::text,'засмажив'::text,'Прямо зараз ти смажиш найкращу ковбаску на цьому подвір''ї, чесно.'::text),
(332763,36974,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ahora mismo tú ... la mejor salchicha de este patio, de verdad.'::text,'estás asando'::text,'asas'::text,'has asado'::text,'Ahora mismo tú estás asando la mejor salchicha de este patio, de verdad.'::text),
(332762,36974,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En ce moment, tu ... la meilleure saucisse de ce jardin, franchement.'::text,'grilles'::text,'grilles'::text,'as grillé'::text,'En ce moment, tu grilles la meilleure saucisse de ce jardin, franchement.'::text),
(332765,36974,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Şu anda sen bu bahçedeki en iyi sosisi ..., açıkçası.'::text,'pişiriyorsun'::text,'pişirirsin'::text,'pişirdin'::text,'Şu anda sen bu bahçedeki en iyi sosisi pişiriyorsun, açıkçası.'::text),
(332766,36974,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Épp most te ... a legjobb kolbászt ebben a hátsó udvarban, őszintén.'::text,'grillezed'::text,'grillezed'::text,'grillezted'::text,'Épp most te grillezed a legjobb kolbászt ebben a hátsó udvarban, őszintén.'::text),
(371064,41230,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn die Neonschilder noch heller wären, ... sie um Mitternacht eine Sonnenbrille. Perfekte Beleuchtung.'::text,'bräuchte'::text,'wird brauchen'::text,'braucht'::text,'Wenn die Neonschilder noch heller wären, bräuchte sie um Mitternacht eine Sonnenbrille. Perfekte Beleuchtung.'::text),
(371068,41230,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби неонові вивіски були ще яскравішими, вона ... сонцезахисних окулярів опівночі. Бездоганне освітлення.'::text,'потребувала б'::text,'потребуватиме'::text,'потребує'::text,'Якби неонові вивіски були ще яскравішими, вона потребувала б сонцезахисних окулярів опівночі. Бездоганне освітлення.'::text),
(371067,41230,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si los letreros de neón fueran aún más brillantes, ella ... gafas de sol a medianoche. Iluminación impecable.'::text,'necesitaría'::text,'necesitará'::text,'necesita'::text,'Si los letreros de neón fueran aún más brillantes, ella necesitaría gafas de sol a medianoche. Iluminación impecable.'::text),
(371066,41230,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si les enseignes au néon étaient encore plus lumineuses, elle ... de lunettes de soleil à minuit. Éclairage impeccable.'::text,'aurait besoin'::text,'aura besoin'::text,'a besoin'::text,'Si les enseignes au néon étaient encore plus lumineuses, elle aurait besoin de lunettes de soleil à minuit. Éclairage impeccable.'::text),
(371069,41230,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Neon tabelalar biraz daha parlak olsaydı, o gece yarısı ... güneş gözlüğüne. Kusursuz aydınlatma.'::text,'ihtiyaç duyardı'::text,'ihtiyaç duyacak'::text,'ihtiyaç duyuyor'::text,'Neon tabelalar biraz daha parlak olsaydı, o gece yarısı ihtiyaç duyardı güneş gözlüğüne. Kusursuz aydınlatma.'::text),
(371070,41230,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a neonfeliratok még fényesebbek lennének, ő ... napszemüvegre éjfélkor. Hibátlan világítás.'::text,'szorulna'::text,'szorul majd'::text,'szorul'::text,'Ha a neonfeliratok még fényesebbek lennének, ő szorulna napszemüvegre éjfélkor. Hibátlan világítás.'::text),
(371118,41236,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Straße war ... der späten Stunde hell, dank der Neonschilder.'::text,'trotz'::text,'wegen'::text,'vorausgesetzt'::text,'Die Straße war trotz der späten Stunde hell, dank der Neonschilder.'::text),
(371122,41236,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вулиця була яскравою ... пізню годину завдяки неоновим вивіскам.'::text,'попри'::text,'через'::text,'за умови'::text,'Вулиця була яскравою попри пізню годину завдяки неоновим вивіскам.'::text),
(371121,41236,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La calle estaba iluminada ... la hora tardía, gracias a los letreros de neón.'::text,'a pesar de'::text,'debido a'::text,'siempre que'::text,'La calle estaba iluminada a pesar de la hora tardía, gracias a los letreros de neón.'::text),
(371120,41236,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La rue était lumineuse ... l''heure tardive, grâce aux enseignes au néon.'::text,'malgré'::text,'en raison de'::text,'pourvu que'::text,'La rue était lumineuse malgré l''heure tardive, grâce aux enseignes au néon.'::text),
(371123,41236,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Neon tabelalar sayesinde sokak geç saate ... aydınlıktı.'::text,'rağmen'::text,'bağlı olarak'::text,'koşuluyla'::text,'Neon tabelalar sayesinde sokak geç saate rağmen aydınlıktı.'::text),
(371124,41236,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az utca a késői óra ... világos volt, a neonfeliratoknak köszönhetően.'::text,'ellenére'::text,'miatt'::text,'feltéve'::text,'Az utca a késői óra ellenére világos volt, a neonfeliratoknak köszönhetően.'::text),
(345495,38389,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ihre Haare bilden feste Ringe, also ... sie von Natur aus lockig sein.'::text,'müssen'::text,'können nicht'::text,'sollten nicht'::text,'Ihre Haare bilden feste Ringe, also müssen sie von Natur aus lockig sein.'::text),
(345499,38389,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Її волосся утворює тугі кільця, тож воно ... бути від природи кучерявим.'::text,'має'::text,'не може'::text,'не повинно'::text,'Її волосся утворює тугі кільця, тож воно має бути від природи кучерявим.'::text),
(345498,38389,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Su pelo forma rizos apretados, así que ... ser rizado natural.'::text,'debe de'::text,'no puede'::text,'no debería'::text,'Su pelo forma rizos apretados, así que debe de ser rizado natural.'::text),
(345497,38389,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ses cheveux forment des boucles serrées, donc ils ... être naturellement bouclés.'::text,'doivent'::text,'ne peuvent pas'::text,'ne devraient pas'::text,'Ses cheveux forment des boucles serrées, donc ils doivent être naturellement bouclés.'::text),
(345500,38389,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Saçları sıkı halkalar oluşturuyor, yani doğal olarak kıvırcık ...'::text,'olmalı'::text,'olamaz'::text,'olmamalı'::text,'Saçları sıkı halkalar oluşturuyor, yani doğal olarak kıvırcık olmalı.'::text),
(345501,38389,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A haja szoros gyűrűket formál, szóval ... természetesen göndör.'::text,'biztosan'::text,'nem lehet'::text,'nem kellene'::text,'A haja szoros gyűrűket formál, szóval biztosan természetesen göndör.'::text),
(382782,42532,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Perfektes Timing: Die Rüschen ... um ihre Beine, als die zwei Frauen zu klatschen begannen.'::text,'wirbelten'::text,'wirbelten'::text,'sind gewirbelt'::text,'Perfektes Timing: Die Rüschen wirbelten um ihre Beine, als die zwei Frauen zu klatschen begannen.'::text),
(382786,42532,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бездоганний таймінг: волани ... навколо її ніг, коли дві жінки почали плескати.'::text,'кружляли'::text,'закружляли'::text,'закружляли'::text,'Бездоганний таймінг: волани кружляли навколо її ніг, коли дві жінки почали плескати.'::text),
(382785,42532,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Timing perfecto: los volantes ... alrededor de sus piernas cuando las dos mujeres empezaron a aplaudir.'::text,'giraban'::text,'giraron'::text,'han girado'::text,'Timing perfecto: los volantes giraban alrededor de sus piernas cuando las dos mujeres empezaron a aplaudir.'::text),
(382784,42532,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Timing parfait : les volants ... autour de ses jambes quand les deux femmes ont commencé à applaudir.'::text,'tourbillonnaient'::text,'ont tourbillonné'::text,'ont tourbillonné'::text,'Timing parfait : les volants tourbillonnaient autour de ses jambes quand les deux femmes ont commencé à applaudir.'::text),
(382787,42532,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kusursuz zamanlama: iki kadın alkışlamaya başladığında fırfırlar bacaklarının etrafında ...'::text,'savruluyordu'::text,'savruldu'::text,'savrulmuş'::text,'Kusursuz zamanlama: iki kadın alkışlamaya başladığında fırfırlar bacaklarının etrafında savruluyordu.'::text),
(382788,42532,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tökéletes időzítés: a fodrok ... a lába körül, amikor a két nő tapsolni kezdett.'::text,'kavarogtak'::text,'megpördültek'::text,'megpördültek'::text,'Tökéletes időzítés: a fodrok kavarogtak a lába körül, amikor a két nő tapsolni kezdett.'::text),
(382872,42542,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, bis zu deiner letzten Drehung ... du jede Rüsche an diesem Kleid fliegen lassen.'::text,'hast'::text,'wirst'::text,'lässt'::text,'Ehrlich, bis zu deiner letzten Drehung hast du jede Rüsche an diesem Kleid fliegen lassen.'::text),
(382876,42542,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, до твого останнього оберту ти ... злетіти кожен волан на цій сукні.'::text,'змусиш'::text,'змусиш'::text,'змушуєш'::text,'Чесно, до твого останнього оберту ти змусиш злетіти кожен волан на цій сукні.'::text),
(382875,42542,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sinceramente, para tu último giro, tú ... volar cada volante de ese vestido.'::text,'habrás hecho'::text,'harás'::text,'haces'::text,'Sinceramente, para tu último giro, tú habrás hecho volar cada volante de ese vestido.'::text),
(382874,42542,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, d''ici ton dernier tour, tu ... voler chaque volant de cette robe.'::text,'auras fait'::text,'feras'::text,'fais'::text,'Franchement, d''ici ton dernier tour, tu auras fait voler chaque volant de cette robe.'::text),
(382877,42542,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası, son dönüşüne kadar sen o elbisedeki her fırfırı ...'::text,'uçurmuş olacaksın'::text,'uçuracaksın'::text,'uçuruyorsun'::text,'Açıkçası, son dönüşüne kadar sen o elbisedeki her fırfırı uçurmuş olacaksın.'::text),
(382878,42542,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, az utolsó pörgésedig te ... a ruha minden fodrát.'::text,'már felrepíted'::text,'fel fogod repíteni'::text,'felrepíted'::text,'Őszintén, az utolsó pörgésedig te már felrepíted a ruha minden fodrát.'::text),
(346431,38493,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie zeigt eine Dehnung nie nur halb vor, und er ... – absolut nie!'::text,'genauso wenig'::text,'genauso'::text,'genauso wenig'::text,'Sie zeigt eine Dehnung nie nur halb vor, und er genauso wenig – absolut nie!'::text),
(346435,38493,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона ніколи не показує розтяжку наполовину, і він ... — абсолютно ніколи!'::text,'теж ні'::text,'теж'::text,'теж ні'::text,'Вона ніколи не показує розтяжку наполовину, і він теж ні — абсолютно ніколи!'::text),
(346434,38493,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ella nunca demuestra un estiramiento a medias, y ... él. ¡Absolutamente nunca!'::text,'tampoco'::text,'también'::text,'tampoco'::text,'Ella nunca demuestra un estiramiento a medias, y tampoco él. ¡Absolutamente nunca!'::text),
(346433,38493,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ne montre jamais un étirement à moitié, et lui ..., absolument jamais !'::text,'non plus'::text,'aussi'::text,'non plus'::text,'Elle ne montre jamais un étirement à moitié, et lui non plus, absolument jamais !'::text),
(346436,38493,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O bir esnemeyi asla yarım yamalak göstermez, o da ...! Kesinlikle asla!'::text,'göstermez'::text,'gösterir'::text,'göstermez'::text,'O bir esnemeyi asla yarım yamalak göstermez, o da göstermez! Kesinlikle asla!'::text),
(346437,38493,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő soha nem mutat be félig egy nyújtást, és ő ..., abszolút soha!'::text,'sem'::text,'is'::text,'sem'::text,'Ő soha nem mutat be félig egy nyújtást, és ő sem, abszolút soha!'::text),
(346467,38497,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn sie die Dehnung nicht vorgemacht hätte, ... er die Arme falsch gehoben.'::text,'hätte'::text,'würde'::text,'hat'::text,'Wenn sie die Dehnung nicht vorgemacht hätte, hätte er die Arme falsch gehoben.'::text),
(346471,38497,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби вона не показала розтяжку, він ... руки неправильно.'::text,'підняв би'::text,'підняв би'::text,'підняв'::text,'Якби вона не показала розтяжку, він підняв би руки неправильно.'::text),
(346470,38497,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si no hubiera demostrado el estiramiento, él ... los brazos de forma incorrecta.'::text,'habría levantado'::text,'levantaría'::text,'levantó'::text,'Si no hubiera demostrado el estiramiento, él habría levantado los brazos de forma incorrecta.'::text),
(346469,38497,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si elle n''avait pas montré l''étirement, il ... les bras de travers.'::text,'aurait levé'::text,'lèverait'::text,'a levé'::text,'Si elle n''avait pas montré l''étirement, il aurait levé les bras de travers.'::text),
(346472,38497,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Esnemeyi göstermeseydi, o kollarını yanlış ...'::text,'kaldırmış olurdu'::text,'kaldırırdı'::text,'kaldırdı'::text,'Esnemeyi göstermeseydi, o kollarını yanlış kaldırmış olurdu.'::text),
(346473,38497,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha nem mutatta volna be a nyújtást, ő rosszul ... a karját.'::text,'emelte volna fel'::text,'emelné fel'::text,'emelte fel'::text,'Ha nem mutatta volna be a nyújtást, ő rosszul emelte volna fel a karját.'::text),
(390837,43427,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die grüne Suppe wurde vom Subjekt ..., was auf starke Abneigung hinweist.'::text,'ausgespuckt'::text,'ausspuckte'::text,'ausspuckend'::text,'Die grüne Suppe wurde vom Subjekt ausgespuckt, was auf starke Abneigung hinweist.'::text),
(390841,43427,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Зелений суп ... суб''єктом, що вказує на сильну відразу.'::text,'був виплюнутий'::text,'виплюнув'::text,'випльовуючи'::text,'Зелений суп був виплюнутий суб''єктом, що вказує на сильну відразу.'::text),
(390840,43427,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La sopa verde ... por el sujeto, lo cual indica un fuerte rechazo.'::text,'fue escupida'::text,'escupió'::text,'escupiendo'::text,'La sopa verde fue escupida por el sujeto, lo cual indica un fuerte rechazo.'::text),
(390839,43427,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La soupe verte ... par le sujet, ce qui indique un fort dégoût.'::text,'a été recrachée'::text,'a recraché'::text,'recrachant'::text,'La soupe verte a été recrachée par le sujet, ce qui indique un fort dégoût.'::text),
(390842,43427,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yeşil çorba denek tarafından ..., bu da güçlü bir hoşnutsuzluğa işaret ediyor.'::text,'tükürüldü'::text,'tükürdü'::text,'tükürerek'::text,'Yeşil çorba denek tarafından tükürüldü, bu da güçlü bir hoşnutsuzluğa işaret ediyor.'::text),
(390843,43427,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A zöld levest az alany ..., ami erős ellenszenvre utal.'::text,'kiköpte'::text,'kiköpték'::text,'kiköpve'::text,'A zöld levest az alany kiköpte, ami erős ellenszenvre utal.'::text),
(391044,43450,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, du und dein Ehepartner genießt es offensichtlich, alles als Team ...'::text,'zu machen'::text,'zu machen'::text,'machen'::text,'Ehrlich, du und dein Ehepartner genießt es offensichtlich, alles als Team zu machen.'::text),
(391048,43450,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, ти і твій чоловік явно любите ... все разом як команда.'::text,'робити'::text,'робити'::text,'робите'::text,'Чесно, ти і твій чоловік явно любите робити все разом як команда.'::text),
(391047,43450,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sinceramente, tú y tu pareja claramente disfrutáis ... todo en equipo.'::text,'haciendo'::text,'hacer'::text,'hacéis'::text,'Sinceramente, tú y tu pareja claramente disfrutáis haciendo todo en equipo.'::text),
(391046,43450,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, toi et ton conjoint, vous aimez clairement ... tout en équipe.'::text,'faire'::text,'faire'::text,'faites'::text,'Franchement, toi et ton conjoint, vous aimez clairement faire tout en équipe.'::text),
(391049,43450,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası sen ve eşin belli ki her şeyi takım olarak ... seviyorsunuz.'::text,'yapmayı'::text,'yapmayı'::text,'yapıyorsunuz'::text,'Açıkçası sen ve eşin belli ki her şeyi takım olarak yapmayı seviyorsunuz.'::text),
(391050,43450,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, te és a házastársad láthatóan szerettek mindent csapatként ...'::text,'csinálni'::text,'csinálni'::text,'csináltok'::text,'Őszintén, te és a házastársad láthatóan szerettek mindent csapatként csinálni.'::text),
(391053,43451,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Du und dein Ehepartner ... seit dem Tag eurer Hochzeit als Team, und ehrlich, Respekt.'::text,'arbeitet'::text,'arbeitet gerade'::text,'arbeitet'::text,'Du und dein Ehepartner arbeitet seit dem Tag eurer Hochzeit als Team, und ehrlich, Respekt.'::text),
(391057,43451,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ти і твій чоловік ... як команда з дня весілля, і, чесно, респект.'::text,'працюєте'::text,'працюєте'::text,'працюєте'::text,'Ти і твій чоловік працюєте як команда з дня весілля, і, чесно, респект.'::text),
(391056,43451,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tú y tu pareja ... en equipo desde el día en que os casasteis y, sinceramente, respeto.'::text,'habéis trabajado'::text,'estáis trabajando'::text,'trabajáis'::text,'Tú y tu pareja habéis trabajado en equipo desde el día en que os casasteis y, sinceramente, respeto.'::text),
(391055,43451,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Toi et ton conjoint, vous ... en équipe depuis le jour de votre mariage, et franchement, respect.'::text,'travaillez'::text,'êtes en train de travailler'::text,'travaillez'::text,'Toi et ton conjoint, vous travaillez en équipe depuis le jour de votre mariage, et franchement, respect.'::text),
(391058,43451,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sen ve eşin evlendiğiniz günden beri takım olarak ... ve açıkçası, saygı.'::text,'çalışıyorsunuz'::text,'çalışıyorsunuz'::text,'çalışırsınız'::text,'Sen ve eşin evlendiğiniz günden beri takım olarak çalışıyorsunuz ve açıkçası, saygı.'::text),
(391059,43451,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Te és a házastársad az esküvőtök napja óta csapatként ..., és őszintén, respekt.'::text,'dolgoztok'::text,'dolgoztok'::text,'dolgoztok'::text,'Te és a házastársad az esküvőtök napja óta csapatként dolgoztok, és őszintén, respekt.'::text),
(338205,37579,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rate mal, sie hat sich anscheinend in diesem schwarzen Umhang die Haare ... lassen.'::text,'machen'::text,'machen'::text,'machend'::text,'Rate mal, sie hat sich anscheinend in diesem schwarzen Umhang die Haare machen lassen.'::text),
(338209,37579,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Уяви, вона, кажуть, ... зачіску в тій чорній накидці.'::text,'зробила'::text,'зробила'::text,'робила'::text,'Уяви, вона, кажуть, зробила зачіску в тій чорній накидці.'::text),
(338208,37579,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Adivina qué: al parecer ella se mandó ... el pelo con esa capa negra.'::text,'arreglar'::text,'arreglar'::text,'arreglando'::text,'Adivina qué: al parecer ella se mandó arreglar el pelo con esa capa negra.'::text),
(338207,37579,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Devine quoi, elle s''est fait ... les cheveux avec cette cape noire, apparemment.'::text,'coiffer'::text,'coiffer'::text,'coiffant'::text,'Devine quoi, elle s''est fait coiffer les cheveux avec cette cape noire, apparemment.'::text),
(338210,37579,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bil bakalım, duyduğuma göre o, siyah pelerinin içinde saçını ...'::text,'yaptırmış'::text,'yapmış'::text,'yaparak'::text,'Bil bakalım, duyduğuma göre o, siyah pelerinin içinde saçını yaptırmış.'::text),
(338211,37579,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Képzeld, ő állítólag abban a fekete beterítőben ... a haját.'::text,'megcsináltatta'::text,'megcsinálta'::text,'csinálva'::text,'Képzeld, ő állítólag abban a fekete beterítőben megcsináltatta a haját.'::text),
(353721,39303,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hör zu, sie hat mir erzählt, dass ihr Fitnessprogramm am Tag davor um 5 Uhr morgens ...'::text,'begonnen hatte'::text,'begonnen hat'::text,'beginnt'::text,'Hör zu, sie hat mir erzählt, dass ihr Fitnessprogramm am Tag davor um 5 Uhr morgens begonnen hatte.'::text),
(353725,39303,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, вона сказала мені, що її фітнес-режим ... о 5 ранку напередодні.'::text,'почався'::text,'почався'::text,'починається'::text,'Слухай, вона сказала мені, що її фітнес-режим почався о 5 ранку напередодні.'::text),
(353724,39303,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Escucha, ella me dijo que su rutina de ejercicio ... a las 5 de la mañana el día anterior.'::text,'había empezado'::text,'ha empezado'::text,'empieza'::text,'Escucha, ella me dijo que su rutina de ejercicio había empezado a las 5 de la mañana el día anterior.'::text),
(353723,39303,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, elle m''a dit que sa routine sportive ... à 5 h du matin la veille.'::text,'avait commencé'::text,'a commencé'::text,'commence'::text,'Écoute, elle m''a dit que sa routine sportive avait commencé à 5 h du matin la veille.'::text),
(353726,39303,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, o bana fitness rutininin bir gün önce sabah 5''te ... söyledi.'::text,'başlamış olduğunu'::text,'başladığını'::text,'başladığını'::text,'Dinle, o bana fitness rutininin bir gün önce sabah 5''te başlamış olduğunu söyledi.'::text),
(353727,39303,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, ő azt mondta nekem, hogy az edzésrutinja előző nap hajnali 5-kor ...'::text,'kezdődött'::text,'kezdődött'::text,'kezdődik'::text,'Figyelj, ő azt mondta nekem, hogy az edzésrutinja előző nap hajnali 5-kor kezdődött.'::text),
(399657,44407,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie jubeln als eine Gruppe, also ... ihr Zusammenhalt sehr stark sein.'::text,'muss'::text,'kann nicht'::text,'sollte'::text,'Sie jubeln als eine Gruppe, also muss ihr Zusammenhalt sehr stark sein.'::text),
(399661,44407,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вони вболівають як одна група, тож їхня єдність ... бути дуже сильною.'::text,'мусить'::text,'не може'::text,'повинна'::text,'Вони вболівають як одна група, тож їхня єдність мусить бути дуже сильною.'::text),
(399660,44407,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ellos animan como un solo grupo, así que su unidad ... ser muy fuerte.'::text,'debe de'::text,'no puede'::text,'debería'::text,'Ellos animan como un solo grupo, así que su unidad debe de ser muy fuerte.'::text),
(399659,44407,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ils applaudissent comme un seul groupe, donc leur unité ... être très forte.'::text,'doit'::text,'ne peut pas'::text,'devrait'::text,'Ils applaudissent comme un seul groupe, donc leur unité doit être très forte.'::text),
(399662,44407,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Onlar tek bir grup gibi tezahürat yapıyor, yani birlikleri çok güçlü ...'::text,'olmalı'::text,'olamaz'::text,'olmalı'::text,'Onlar tek bir grup gibi tezahürat yapıyor, yani birlikleri çok güçlü olmalı.'::text),
(399663,44407,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ők egyetlen csoportként ujjonganak, szóval az egységüknek ... nagyon erősnek.'::text,'kell lennie'::text,'nem lehet'::text,'kellene lennie'::text,'Ők egyetlen csoportként ujjonganak, szóval az egységüknek kell lennie nagyon erősnek.'::text),
(391440,43494,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er will auf der Marmortreppe ein Foto von sich ... lassen.'::text,'machen'::text,'machen'::text,'machend'::text,'Er will auf der Marmortreppe ein Foto von sich machen lassen.'::text),
(391444,43494,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він хоче, щоб його ... на мармурових сходах.'::text,'сфотографували'::text,'сфотографувати'::text,'фотографуючи'::text,'Він хоче, щоб його сфотографували на мармурових сходах.'::text),
(391443,43494,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Él quiere que le ... una foto en la escalera de mármol.'::text,'hagan'::text,'hacer'::text,'haciendo'::text,'Él quiere que le hagan una foto en la escalera de mármol.'::text),
(391442,43494,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il veut se faire ... en photo sur l''escalier en marbre.'::text,'prendre'::text,'prendre'::text,'prenant'::text,'Il veut se faire prendre en photo sur l''escalier en marbre.'::text),
(391445,43494,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O mermer merdivende fotoğrafını ... istiyor.'::text,'çektirmek'::text,'çekmek'::text,'çekerek'::text,'O mermer merdivende fotoğrafını çektirmek istiyor.'::text),
(391446,43494,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő le akarja ... magát a márványlépcsőn.'::text,'fotóztatni'::text,'fotózni'::text,'fotózva'::text,'Ő le akarja fotóztatni magát a márványlépcsőn.'::text),
(380316,42258,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Diese Fans ... diese Tradition schon seit über fünfzig Jahren.'::text,'respektieren'::text,'respektieren gerade'::text,'respektieren'::text,'Diese Fans respektieren diese Tradition schon seit über fünfzig Jahren.'::text),
(380320,42258,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ці фанати ... цю традицію вже понад п''ятдесят років.'::text,'шанують'::text,'шанують'::text,'шанують'::text,'Ці фанати шанують цю традицію вже понад п''ятдесят років.'::text),
(380319,42258,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Estos aficionados ... esta tradición desde hace más de cincuenta años.'::text,'vienen respetando'::text,'están respetando'::text,'respetan'::text,'Estos aficionados vienen respetando esta tradición desde hace más de cincuenta años.'::text),
(380318,42258,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ces supporters ... cette tradition depuis plus de cinquante ans.'::text,'respectent'::text,'sont en train de respecter'::text,'respectent'::text,'Ces supporters respectent cette tradition depuis plus de cinquante ans.'::text),
(380321,42258,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu taraftarlar elli yılı aşkın süredir bu geleneğe ...'::text,'saygı gösteriyor'::text,'saygı gösteriyor'::text,'saygı gösterir'::text,'Bu taraftarlar elli yılı aşkın süredir bu geleneğe saygı gösteriyor.'::text),
(380322,42258,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ezek a szurkolók már több mint ötven éve ... ezt a hagyományt.'::text,'tisztelik'::text,'tisztelik'::text,'tisztelik'::text,'Ezek a szurkolók már több mint ötven éve tisztelik ezt a hagyományt.'::text),
(380388,42266,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bemerkenswerterweise ... die Zuschauer die Tradition schon lange vor Beginn dieses Spiels respektiert.'::text,'hatten'::text,'haben'::text,'waren'::text,'Bemerkenswerterweise hatten die Zuschauer die Tradition schon lange vor Beginn dieses Spiels respektiert.'::text),
(380392,42266,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Примітно, що глядачі ... традицію задовго до початку цього матчу.'::text,'шанували'::text,'шанують'::text,'шанували'::text,'Примітно, що глядачі шанували традицію задовго до початку цього матчу.'::text),
(380391,42266,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sorprendentemente, los espectadores ... la tradición mucho antes de que empezara este partido.'::text,'habían respetado'::text,'han respetado'::text,'estaban respetando'::text,'Sorprendentemente, los espectadores habían respetado la tradición mucho antes de que empezara este partido.'::text),
(380390,42266,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Fait remarquable, les spectateurs ... la tradition bien avant le début de ce match.'::text,'avaient respecté'::text,'ont respecté'::text,'respectaient'::text,'Fait remarquable, les spectateurs avaient respecté la tradition bien avant le début de ce match.'::text),
(380393,42266,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dikkat çekici biçimde, seyirciler bu maç başlamadan çok önce geleneğe ...'::text,'saygı göstermişti'::text,'saygı gösterdi'::text,'saygı gösteriyordu'::text,'Dikkat çekici biçimde, seyirciler bu maç başlamadan çok önce geleneğe saygı göstermişti.'::text),
(380394,42266,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelemre méltó módon a nézők már jóval a meccs kezdete előtt ... a hagyományt.'::text,'tisztelték'::text,'tisztelik'::text,'tisztelték'::text,'Figyelemre méltó módon a nézők már jóval a meccs kezdete előtt tisztelték a hagyományt.'::text),
(350580,38954,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ohne Witz, sie kann nicht anders, als ... wie der begeistertste Fan überhaupt.'::text,'zu jubeln'::text,'zu jubeln'::text,'jubeln'::text,'Ohne Witz, sie kann nicht anders, als zu jubeln wie der begeistertste Fan überhaupt.'::text),
(350584,38954,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, вона не може не ... як найзапекліша фанатка.'::text,'вболівати'::text,'вболівати'::text,'вболіває'::text,'Чесно, вона не може не вболівати як найзапекліша фанатка.'::text),
(350583,38954,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'No voy a mentir, ella no puede parar de ... como la fan más entusiasta del mundo.'::text,'animar'::text,'animar'::text,'anima'::text,'No voy a mentir, ella no puede parar de animar como la fan más entusiasta del mundo.'::text),
(350582,38954,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sans mentir, elle ne peut pas s''empêcher ... comme la fan la plus enthousiaste de tous les temps.'::text,'d''acclamer'::text,'d''acclamer'::text,'acclame'::text,'Sans mentir, elle ne peut pas s''empêcher d''acclamer comme la fan la plus enthousiaste de tous les temps.'::text),
(350585,38954,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yalan yok, o dünyanın en coşkulu taraftarı gibi ... kendini alamıyor.'::text,'tezahürat yapmaktan'::text,'tezahürat yapmaktan'::text,'tezahürat yapıyor'::text,'Yalan yok, o dünyanın en coşkulu taraftarı gibi tezahürat yapmaktan kendini alamıyor.'::text),
(350586,38954,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nem kamu, ő nem tudja megállni, hogy ne ... úgy, mint minden idők leglelkesebb szurkolója.'::text,'szurkoljon'::text,'szurkoljon'::text,'szurkol'::text,'Nem kamu, ő nem tudja megállni, hogy ne szurkoljon úgy, mint minden idők leglelkesebb szurkolója.'::text),
(350607,38957,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis zum Schlusspfiff wird das Subjekt etwa 90 Minuten lang begeistert ...'::text,'gejubelt haben'::text,'jubeln'::text,'am Jubeln sein'::text,'Bis zum Schlusspfiff wird das Subjekt etwa 90 Minuten lang begeistert gejubelt haben.'::text),
(350611,38957,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До фінального свистка суб''єкт ... із захватом приблизно 90 хвилин.'::text,'вболіватиме'::text,'вболіватиме'::text,'вболіватиме'::text,'До фінального свистка суб''єкт вболіватиме із захватом приблизно 90 хвилин.'::text),
(350610,38957,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para el pitido final, el sujeto ... con entusiasmo durante aproximadamente 90 minutos.'::text,'habrá animado'::text,'animará'::text,'estará animando'::text,'Para el pitido final, el sujeto habrá animado con entusiasmo durante aproximadamente 90 minutos.'::text),
(350609,38957,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici le coup de sifflet final, le sujet ... avec enthousiasme pendant environ 90 minutes.'::text,'aura acclamé'::text,'acclamera'::text,'sera en train d''acclamer'::text,'D''ici le coup de sifflet final, le sujet aura acclamé avec enthousiasme pendant environ 90 minutes.'::text),
(350612,38957,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Son düdüğe kadar denek yaklaşık 90 dakika boyunca coşkuyla ...'::text,'tezahürat yapmış olacak'::text,'tezahürat yapacak'::text,'tezahürat yapıyor olacak'::text,'Son düdüğe kadar denek yaklaşık 90 dakika boyunca coşkuyla tezahürat yapmış olacak.'::text),
(350613,38957,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A lefújásig az alany lelkesen ... a körülbelül 90 percet.'::text,'végigszurkolja'::text,'szurkolni fog'::text,'szurkolni fog'::text,'A lefújásig az alany lelkesen végigszurkolja a körülbelül 90 percet.'::text),
(366744,40750,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Fan gab an, dass seine Treue etwa vierzig Jahre zuvor ...'::text,'begonnen hatte'::text,'begonnen hat'::text,'beginnt'::text,'Der Fan gab an, dass seine Treue etwa vierzig Jahre zuvor begonnen hatte.'::text),
(366748,40750,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Уболівальник заявив, що його вірність ... приблизно сорока роками раніше.'::text,'почалася'::text,'почалася'::text,'починається'::text,'Уболівальник заявив, що його вірність почалася приблизно сорока роками раніше.'::text),
(366747,40750,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El aficionado afirmó que su lealtad ... aproximadamente cuarenta años antes.'::text,'había empezado'::text,'ha empezado'::text,'empieza'::text,'El aficionado afirmó que su lealtad había empezado aproximadamente cuarenta años antes.'::text),
(366746,40750,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le supporter a déclaré que sa loyauté ... environ quarante ans plus tôt.'::text,'avait commencé'::text,'a commencé'::text,'commence'::text,'Le supporter a déclaré que sa loyauté avait commencé environ quarante ans plus tôt.'::text),
(366749,40750,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Taraftar, sadakatinin yaklaşık kırk yıl önce ... belirtti.'::text,'başlamış olduğunu'::text,'başladığını'::text,'başladığını'::text,'Taraftar, sadakatinin yaklaşık kırk yıl önce başlamış olduğunu belirtti.'::text),
(366750,40750,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A szurkoló kijelentette, hogy a hűsége körülbelül negyven évvel korábban ...'::text,'kezdődött'::text,'kezdődött'::text,'kezdődik'::text,'A szurkoló kijelentette, hogy a hűsége körülbelül negyven évvel korábban kezdődött.'::text),
(366780,40754,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Süße, anscheinend ... er seit den Achtzigern jede Woche in dieses Stadion, totale Treue.'::text,'kommt'::text,'kommt gerade'::text,'kommt'::text,'Süße, anscheinend kommt er seit den Achtzigern jede Woche in dieses Stadion, totale Treue.'::text),
(366784,40754,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, кажуть, він ... на цей стадіон щотижня з вісімдесятих, повна вірність.'::text,'ходить'::text,'ходить'::text,'ходить'::text,'Подруго, кажуть, він ходить на цей стадіон щотижня з вісімдесятих, повна вірність.'::text),
(366783,40754,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tía, al parecer él ... a este estadio cada semana desde los ochenta, lealtad total.'::text,'lleva viniendo'::text,'está viniendo'::text,'viene'::text,'Tía, al parecer él lleva viniendo a este estadio cada semana desde los ochenta, lealtad total.'::text),
(366782,40754,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Meuf, apparemment il ... dans ce stade chaque semaine depuis les années 80, loyauté totale.'::text,'vient'::text,'est en train de venir'::text,'vient'::text,'Meuf, apparemment il vient dans ce stade chaque semaine depuis les années 80, loyauté totale.'::text),
(366785,40754,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, duyduğuma göre o seksenlerden beri her hafta bu stadyuma ..., tam sadakat.'::text,'geliyormuş'::text,'geliyor'::text,'gelir'::text,'Kızım, duyduğuma göre o seksenlerden beri her hafta bu stadyuma geliyormuş, tam sadakat.'::text),
(366786,40754,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, állítólag ő ... ebbe a stadionba minden héten a nyolcvanas évek óta, teljes hűség.'::text,'jár'::text,'jön'::text,'jár'::text,'Csajszi, állítólag ő jár ebbe a stadionba minden héten a nyolcvanas évek óta, teljes hűség.'::text),
(378237,42027,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Morgen um diese Zeit wird er mit der Bahn quer durchs Land ...'::text,'reisen'::text,'reisen'::text,'reist'::text,'Morgen um diese Zeit wird er mit der Bahn quer durchs Land reisen.'::text),
(378241,42027,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Завтра в цей час він ... країною залізницею.'::text,'подорожуватиме'::text,'подорожуватиме'::text,'подорожує'::text,'Завтра в цей час він подорожуватиме країною залізницею.'::text),
(378240,42027,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mañana a esta hora, él ... por el país en tren.'::text,'estará viajando'::text,'viajará'::text,'viaja'::text,'Mañana a esta hora, él estará viajando por el país en tren.'::text),
(378239,42027,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Demain à la même heure, il ... à travers le pays en train.'::text,'sera en train de voyager'::text,'voyagera'::text,'voyage'::text,'Demain à la même heure, il sera en train de voyager à travers le pays en train.'::text),
(378242,42027,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yarın bu saatte o trenle ülkeyi boydan boya ...'::text,'geziyor olacak'::text,'gezecek'::text,'geziyor'::text,'Yarın bu saatte o trenle ülkeyi boydan boya geziyor olacak.'::text),
(378243,42027,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Holnap ilyenkor ő vonattal ... keresztül az országon.'::text,'fog utazni'::text,'utazik majd'::text,'utazik'::text,'Holnap ilyenkor ő vonattal fog utazni keresztül az országon.'::text),
(342372,38042,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie hat heute zwei Fahrzeuge ..., ohne sich einen Zentimeter zu bewegen. Wirklich legendäres Fahren.'::text,'gesteuert'::text,'gesteuert'::text,'am Steuern'::text,'Sie hat heute zwei Fahrzeuge gesteuert, ohne sich einen Zentimeter zu bewegen. Wirklich legendäres Fahren.'::text),
(342376,38042,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона сьогодні ... двома транспортними засобами, не зрушивши ні на сантиметр. Справді легендарне водіння.'::text,'керувала'::text,'керувала'::text,'керує'::text,'Вона сьогодні керувала двома транспортними засобами, не зрушивши ні на сантиметр. Справді легендарне водіння.'::text),
(342375,38042,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ella ... dos vehículos hoy sin moverse ni un centímetro. Conducción realmente legendaria.'::text,'ha manejado'::text,'ha estado manejando'::text,'está manejando'::text,'Ella ha manejado dos vehículos hoy sin moverse ni un centímetro. Conducción realmente legendaria.'::text),
(342374,38042,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ... deux véhicules aujourd''hui sans bouger d''un centimètre. Une conduite vraiment légendaire.'::text,'a piloté'::text,'a piloté'::text,'pilote'::text,'Elle a piloté deux véhicules aujourd''hui sans bouger d''un centimètre. Une conduite vraiment légendaire.'::text),
(342377,38042,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O bugün ... iki aracı, bir santim bile kıpırdamadan. Gerçekten efsanevi sürüş.'::text,'kontrol etti'::text,'kontrol edip durdu'::text,'kontrol ediyor'::text,'O bugün kontrol etti iki aracı, bir santim bile kıpırdamadan. Gerçekten efsanevi sürüş.'::text),
(342378,38042,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő ma két járművet ..., anélkül hogy egy centit is mozdult volna. Igazán legendás vezetés.'::text,'irányított'::text,'irányítgatott'::text,'irányít'::text,'Ő ma két járművet irányított, anélkül hogy egy centit is mozdult volna. Igazán legendás vezetés.'::text),
(342381,38043,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie bestand darauf, den Bus selbst ..., und das Depot war natürlich begeistert.'::text,'zu steuern'::text,'zu steuern'::text,'steuern'::text,'Sie bestand darauf, den Bus selbst zu steuern, und das Depot war natürlich begeistert.'::text),
(342385,38043,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона наполягла на тому, щоб ... автобусом самій. Депо, звісно, було в захваті.'::text,'керувати'::text,'керувати'::text,'керує'::text,'Вона наполягла на тому, щоб керувати автобусом самій. Депо, звісно, було в захваті.'::text),
(342384,38043,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ella insistió en ... el autobús ella misma. Obviamente, en la cochera estaban encantados.'::text,'conducir'::text,'conducir'::text,'conduce'::text,'Ella insistió en conducir el autobús ella misma. Obviamente, en la cochera estaban encantados.'::text),
(342383,38043,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle a tenu à ... le bus elle-même. Le dépôt était évidemment ravi.'::text,'conduire'::text,'conduire'::text,'conduit'::text,'Elle a tenu à conduire le bus elle-même. Le dépôt était évidemment ravi.'::text),
(342386,38043,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O otobüsü bizzat ... ısrar etti. Depo tabii ki çok mutluydu.'::text,'kullanmakta'::text,'kullanmakta'::text,'kullanıyor'::text,'O otobüsü bizzat kullanmakta ısrar etti. Depo tabii ki çok mutluydu.'::text),
(342387,38043,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő ragaszkodott hozzá, hogy maga ... a buszt. A telep nyilván el volt ragadtatva.'::text,'vezesse'::text,'vezesse'::text,'vezeti'::text,'Ő ragaszkodott hozzá, hogy maga vezesse a buszt. A telep nyilván el volt ragadtatva.'::text),
(397344,44150,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Mädchen gab an, dass es zuvor noch nie Zuckerguss auf der Zunge ...'::text,'gehabt hatte'::text,'gehabt hat'::text,'hat'::text,'Das Mädchen gab an, dass es zuvor noch nie Zuckerguss auf der Zunge gehabt hatte.'::text),
(397348,44150,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Дівчинка вказала, що раніше вона ... глазур на язиці.'::text,'ніколи не куштувала'::text,'ніколи не куштувала'::text,'ніколи не куштує'::text,'Дівчинка вказала, що раніше вона ніколи не куштувала глазур на язиці.'::text),
(397347,44150,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La niña indicó que ella ... glaseado en la lengua antes.'::text,'nunca había tenido'::text,'nunca ha tenido'::text,'nunca tiene'::text,'La niña indicó que ella nunca había tenido glaseado en la lengua antes.'::text),
(397346,44150,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La fillette a indiqué qu''elle ... de glaçage sur la langue auparavant.'::text,'n''avait jamais eu'::text,'n''a jamais eu'::text,'n''a jamais'::text,'La fillette a indiqué qu''elle n''avait jamais eu de glaçage sur la langue auparavant.'::text),
(397349,44150,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kız, daha önce dilinde hiç krema ... belirtti.'::text,'olmamış olduğunu'::text,'olmadığını'::text,'olmadığını'::text,'Kız, daha önce dilinde hiç krema olmamış olduğunu belirtti.'::text),
(397350,44150,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A kislány jelezte, hogy ő korábban még soha ... cukormázat a nyelvén.'::text,'nem érzett'::text,'nem érzett'::text,'nem érez'::text,'A kislány jelezte, hogy ő korábban még soha nem érzett cukormázat a nyelvén.'::text),
(399297,44367,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das eine der zwei gleichen Betten hat ein weißes Kopfteil, und ...'::text,'das andere auch'::text,'das andere auch'::text,'das andere auch nicht'::text,'Das eine der zwei gleichen Betten hat ein weißes Kopfteil, und das andere auch.'::text),
(399301,44367,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Одне з двох однакових ліжок має біле узголів''я, і ...'::text,'інше теж'::text,'інше теж'::text,'інше теж ні'::text,'Одне з двох однакових ліжок має біле узголів''я, і інше теж.'::text),
(399300,44367,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Una de las camas gemelas tiene un cabecero blanco, y ...'::text,'la otra también'::text,'la otra también'::text,'la otra tampoco'::text,'Una de las camas gemelas tiene un cabecero blanco, y la otra también.'::text),
(399299,44367,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''un des lits jumeaux a une tête de lit blanche, et ...'::text,'l''autre aussi'::text,'l''autre aussi'::text,'l''autre non plus'::text,'L''un des lits jumeaux a une tête de lit blanche, et l''autre aussi.'::text),
(399302,44367,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'İkiz yataklardan birinin beyaz bir başlığı var ve ...'::text,'diğerinin de'::text,'diğerinin de'::text,'diğerinin de yok'::text,'İkiz yataklardan birinin beyaz bir başlığı var ve diğerinin de.'::text),
(399303,44367,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az egyik ikerágynak fehér az ágytámlája, és ...'::text,'a másiknak is'::text,'a másiknak is'::text,'a másiknak sem'::text,'Az egyik ikerágynak fehér az ágytámlája, és a másiknak is.'::text),
(399351,44373,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hör zu, ich habe gehört, dass sie eine Stunde auf ihren gleichen Betten ..., bevor sie zu tanzen anfingen.'::text,'gesessen hatten'::text,'gesessen haben'::text,'sitzen'::text,'Hör zu, ich habe gehört, dass sie eine Stunde auf ihren gleichen Betten gesessen hatten, bevor sie zu tanzen anfingen.'::text),
(399355,44373,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, я чула, що вони ... годину на своїх однакових ліжках, перш ніж почали танцювати.'::text,'сиділи'::text,'сидять'::text,'сидять'::text,'Слухай, я чула, що вони сиділи годину на своїх однакових ліжках, перш ніж почали танцювати.'::text),
(399354,44373,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Escucha, yo oí que ellas ... en sus camas gemelas durante una hora antes de empezar a bailar.'::text,'habían estado sentadas'::text,'han estado sentadas'::text,'están sentadas'::text,'Escucha, yo oí que ellas habían estado sentadas en sus camas gemelas durante una hora antes de empezar a bailar.'::text),
(399353,44373,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, j''ai entendu dire qu''elles ... sur leurs lits jumeaux pendant une heure avant de se mettre à danser.'::text,'étaient restées assises'::text,'sont restées assises'::text,'sont assises'::text,'Écoute, j''ai entendu dire qu''elles étaient restées assises sur leurs lits jumeaux pendant une heure avant de se mettre à danser.'::text),
(399356,44373,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, ben onların dans etmeye başlamadan önce bir saat ikiz yataklarında ... duydum.'::text,'oturmuş olduklarını'::text,'oturduklarını'::text,'oturduklarını'::text,'Dinle, ben onların dans etmeye başlamadan önce bir saat ikiz yataklarında oturmuş olduklarını duydum.'::text),
(399357,44373,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, én úgy hallottam, hogy egy órát ... az ikerágyukon, mielőtt táncolni kezdtek.'::text,'ültek'::text,'ülnek'::text,'ülnek'::text,'Figyelj, én úgy hallottam, hogy egy órát ültek az ikerágyukon, mielőtt táncolni kezdtek.'::text),
(377895,41989,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, diese Patchworkdecke ist irgendwie ikonisch, ...?'::text,'oder nicht'::text,'oder'::text,'ja'::text,'Yo, diese Patchworkdecke ist irgendwie ikonisch, oder nicht?'::text),
(377899,41989,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Йо, ця печворкова ковдра якась легендарна, ...?'::text,'чи не так'::text,'хіба ні'::text,'так'::text,'Йо, ця печворкова ковдра якась легендарна, чи не так?'::text),
(377898,41989,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, esa colcha de patchwork es bastante icónica, ¿...?'::text,'verdad'::text,'no'::text,'sí'::text,'Oye, esa colcha de patchwork es bastante icónica, ¿verdad?'::text),
(377897,41989,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, cette courtepointe en patchwork est grave iconique, ... ?'::text,'non'::text,'pas vrai'::text,'hein'::text,'Yo, cette courtepointe en patchwork est grave iconique, non ?'::text),
(377900,41989,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, o yama yorgan resmen ikonik, ...?'::text,'değil mi'::text,'değil mi'::text,'öyle mi'::text,'Kanka, o yama yorgan resmen ikonik, değil mi?'::text),
(377901,41989,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, az a patchwork takaró elég ikonikus, ...?'::text,'nem'::text,'ugye'::text,'igaz'::text,'Tesó, az a patchwork takaró elég ikonikus, nem?'::text),
(377967,41997,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie gaben zu, die Decke in einer Nacht ..., was natürlich total glaubwürdig ist.'::text,'genäht zu haben'::text,'zu nähen'::text,'nähten'::text,'Sie gaben zu, die Decke in einer Nacht genäht zu haben, was natürlich total glaubwürdig ist.'::text),
(377971,41997,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вони зізналися, що ... ковдру за одну ніч, що, звісно, дуже правдоподібно.'::text,'пошили'::text,'пошити'::text,'пошили'::text,'Вони зізналися, що пошили ковдру за одну ніч, що, звісно, дуже правдоподібно.'::text),
(377970,41997,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ellas admitieron ... la colcha en una noche, lo cual es claramente muy creíble.'::text,'haber hecho'::text,'hacer'::text,'que hicieron'::text,'Ellas admitieron haber hecho la colcha en una noche, lo cual es claramente muy creíble.'::text),
(377969,41997,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elles ont avoué ... la courtepointe en une nuit, ce qui est clairement très crédible.'::text,'avoir fait'::text,'faire'::text,'qu''elles ont fait'::text,'Elles ont avoué avoir fait la courtepointe en une nuit, ce qui est clairement très crédible.'::text),
(377972,41997,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Onlar yorganı bir gecede ... itiraf etti, ki bu kesinlikle çok inandırıcı.'::text,'diktiklerini'::text,'dikmeyi'::text,'diktiklerini'::text,'Onlar yorganı bir gecede diktiklerini itiraf etti, ki bu kesinlikle çok inandırıcı.'::text),
(377973,41997,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ők bevallották, hogy egy éjszaka alatt ... a takarót, ami egyértelműen nagyon hihető.'::text,'megvarrták'::text,'megvarrni'::text,'megvarrták'::text,'Ők bevallották, hogy egy éjszaka alatt megvarrták a takarót, ami egyértelműen nagyon hihető.'::text),
(364926,40548,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Während sie sich an das Brückengeländer ..., verbuchte ihr Partner 5 km auf das Wochenziel.'::text,'lehnte'::text,'lehnte'::text,'gelehnt hat'::text,'Während sie sich an das Brückengeländer lehnte, verbuchte ihr Partner 5 km auf das Wochenziel.'::text),
(364930,40548,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Поки вона ... на поруччя мосту, її партнер зарахував 5 км у тижневу ціль.'::text,'спиралася'::text,'сперлася'::text,'сперлася'::text,'Поки вона спиралася на поруччя мосту, її партнер зарахував 5 км у тижневу ціль.'::text),
(364929,40548,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mientras ella ... en la barandilla del puente, su compañero registró 5 km para el objetivo semanal.'::text,'estaba apoyada'::text,'se apoyó'::text,'se ha apoyado'::text,'Mientras ella estaba apoyada en la barandilla del puente, su compañero registró 5 km para el objetivo semanal.'::text),
(364928,40548,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Pendant qu''elle ... sur la rambarde du pont, son partenaire a enregistré 5 km sur l''objectif hebdomadaire.'::text,'s''appuyait'::text,'s''est appuyée'::text,'s''est appuyée'::text,'Pendant qu''elle s''appuyait sur la rambarde du pont, son partenaire a enregistré 5 km sur l''objectif hebdomadaire.'::text),
(364931,40548,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O köprü korkuluğuna ..., partneri haftalık hedefe karşı 5 km kaydetti.'::text,'yaslanırken'::text,'yaslandı'::text,'yaslanmışken'::text,'O köprü korkuluğuna yaslanırken, partneri haftalık hedefe karşı 5 km kaydetti.'::text),
(364932,40548,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Miközben ő ... a híd korlátjának, a partnere 5 km-t könyvelt el a heti célra.'::text,'dőlt'::text,'nekidőlt'::text,'nekidőlt'::text,'Miközben ő dőlt a híd korlátjának, a partnere 5 km-t könyvelt el a heti célra.'::text),
(364953,40551,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ihr Partner ließ sie sich ans Geländer ..., bis der Seitenstich vorbei war.'::text,'lehnen'::text,'zu lehnen'::text,'lehnt'::text,'Ihr Partner ließ sie sich ans Geländer lehnen, bis der Seitenstich vorbei war.'::text),
(364957,40551,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Партнер змусив її ... на поруччя, поки біль у боці не минув.'::text,'спертися'::text,'спертися'::text,'спирається'::text,'Партнер змусив її спертися на поруччя, поки біль у боці не минув.'::text),
(364956,40551,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Su compañero hizo que ella se ... en la barandilla hasta que se le pasó el dolor del costado.'::text,'apoyara'::text,'apoyara'::text,'apoya'::text,'Su compañero hizo que ella se apoyara en la barandilla hasta que se le pasó el dolor del costado.'::text),
(364955,40551,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Son partenaire l''a fait ... sur la rambarde jusqu''à ce que la douleur au côté passe.'::text,'s''appuyer'::text,'de s''appuyer'::text,'s''appuie'::text,'Son partenaire l''a fait s''appuyer sur la rambarde jusqu''à ce que la douleur au côté passe.'::text),
(364958,40551,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Partneri, yan ağrısı geçene kadar onu korkuluğa ...'::text,'yaslandırdı'::text,'yaslanmaya'::text,'yaslanıyor'::text,'Partneri, yan ağrısı geçene kadar onu korkuluğa yaslandırdı.'::text),
(364959,40551,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A partnere rávette, hogy ő ... a korlátnak, amíg el nem múlt az oldalszúrása.'::text,'nekidőljön'::text,'nekidőlni'::text,'nekidől'::text,'A partnere rávette, hogy ő nekidőljön a korlátnak, amíg el nem múlt az oldalszúrása.'::text),
(332481,36943,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er schrie, dass sie ihm eine Medaille zu viel ...!'::text,'verliehen hatten'::text,'verliehen haben'::text,'verleihen'::text,'Er schrie, dass sie ihm eine Medaille zu viel verliehen hatten!'::text),
(332485,36943,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він кричав, що вони ... йому на одну медаль забагато!'::text,'вручили'::text,'вручили'::text,'вручають'::text,'Він кричав, що вони вручили йому на одну медаль забагато!'::text),
(332484,36943,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Él gritó que le ... una medalla de más!'::text,'habían dado'::text,'han dado'::text,'dan'::text,'¡Él gritó que le habían dado una medalla de más!'::text),
(332483,36943,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il a hurlé qu''ils lui ... une médaille de trop !'::text,'avaient décerné'::text,'ont décerné'::text,'décernent'::text,'Il a hurlé qu''ils lui avaient décerné une médaille de trop !'::text),
(332486,36943,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O, ona bir madalya fazla ... bağırdı!'::text,'vermiş olduklarını'::text,'verdiklerini'::text,'veriyor olduklarını'::text,'O, ona bir madalya fazla vermiş olduklarını bağırdı!'::text),
(332487,36943,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő azt üvöltötte, hogy eggyel több érmet ... neki!'::text,'ítéltek oda'::text,'ítéltek oda'::text,'ítélnek oda'::text,'Ő azt üvöltötte, hogy eggyel több érmet ítéltek oda neki!'::text),
(332508,36946,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gerade ... ihm die Offizierin noch eine Medaille.'::text,'verleiht'::text,'verleiht'::text,'hat verliehen'::text,'Gerade verleiht ihm die Offizierin noch eine Medaille.'::text),
(332512,36946,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Прямо зараз офіцерка ... йому ще одну медаль.'::text,'вручає'::text,'вручає'::text,'вручила'::text,'Прямо зараз офіцерка вручає йому ще одну медаль.'::text),
(332511,36946,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ahora mismo la oficial le ... otra medalla más.'::text,'está dando'::text,'da'::text,'ha dado'::text,'Ahora mismo la oficial le está dando otra medalla más.'::text),
(332510,36946,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En ce moment, l''officière lui ... encore une médaille.'::text,'remet'::text,'remet'::text,'a remis'::text,'En ce moment, l''officière lui remet encore une médaille.'::text),
(332513,36946,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Şu anda subay ona bir madalya daha ...'::text,'veriyor'::text,'verir'::text,'verdi'::text,'Şu anda subay ona bir madalya daha veriyor.'::text),
(332514,36946,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Épp most a tiszt ... neki még egy érmet.'::text,'adja át'::text,'átadja'::text,'átadta'::text,'Épp most a tiszt adja át neki még egy érmet.'::text),
(344208,38246,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn das Mädchen auf diesem moosigen Stein ausrutscht, ... es in den Bach.'::text,'fällt'::text,'würde fallen'::text,'fiel'::text,'Wenn das Mädchen auf diesem moosigen Stein ausrutscht, fällt es in den Bach.'::text),
(344212,38246,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо дівчина посковзнеться на тому мохатому камені, вона ... в струмок.'::text,'впаде'::text,'впала б'::text,'впала'::text,'Якщо дівчина посковзнеться на тому мохатому камені, вона впаде в струмок.'::text),
(344211,38246,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si la niña resbala en esa roca con musgo, ella ... al arroyo.'::text,'se caerá'::text,'se caería'::text,'se cayó'::text,'Si la niña resbala en esa roca con musgo, ella se caerá al arroyo.'::text),
(344210,38246,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si la fille glisse sur ce rocher moussu, elle ... dans le ruisseau.'::text,'tombera'::text,'tomberait'::text,'est tombée'::text,'Si la fille glisse sur ce rocher moussu, elle tombera dans le ruisseau.'::text),
(344213,38246,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kız o yosunlu kayada kayarsa, o dereye ...'::text,'düşecek'::text,'düşerdi'::text,'düştü'::text,'Kız o yosunlu kayada kayarsa, o dereye düşecek.'::text),
(344214,38246,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a lány megcsúszik azon a mohás sziklán, ő ... a patakba.'::text,'bele fog esni'::text,'beleesne'::text,'beleesett'::text,'Ha a lány megcsúszik azon a mohás sziklán, ő bele fog esni a patakba.'::text),
(392763,43641,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Diese Straßenlaterne ... seit etwa 17 Uhr.'::text,'brennt'::text,'brennt gerade'::text,'brennt'::text,'Diese Straßenlaterne brennt seit etwa 17 Uhr.'::text),
(392767,43641,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Цей ліхтар ... приблизно з 17:00.'::text,'горить'::text,'горить'::text,'горить'::text,'Цей ліхтар горить приблизно з 17:00.'::text),
(392766,43641,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Esta farola ... desde aproximadamente las 17:00.'::text,'lleva encendida'::text,'está encendida'::text,'se enciende'::text,'Esta farola lleva encendida desde aproximadamente las 17:00.'::text),
(392765,43641,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ce lampadaire ... depuis environ 17 h.'::text,'brille'::text,'est en train de briller'::text,'brille'::text,'Ce lampadaire brille depuis environ 17 h.'::text),
(392768,43641,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu sokak lambası yaklaşık 17.00''den beri ...'::text,'yanıyor'::text,'yanıyor'::text,'yanar'::text,'Bu sokak lambası yaklaşık 17.00''den beri yanıyor.'::text),
(392769,43641,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ez az utcai lámpa körülbelül 17 óra óta ...'::text,'világít'::text,'világít'::text,'világít'::text,'Ez az utcai lámpa körülbelül 17 óra óta világít.'::text),
(392835,43649,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... der Straßenlaternen blieb die Straße lange nach Sonnenuntergang hell.'::text,'Dank'::text,'Trotz'::text,'Im Falle'::text,'Dank der Straßenlaternen blieb die Straße lange nach Sonnenuntergang hell.'::text),
(392839,43649,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... вуличним ліхтарям дорога залишалася світлою ще довго після заходу сонця.'::text,'Завдяки'::text,'Попри'::text,'У разі'::text,'Завдяки вуличним ліхтарям дорога залишалася світлою ще довго після заходу сонця.'::text),
(392838,43649,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... las farolas, la calle siguió iluminada mucho después de la puesta de sol.'::text,'Gracias a'::text,'A pesar de'::text,'En caso de'::text,'Gracias a las farolas, la calle siguió iluminada mucho después de la puesta de sol.'::text),
(392837,43649,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... lampadaires, la route est restée éclairée longtemps après le coucher du soleil.'::text,'Grâce aux'::text,'Malgré les'::text,'En cas de'::text,'Grâce aux lampadaires, la route est restée éclairée longtemps après le coucher du soleil.'::text),
(392840,43649,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sokak lambaları ..., yol gün batımından çok sonra da aydınlık kaldı.'::text,'sayesinde'::text,'rağmen'::text,'durumunda'::text,'Sokak lambaları sayesinde, yol gün batımından çok sonra da aydınlık kaldı.'::text),
(392841,43649,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az utcai lámpáknak ... az út még sokáig világos maradt naplemente után.'::text,'köszönhetően'::text,'ellenére'::text,'esetén'::text,'Az utcai lámpáknak köszönhetően az út még sokáig világos maradt naplemente után.'::text),
(356781,39643,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie schreit ihren Laptop an, also ... ihre Frustration gerade riesig sein.'::text,'muss'::text,'könnte'::text,'kann nicht'::text,'Sie schreit ihren Laptop an, also muss ihre Frustration gerade riesig sein.'::text),
(356785,39643,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона кричить на ноутбук, тож її фрустрація ... бути величезною зараз.'::text,'має'::text,'може'::text,'не може'::text,'Вона кричить на ноутбук, тож її фрустрація має бути величезною зараз.'::text),
(356784,39643,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ella le está gritando al portátil, así que su frustración ... ser enorme ahora mismo.'::text,'debe de'::text,'podría'::text,'no puede'::text,'Ella le está gritando al portátil, así que su frustración debe de ser enorme ahora mismo.'::text),
(356783,39643,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle hurle sur son ordinateur portable, donc sa frustration ... être énorme en ce moment.'::text,'doit'::text,'pourrait'::text,'ne peut pas'::text,'Elle hurle sur son ordinateur portable, donc sa frustration doit être énorme en ce moment.'::text),
(356786,39643,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O dizüstü bilgisayarına bağırıyor, yani hayal kırıklığı şu anda çok büyük ...'::text,'olmalı'::text,'olabilir'::text,'olamaz'::text,'O dizüstü bilgisayarına bağırıyor, yani hayal kırıklığı şu anda çok büyük olmalı.'::text),
(356787,39643,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő a laptopjára kiabál, szóval a frusztrációja most ... hatalmas.'::text,'biztosan'::text,'talán'::text,'nem lehet'::text,'Ő a laptopjára kiabál, szóval a frusztrációja most biztosan hatalmas.'::text),
(356817,39647,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'..., die beim Subjekt beobachtet wird, tritt unmittelbar auf, nachdem sie das Blatt liest.'::text,'Die Frustration'::text,'Frustration'::text,'Eine Frustration'::text,'Die Frustration, die beim Subjekt beobachtet wird, tritt unmittelbar auf, nachdem sie das Blatt liest.'::text),
(356821,39647,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'..., яку спостерігають у суб''єкта, виникає одразу після того, як вона читає аркуш.'::text,'Фрустрація'::text,'Фрустрація'::text,'Фрустрація'::text,'Фрустрація, яку спостерігають у суб''єкта, виникає одразу після того, як вона читає аркуш.'::text),
(356820,39647,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... observada en el sujeto aparece justo después de que ella lee la hoja.'::text,'La frustración'::text,'Frustración'::text,'Una frustración'::text,'La frustración observada en el sujeto aparece justo después de que ella lee la hoja.'::text),
(356819,39647,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... observée chez le sujet survient immédiatement après qu''elle a lu la feuille.'::text,'La frustration'::text,'Frustration'::text,'Une frustration'::text,'La frustration observée chez le sujet survient immédiatement après qu''elle a lu la feuille.'::text),
(356822,39647,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Denekte gözlemlenen ..., o kâğıdı okuduktan hemen sonra ortaya çıkıyor.'::text,'hayal kırıklığı'::text,'hayal kırıklığı'::text,'bir hayal kırıklığı'::text,'Denekte gözlemlenen hayal kırıklığı, o kâğıdı okuduktan hemen sonra ortaya çıkıyor.'::text),
(356823,39647,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'..., amelyet az alanynál megfigyeltek, közvetlenül azután jelentkezik, hogy ő elolvassa a lapot.'::text,'A frusztráció'::text,'Frusztráció'::text,'Egy frusztráció'::text,'A frusztráció, amelyet az alanynál megfigyeltek, közvetlenül azután jelentkezik, hogy ő elolvassa a lapot.'::text),
(372621,41403,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Eindeutig ein entspannter Job: Wenn sie ans Telefon ..., landet noch mehr Papierkram auf ihrem Schreibtisch.'::text,'geht'::text,'gehen wird'::text,'ging'::text,'Eindeutig ein entspannter Job: Wenn sie ans Telefon geht, landet noch mehr Papierkram auf ihrem Schreibtisch.'::text),
(372625,41403,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Явно розслаблена робота: якщо вона ... телефон, на її стіл падає ще більше паперів.'::text,'бере'::text,'візьме'::text,'взяла'::text,'Явно розслаблена робота: якщо вона бере телефон, на її стіл падає ще більше паперів.'::text),
(372624,41403,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Claramente un trabajo relajante: si ella ... el teléfono, le cae más papeleo en la mesa.'::text,'contesta'::text,'contestará'::text,'contestó'::text,'Claramente un trabajo relajante: si ella contesta el teléfono, le cae más papeleo en la mesa.'::text),
(372623,41403,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Clairement un boulot relaxant : si elle ... au téléphone, encore plus de paperasse atterrit sur son bureau.'::text,'répond'::text,'répondra'::text,'répondait'::text,'Clairement un boulot relaxant : si elle répond au téléphone, encore plus de paperasse atterrit sur son bureau.'::text),
(372626,41403,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkça rahatlatıcı bir iş: o telefonu ..., masasına daha fazla evrak düşüyor.'::text,'açarsa'::text,'açacaksa'::text,'açtıysa'::text,'Açıkça rahatlatıcı bir iş: o telefonu açarsa, masasına daha fazla evrak düşüyor.'::text),
(372627,41403,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Egyértelműen pihentető munka: ha ő ... a telefont, még több papírmunka landol az asztalán.'::text,'felveszi'::text,'fel fogja venni'::text,'felvette'::text,'Egyértelműen pihentető munka: ha ő felveszi a telefont, még több papírmunka landol az asztalán.'::text),
(372666,41408,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn der Papierkram früher aufgehört hätte, ... sie nicht auf ihren Schreibtisch gesunken.'::text,'wäre'::text,'wird'::text,'ist'::text,'Wenn der Papierkram früher aufgehört hätte, wäre sie nicht auf ihren Schreibtisch gesunken.'::text),
(372670,41408,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби паперова робота закінчилася раніше, вона ... на стіл.'::text,'не впала б'::text,'не впаде'::text,'не впала'::text,'Якби паперова робота закінчилася раніше, вона не впала б на стіл.'::text),
(372669,41408,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si el papeleo hubiera parado antes, ella ... sobre la mesa.'::text,'no se habría desplomado'::text,'no se desplomará'::text,'no se desplomó'::text,'Si el papeleo hubiera parado antes, ella no se habría desplomado sobre la mesa.'::text),
(372668,41408,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si la paperasse s''était arrêtée plus tôt, elle ... sur son bureau.'::text,'ne se serait pas effondrée'::text,'ne s''effondrera pas'::text,'ne s''est pas effondrée'::text,'Si la paperasse s''était arrêtée plus tôt, elle ne se serait pas effondrée sur son bureau.'::text),
(372671,41408,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Evrak işi daha erken bitseydi, o masasına ...'::text,'yığılmazdı'::text,'yığılmayacak'::text,'yığılmadı'::text,'Evrak işi daha erken bitseydi, o masasına yığılmazdı.'::text),
(372672,41408,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a papírmunka korábban abbamaradt volna, ő ... az asztalára.'::text,'nem roskadt volna rá'::text,'nem fog ráborulni'::text,'nem roskadt rá'::text,'Ha a papírmunka korábban abbamaradt volna, ő nem roskadt volna rá az asztalára.'::text),
(398055,44229,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Gruppe wurde von der Trainerin durch jede Dehnung ...'::text,'geführt'::text,'geführt'::text,'führte'::text,'Die Gruppe wurde von der Trainerin durch jede Dehnung geführt.'::text),
(398059,44229,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Група ... через кожну розтяжку тренеркою.'::text,'була проведена'::text,'проводиться'::text,'провела'::text,'Група була проведена через кожну розтяжку тренеркою.'::text),
(398058,44229,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El grupo ... por cada estiramiento por la entrenadora.'::text,'fue guiado'::text,'es guiado'::text,'guio'::text,'El grupo fue guiado por cada estiramiento por la entrenadora.'::text),
(398057,44229,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le groupe ... à travers chaque étirement par l''entraîneuse.'::text,'a été guidé'::text,'est guidé'::text,'a guidé'::text,'Le groupe a été guidé à travers chaque étirement par l''entraîneuse.'::text),
(398060,44229,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Grup her esneme hareketinde eğitmen tarafından ...'::text,'yönlendirildi'::text,'yönlendirilir'::text,'yönlendirdi'::text,'Grup her esneme hareketinde eğitmen tarafından yönlendirildi.'::text),
(398061,44229,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A csoportot minden nyújtáson az edző ... végig.'::text,'vezette'::text,'vezeti'::text,'vezették'::text,'A csoportot minden nyújtáson az edző vezette végig.'::text),
(398127,44237,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Süße, sie hat mir erzählt, die Trainerin ... die Stunde schon zehn Minuten, als die Katze mitmachte.'::text,'leitete'::text,'leitet'::text,'leitet gerade'::text,'Süße, sie hat mir erzählt, die Trainerin leitete die Stunde schon zehn Minuten, als die Katze mitmachte.'::text),
(398131,44237,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, вона сказала мені, що тренерка ... заняття десять хвилин, коли приєднався кіт.'::text,'вела'::text,'веде'::text,'веде'::text,'Подруго, вона сказала мені, що тренерка вела заняття десять хвилин, коли приєднався кіт.'::text),
(398130,44237,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tía, ella me dijo que la entrenadora ... la clase durante diez minutos cuando se unió el gato.'::text,'había estado dirigiendo'::text,'ha estado dirigiendo'::text,'está dirigiendo'::text,'Tía, ella me dijo que la entrenadora había estado dirigiendo la clase durante diez minutos cuando se unió el gato.'::text),
(398129,44237,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Meuf, elle m''a dit que l''entraîneuse ... le cours depuis dix minutes quand le chat s''est joint à eux.'::text,'animait'::text,'anime'::text,'est en train d''animer'::text,'Meuf, elle m''a dit que l''entraîneuse animait le cours depuis dix minutes quand le chat s''est joint à eux.'::text),
(398132,44237,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, o bana kedi katıldığında eğitmenin on dakikadır dersi ... söyledi.'::text,'yönetiyor olduğunu'::text,'yönettiğini'::text,'yönetmekte olduğunu'::text,'Kızım, o bana kedi katıldığında eğitmenin on dakikadır dersi yönetiyor olduğunu söyledi.'::text),
(398133,44237,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, ő azt mondta nekem, hogy az edző már tíz perce ... az órát, amikor a macska beszállt.'::text,'vezette'::text,'vezeti'::text,'vezeti'::text,'Csajszi, ő azt mondta nekem, hogy az edző már tíz perce vezette az órát, amikor a macska beszállt.'::text),
(404148,44906,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Seit die Sonne unterzugehen begann, hat sie fünf Yoga-Posen ...'::text,'gemacht'::text,'gemacht'::text,'macht'::text,'Seit die Sonne unterzugehen begann, hat sie fünf Yoga-Posen gemacht.'::text),
(404152,44906,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Відколи сонце почало сідати, вона ... п''ять поз йоги.'::text,'зробила'::text,'робить'::text,'робить'::text,'Відколи сонце почало сідати, вона зробила п''ять поз йоги.'::text),
(404151,44906,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ella ... cinco posturas de yoga desde que el sol empezó a ponerse.'::text,'ha hecho'::text,'ha estado haciendo'::text,'hace'::text,'Ella ha hecho cinco posturas de yoga desde que el sol empezó a ponerse.'::text),
(404150,44906,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ... cinq postures de yoga depuis que le soleil a commencé à se coucher.'::text,'a fait'::text,'fait'::text,'fait'::text,'Elle a fait cinq postures de yoga depuis que le soleil a commencé à se coucher.'::text),
(404153,44906,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Güneş batmaya başladığından beri o beş yoga pozu ...'::text,'yaptı'::text,'yapıyor'::text,'yapar'::text,'Güneş batmaya başladığından beri o beş yoga pozu yaptı.'::text),
(404154,44906,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Amióta a nap elkezdett lemenni, ő öt jógapózt ...'::text,'csinált meg'::text,'csinál'::text,'csinál'::text,'Amióta a nap elkezdett lemenni, ő öt jógapózt csinált meg.'::text),
(373638,41516,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... natürlich einmal in ihr Lehrbuch und baute dann eine Mauer aus Büchern.'::text,'linste'::text,'linste gerade'::text,'hat gelinst'::text,'Sie linste natürlich einmal in ihr Lehrbuch und baute dann eine Mauer aus Büchern.'::text),
(373642,41516,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона, звісно, ... в підручник один раз, а потім збудувала стіну з книжок.'::text,'зазирнула'::text,'зазирала'::text,'зазирнула'::text,'Вона, звісно, зазирнула в підручник один раз, а потім збудувала стіну з книжок.'::text),
(373641,41516,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ella obviamente ... su libro de texto una vez y luego construyó un muro de libros.'::text,'echó un vistazo a'::text,'estaba echando un vistazo a'::text,'ha echado un vistazo a'::text,'Ella obviamente echó un vistazo a su libro de texto una vez y luego construyó un muro de libros.'::text),
(373640,41516,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ... évidemment une fois dans son manuel, puis a construit un mur de livres.'::text,'a jeté un œil'::text,'jetait un œil'::text,'a jeté un œil'::text,'Elle a jeté un œil évidemment une fois dans son manuel, puis a construit un mur de livres.'::text),
(373643,41516,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O tabii ki ders kitabına bir kez ..., sonra kitaplardan bir duvar ördü.'::text,'göz attı'::text,'göz atıyordu'::text,'göz atmış'::text,'O tabii ki ders kitabına bir kez göz attı, sonra kitaplardan bir duvar ördü.'::text),
(373644,41516,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő persze egyszer ... a tankönyvébe, aztán könyvfalat épített.'::text,'belekukkantott'::text,'kukucskált'::text,'belekukkantott'::text,'Ő persze egyszer belekukkantott a tankönyvébe, aztán könyvfalat épített.'::text),
(373692,41522,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hör zu, anscheinend hat sich das Mädchen, ... Augen immer wieder über die Bücher lugten, vor ihrem Ex versteckt.'::text,'dessen'::text,'das'::text,'welches'::text,'Hör zu, anscheinend hat sich das Mädchen, dessen Augen immer wieder über die Bücher lugten, vor ihrem Ex versteckt.'::text),
(373696,41522,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, кажуть, дівчина, ... очі постійно визирали з-за книжок, ховалася від свого колишнього.'::text,'чиї'::text,'яка'::text,'котра'::text,'Слухай, кажуть, дівчина, чиї очі постійно визирали з-за книжок, ховалася від свого колишнього.'::text),
(373695,41522,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Escucha, al parecer la chica, ... ojos no dejaban de asomarse por encima de los libros, se escondía de su ex.'::text,'cuyos'::text,'que'::text,'la cual'::text,'Escucha, al parecer la chica, cuyos ojos no dejaban de asomarse por encima de los libros, se escondía de su ex.'::text),
(373694,41522,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, apparemment la fille, ... les yeux dépassaient sans cesse des livres, se cachait de son ex.'::text,'dont'::text,'qui'::text,'laquelle'::text,'Écoute, apparemment la fille, dont les yeux dépassaient sans cesse des livres, se cachait de son ex.'::text),
(373697,41522,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, duyduğuma göre ... gözleri sürekli kitapların üstünden bakan kız, eski sevgilisinden saklanıyormuş.'::text,''::text,NULL::text,NULL::text,'Dinle, duyduğuma göre gözleri sürekli kitapların üstünden bakan kız, eski sevgilisinden saklanıyormuş.'::text),
(373698,41522,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, állítólag a lány, ... a szeme folyton kikandikált a könyvek mögül, az exe elől bujkált.'::text,'akinek'::text,'aki'::text,'amely'::text,'Figyelj, állítólag a lány, akinek a szeme folyton kikandikált a könyvek mögül, az exe elől bujkált.'::text),
(368778,40976,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, der Typ, ... den Metro-Gang gefilmt hat, sah ziemlich geschockt aus, echt.'::text,'der'::text,'welcher'::text,'dessen'::text,'Bro, der Typ, der den Metro-Gang gefilmt hat, sah ziemlich geschockt aus, echt.'::text),
(368782,40976,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, хлопець, ... знімав коридор метро, виглядав якось шокованим, чесно.'::text,'який'::text,'що'::text,'чий'::text,'Бро, хлопець, який знімав коридор метро, виглядав якось шокованим, чесно.'::text),
(368781,40976,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, el tío ... grabó el pasillo del metro parecía bastante flipado, en serio.'::text,'que'::text,'el cual'::text,'cuyo'::text,'Bro, el tío que grabó el pasillo del metro parecía bastante flipado, en serio.'::text),
(368780,40976,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, le mec ... a filmé le couloir du métro avait l''air grave choqué, sérieux.'::text,'qui'::text,'lequel'::text,'dont'::text,'Frérot, le mec qui a filmé le couloir du métro avait l''air grave choqué, sérieux.'::text),
(368783,40976,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, metro koridorunu ... çeken adam epey şokta görünüyordu, cidden.'::text,''::text,NULL::text,NULL::text,'Kanka, metro koridorunu çeken adam epey şokta görünüyordu, cidden.'::text),
(368784,40976,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, a srác, ... a metrófolyosót filmezte, elég sokkosnak tűnt, komolyan.'::text,'aki'::text,'amely'::text,'akinek'::text,'Tesó, a srác, aki a metrófolyosót filmezte, elég sokkosnak tűnt, komolyan.'::text),
(329484,36610,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Als sie die Linie überquerte, ... ihr zwei Freunde, also überquerte sie sie nicht allein.'::text,'halfen'::text,'halfen'::text,'haben geholfen'::text,'Als sie die Linie überquerte, halfen ihr zwei Freunde, also überquerte sie sie nicht allein.'::text),
(329488,36610,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коли вона перетинала лінію, двоє друзів ... їй, тож вона перетинала її не сама.'::text,'допомагали'::text,'допомогли'::text,'допомогли'::text,'Коли вона перетинала лінію, двоє друзів допомагали їй, тож вона перетинала її не сама.'::text),
(329487,36610,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cuando ella cruzó la línea, dos amigos la ..., así que no la estaba cruzando sola.'::text,'estaban ayudando'::text,'ayudaron'::text,'han ayudado'::text,'Cuando ella cruzó la línea, dos amigos la estaban ayudando, así que no la estaba cruzando sola.'::text),
(329486,36610,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Quand elle a franchi la ligne, deux amis ..., donc elle ne la franchissait pas seule.'::text,'l''aidaient'::text,'l''ont aidée'::text,'l''ont aidée'::text,'Quand elle a franchi la ligne, deux amis l''aidaient, donc elle ne la franchissait pas seule.'::text),
(329489,36610,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O çizgiyi geçtiğinde iki arkadaşı ona ..., yani çizgiyi tek başına geçmiyordu.'::text,'yardım ediyordu'::text,'yardım etti'::text,'yardım etmiş'::text,'O çizgiyi geçtiğinde iki arkadaşı ona yardım ediyordu, yani çizgiyi tek başına geçmiyordu.'::text),
(329490,36610,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Amikor ő átlépte a vonalat, két barátja ... neki, így nem egyedül lépte át.'::text,'segített'::text,'segített'::text,'segített'::text,'Amikor ő átlépte a vonalat, két barátja segített neki, így nem egyedül lépte át.'::text),
(329556,36618,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nee Bro, die zwei ... ihr schon so 200 Meter lang, als sie sich im Ziel umarmten.'::text,'halfen'::text,'halfen gerade'::text,'helfen'::text,'Nee Bro, die zwei halfen ihr schon so 200 Meter lang, als sie sich im Ziel umarmten.'::text),
(329560,36618,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Та ні, бро, ті двоє ... їй метрів 200, поки вони не обнялися на фініші.'::text,'допомагали'::text,'допомагали'::text,'допомагають'::text,'Та ні, бро, ті двоє допомагали їй метрів 200, поки вони не обнялися на фініші.'::text),
(329559,36618,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Qué va, bro, esos dos la ... unos 200 metros para cuando se abrazaron en la meta.'::text,'habían estado ayudando'::text,'estaban ayudando'::text,'han estado ayudando'::text,'Qué va, bro, esos dos la habían estado ayudando unos 200 metros para cuando se abrazaron en la meta.'::text),
(329558,36618,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nan frérot, ces deux-là ... sur genre 200 mètres au moment où ils se sont enlacés sur la ligne.'::text,'l''avaient aidée'::text,'l''aidaient'::text,'l''ont aidée'::text,'Nan frérot, ces deux-là l''avaient aidée sur genre 200 mètres au moment où ils se sont enlacés sur la ligne.'::text),
(329561,36618,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yok kanka, o ikisi bitişte sarılana kadar ona 200 metre kadar ...'::text,'yardım ediyordu'::text,'yardım ediyordu'::text,'yardım ediyor'::text,'Yok kanka, o ikisi bitişte sarılana kadar ona 200 metre kadar yardım ediyordu.'::text),
(329562,36618,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Á, tesó, az a kettő nagyjából 200 méteren át ... neki, mire a célban összeölelkeztek.'::text,'segített'::text,'segített'::text,'segít'::text,'Á, tesó, az a kettő nagyjából 200 méteren át segített neki, mire a célban összeölelkeztek.'::text),
(331842,36872,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bei ihren früheren Rennen ... sie niemanden, der ihr im Ziel assistierte.'::text,'brauchte'::text,'brauchte'::text,'war es gewohnt zu brauchen'::text,'Bei ihren früheren Rennen brauchte sie niemanden, der ihr im Ziel assistierte.'::text),
(331846,36872,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'На своїх старих перегонах вона ... нікого, хто допоміг би їй на фініші.'::text,'раніше не потребувала'::text,'не потребувала б'::text,'не звикла потребувати'::text,'На своїх старих перегонах вона раніше не потребувала нікого, хто допоміг би їй на фініші.'::text),
(331845,36872,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En sus carreras de antes, ella ... necesitar a nadie que la ayudara en la meta.'::text,'no solía'::text,'no iba a'::text,'no estaba acostumbrada a'::text,'En sus carreras de antes, ella no solía necesitar a nadie que la ayudara en la meta.'::text),
(331844,36872,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dans ses anciennes courses, elle ... besoin de personne pour l''aider à l''arrivée.'::text,'n''avait jamais'::text,'n''aurait'::text,'n''était pas habituée à avoir'::text,'Dans ses anciennes courses, elle n''avait jamais besoin de personne pour l''aider à l''arrivée.'::text),
(331847,36872,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Eski yarışlarında o bitişte kendisine yardım edecek birine ...'::text,'ihtiyaç duymazdı'::text,'ihtiyaç duymazdı'::text,'ihtiyaç duymaya alışkın değildi'::text,'Eski yarışlarında o bitişte kendisine yardım edecek birine ihtiyaç duymazdı.'::text),
(331848,36872,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A régi versenyein ő ... senkire, aki segítsen neki a célban.'::text,'nem szokott rászorulni'::text,'nem szorult volna'::text,'nem volt hozzászokva, hogy rászoruljon'::text,'A régi versenyein ő nem szokott rászorulni senkire, aki segítsen neki a célban.'::text),
(331896,36878,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis zum Ende des Rennens wird das Team im Ziel den Läufern laut Bericht vier Stunden lang ...'::text,'geholfen haben'::text,'helfen'::text,'helfen'::text,'Bis zum Ende des Rennens wird das Team im Ziel den Läufern laut Bericht vier Stunden lang geholfen haben.'::text),
(331900,36878,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До кінця перегонів команда на фініші ... бігунам чотири години, згідно зі звітом.'::text,'допомагатиме'::text,'допомагатиме'::text,'допоможе'::text,'До кінця перегонів команда на фініші допомагатиме бігунам чотири години, згідно зі звітом.'::text),
(331899,36878,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para el final de la carrera, el equipo de meta ... a los corredores durante cuatro horas, según el informe.'::text,'habrá estado asistiendo'::text,'estará asistiendo'::text,'asistirá'::text,'Para el final de la carrera, el equipo de meta habrá estado asistiendo a los corredores durante cuatro horas, según el informe.'::text),
(331898,36878,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici la fin de la course, l''équipe de l''arrivée ... les coureurs pendant quatre heures, selon le rapport.'::text,'aura assisté'::text,'sera en train d''assister'::text,'assistera'::text,'D''ici la fin de la course, l''équipe de l''arrivée aura assisté les coureurs pendant quatre heures, selon le rapport.'::text),
(331901,36878,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yarışın sonuna kadar bitiş ekibi rapora göre dört saat boyunca koşuculara ...'::text,'yardım etmiş olacak'::text,'yardım ediyor olacak'::text,'yardım edecek'::text,'Yarışın sonuna kadar bitiş ekibi rapora göre dört saat boyunca koşuculara yardım etmiş olacak.'::text),
(331902,36878,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A verseny végére a célcsapat a jelentés szerint négy órán át ... a futóknak.'::text,'segített majd'::text,'segíteni fog'::text,'segít majd'::text,'A verseny végére a célcsapat a jelentés szerint négy órán át segített majd a futóknak.'::text),
(402294,44700,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Seine Waffe wurde ins Gras ...! Es ist vorbei, komplett vorbei!'::text,'gesenkt'::text,'senkte'::text,'senkend'::text,'Seine Waffe wurde ins Gras gesenkt! Es ist vorbei, komplett vorbei!'::text),
(402298,44700,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Його зброя ... на траву! Усе скінчено, повністю скінчено!'::text,'була опущена'::text,'опустила'::text,'опускаючи'::text,'Його зброя була опущена на траву! Усе скінчено, повністю скінчено!'::text),
(402297,44700,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Su arma ... sobre la hierba! ¡Se acabó, se acabó del todo!'::text,'fue bajada'::text,'bajó'::text,'bajando'::text,'¡Su arma fue bajada sobre la hierba! ¡Se acabó, se acabó del todo!'::text),
(402296,44700,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Son arme ... dans l''herbe ! C''est fini, complètement fini !'::text,'a été baissée'::text,'a baissé'::text,'baissant'::text,'Son arme a été baissée dans l''herbe ! C''est fini, complètement fini !'::text),
(402299,44700,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Onun silahı çimenlere ...! Bitti, tamamen bitti!'::text,'indirildi'::text,'indirdi'::text,'indirerek'::text,'Onun silahı çimenlere indirildi! Bitti, tamamen bitti!'::text),
(402300,44700,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A fegyverét ... a fűbe! Vége, teljesen vége!'::text,'leengedték'::text,'leengedte'::text,'leengedve'::text,'A fegyverét leengedték a fűbe! Vége, teljesen vége!'::text),
(402384,44710,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis 17 Uhr werden die Spieler diesen Waffentyp etwa sechs Stunden lang ...'::text,'benutzt haben'::text,'benutzen'::text,'benutzt'::text,'Bis 17 Uhr werden die Spieler diesen Waffentyp etwa sechs Stunden lang benutzt haben.'::text),
(402388,44710,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До 17:00 гравці ... цей тип зброї приблизно шість годин.'::text,'використовуватимуть'::text,'використовуватимуть'::text,'використовували'::text,'До 17:00 гравці використовуватимуть цей тип зброї приблизно шість годин.'::text),
(402387,44710,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para las 17:00, los jugadores ... este tipo de arma durante aproximadamente seis horas.'::text,'habrán estado usando'::text,'estarán usando'::text,'han usado'::text,'Para las 17:00, los jugadores habrán estado usando este tipo de arma durante aproximadamente seis horas.'::text),
(402386,44710,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici 17 h, les joueurs ... ce type d''arme pendant environ six heures.'::text,'auront utilisé'::text,'seront en train d''utiliser'::text,'ont utilisé'::text,'D''ici 17 h, les joueurs auront utilisé ce type d''arme pendant environ six heures.'::text),
(402389,44710,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Saat 17.00''ye kadar oyuncular bu tür silahı yaklaşık altı saattir ...'::text,'kullanıyor olacak'::text,'kullanıyor olacak'::text,'kullandı'::text,'Saat 17.00''ye kadar oyuncular bu tür silahı yaklaşık altı saattir kullanıyor olacak.'::text),
(402390,44710,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Délután 5-re a játékosok körülbelül hat órája ... ezt a fegyvertípust.'::text,'fogják használni'::text,'fogják használni'::text,'használták'::text,'Délután 5-re a játékosok körülbelül hat órája fogják használni ezt a fegyvertípust.'::text),
(394698,43856,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'In dem Moment, als die Farbe platzte, wusste er, dass er sich innerhalb von Sekunden ...! Totale Katastrophe!'::text,'ergeben würde'::text,'ergeben wird'::text,'ergibt'::text,'In dem Moment, als die Farbe platzte, wusste er, dass er sich innerhalb von Sekunden ergeben würde! Totale Katastrophe!'::text),
(394702,43856,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Щойно вибухнула фарба, він знав, що ... за лічені секунди! Повна катастрофа!'::text,'здасться'::text,'здасться'::text,'здається'::text,'Щойно вибухнула фарба, він знав, що здасться за лічені секунди! Повна катастрофа!'::text),
(394701,43856,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡En cuanto estalló la pintura, él supo que se ... en cuestión de segundos! ¡Desastre total!'::text,'rendiría'::text,'rendirá'::text,'está rindiendo'::text,'¡En cuanto estalló la pintura, él supo que se rendiría en cuestión de segundos! ¡Desastre total!'::text),
(394700,43856,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Au moment où la peinture a éclaté, il a su qu''il ... en quelques secondes ! Désastre total !'::text,'se rendrait'::text,'se rendra'::text,'se rend'::text,'Au moment où la peinture a éclaté, il a su qu''il se rendrait en quelques secondes ! Désastre total !'::text),
(394703,43856,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Boya patladığı an o saniyeler içinde ... biliyordu! Tam bir felaket!'::text,'teslim olacağını'::text,'teslim olacağını'::text,'teslim olduğunu'::text,'Boya patladığı an o saniyeler içinde teslim olacağını biliyordu! Tam bir felaket!'::text),
(394704,43856,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Abban a pillanatban, amikor a festék szétfröccsent, ő tudta, hogy másodperceken belül ...! Teljes katasztrófa!'::text,'megadja magát'::text,'meg fogja adni magát'::text,'megadja magát'::text,'Abban a pillanatban, amikor a festék szétfröccsent, ő tudta, hogy másodperceken belül megadja magát! Teljes katasztrófa!'::text),
(393717,43747,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis zur Pause ... sie sich 12 Burger in den Mund gestopft und das Ziel übertroffen.'::text,'hatte'::text,'hat'::text,'stopft'::text,'Bis zur Pause hatte sie sich 12 Burger in den Mund gestopft und das Ziel übertroffen.'::text),
(393721,43747,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До перерви вона ... до рота 12 бургерів і перевершила ціль.'::text,'напхала'::text,'напхала'::text,'напихає'::text,'До перерви вона напхала до рота 12 бургерів і перевершила ціль.'::text),
(393720,43747,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para el descanso, ella se ... 12 hamburguesas en la boca y superado el objetivo.'::text,'había metido'::text,'ha metido'::text,'mete'::text,'Para el descanso, ella se había metido 12 hamburguesas en la boca y superado el objetivo.'::text),
(393719,43747,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'À la pause, elle ... 12 burgers dans la bouche et dépassé l''objectif.'::text,'s''était enfoncé'::text,'s''est enfoncé'::text,'s''enfonce'::text,'À la pause, elle s''était enfoncé 12 burgers dans la bouche et dépassé l''objectif.'::text),
(393722,43747,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Molaya kadar o ağzına 12 burger ... ve hedefi aşmıştı.'::text,'tıkıştırmıştı'::text,'tıkıştırdı'::text,'tıkıştırıyor'::text,'Molaya kadar o ağzına 12 burger tıkıştırmıştı ve hedefi aşmıştı.'::text),
(393723,43747,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A szünetre ő ... 12 burgert a szájába, és túlszárnyalta a célt.'::text,'már betömött'::text,'betömött'::text,'betöm'::text,'A szünetre ő már betömött 12 burgert a szájába, és túlszárnyalta a célt.'::text),
(393762,43752,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... sich schon fünf Minuten lang Burger rein, als ihre Wangen fast explodierten!'::text,'stopfte'::text,'stopft'::text,'stopft gerade'::text,'Sie stopfte sich schon fünf Minuten lang Burger rein, als ihre Wangen fast explodierten!'::text),
(393766,43752,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона ... бургерами п''ять хвилин, коли її щоки мало не вибухнули!'::text,'напихалася'::text,'напихається'::text,'напихається'::text,'Вона напихалася бургерами п''ять хвилин, коли її щоки мало не вибухнули!'::text),
(393765,43752,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Ella ... hamburguesas durante cinco minutos cuando casi le explotan las mejillas!'::text,'había estado zampándose'::text,'ha estado zampándose'::text,'está zampándose'::text,'¡Ella había estado zampándose hamburguesas durante cinco minutos cuando casi le explotan las mejillas!'::text),
(393764,43752,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ... des burgers depuis cinq minutes quand ses joues ont failli exploser !'::text,'s''enfilait'::text,'s''enfile'::text,'est en train de s''enfiler'::text,'Elle s''enfilait des burgers depuis cinq minutes quand ses joues ont failli exploser !'::text),
(393767,43752,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yanakları neredeyse patladığında o beş dakikadır burger ...!'::text,'tıkıştırıyordu'::text,'tıkıştırıyor'::text,'tıkıştırıyor'::text,'Yanakları neredeyse patladığında o beş dakikadır burger tıkıştırıyordu!'::text),
(393768,43752,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő már öt perce ... a burgereket, amikor majdnem szétrobbant az arca!'::text,'tömte'::text,'tömi'::text,'tömi'::text,'Ő már öt perce tömte a burgereket, amikor majdnem szétrobbant az arca!'::text),
(393915,43769,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn die Sonne so heiß ..., leiden die Menschen und schwitzen viel.'::text,'ist'::text,'war'::text,'sein wird'::text,'Wenn die Sonne so heiß ist, leiden die Menschen und schwitzen viel.'::text),
(393919,43769,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коли сонце ... таке пекуче, люди страждають і сильно пітніють.'::text,''::text,'було'::text,'буде'::text,'Коли сонце таке пекуче, люди страждають і сильно пітніють.'::text),
(393918,43769,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si el sol ... así de fuerte, la gente sufre y suda mucho.'::text,'está'::text,'estaba'::text,'estará'::text,'Si el sol está así de fuerte, la gente sufre y suda mucho.'::text),
(393917,43769,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si le soleil ... aussi chaud, les gens souffrent et transpirent beaucoup.'::text,'est'::text,'était'::text,'sera'::text,'Si le soleil est aussi chaud, les gens souffrent et transpirent beaucoup.'::text),
(393920,43769,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Güneş bu kadar sıcak ..., insanlar acı çeker ve çok terler.'::text,'olursa'::text,'olduysa'::text,'olacaksa'::text,'Güneş bu kadar sıcak olursa, insanlar acı çeker ve çok terler.'::text),
(393921,43769,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a nap ... ilyen forró, az emberek szenvednek és sokat izzadnak.'::text,''::text,'volt'::text,'lesz'::text,'Ha a nap ilyen forró, az emberek szenvednek és sokat izzadnak.'::text),
(397560,44174,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er sagte, dass das Training das härteste seines ganzen Lebens ...! Pure Qual!'::text,'gewesen war'::text,'gewesen ist'::text,'ist'::text,'Er sagte, dass das Training das härteste seines ganzen Lebens gewesen war! Pure Qual!'::text),
(397564,44174,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він сказав, що тренування ... найважчим у всьому його житті! Суща агонія!'::text,'було'::text,'було'::text,'є'::text,'Він сказав, що тренування було найважчим у всьому його житті! Суща агонія!'::text),
(397563,44174,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Él dijo que el entrenamiento ... el más duro de toda su vida! ¡Pura agonía!'::text,'había sido'::text,'ha sido'::text,'es'::text,'¡Él dijo que el entrenamiento había sido el más duro de toda su vida! ¡Pura agonía!'::text),
(397562,44174,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il a dit que l''entraînement ... le plus dur de toute sa vie ! Une pure agonie !'::text,'avait été'::text,'a été'::text,'est'::text,'Il a dit que l''entraînement avait été le plus dur de toute sa vie ! Une pure agonie !'::text),
(397565,44174,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O antrenmanın tüm hayatının en zoru ... söyledi! Tam bir işkence!'::text,'olmuş olduğunu'::text,'olduğunu'::text,'olduğunu'::text,'O antrenmanın tüm hayatının en zoru olmuş olduğunu söyledi! Tam bir işkence!'::text),
(397566,44174,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő azt mondta, hogy az edzés ... egész élete legkeményebbje! Tiszta kín!'::text,'volt'::text,'volt'::text,NULL::text,'Ő azt mondta, hogy az edzés volt egész élete legkeményebbje! Tiszta kín!'::text),
(397605,44179,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... seit zwei Stunden, also sah er müde, aber taff aus.'::text,'trainierte'::text,'trainiert'::text,'trainiert gerade'::text,'Er trainierte seit zwei Stunden, also sah er müde, aber taff aus.'::text),
(397609,44179,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він ... дві години, тож виглядав утомленим, але міцним.'::text,'тренувався'::text,'тренується'::text,'тренується'::text,'Він тренувався дві години, тож виглядав утомленим, але міцним.'::text),
(397608,44179,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Él ... durante dos horas, así que parecía cansado pero duro.'::text,'había estado entrenando'::text,'ha estado entrenando'::text,'está entrenando'::text,'Él había estado entrenando durante dos horas, así que parecía cansado pero duro.'::text),
(397607,44179,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... depuis deux heures, alors il avait l''air fatigué mais coriace.'::text,'s''entraînait'::text,'s''entraîne'::text,'est en train de s''entraîner'::text,'Il s''entraînait depuis deux heures, alors il avait l''air fatigué mais coriace.'::text),
(397610,44179,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O iki saattir ..., bu yüzden yorgun ama sert görünüyordu.'::text,'antrenman yapıyordu'::text,'antrenman yapıyor'::text,'antrenman yapıyor'::text,'O iki saattir antrenman yapıyordu, bu yüzden yorgun ama sert görünüyordu.'::text),
(397611,44179,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő két órája ..., így fáradtnak, de keménynek tűnt.'::text,'edzett'::text,'edz'::text,'edz'::text,'Ő két órája edzett, így fáradtnak, de keménynek tűnt.'::text),
(338115,37569,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Kanu, ... Paddel beinahe ins Meer rutschte, hat die Katastrophe überlebt!'::text,'dessen'::text,'das'::text,'welches'::text,'Das Kanu, dessen Paddel beinahe ins Meer rutschte, hat die Katastrophe überlebt!'::text),
(338119,37569,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Каное, ... весло мало не зісковзнуло в море, пережило катастрофу!'::text,'чиє'::text,'яке'::text,'що'::text,'Каное, чиє весло мало не зісковзнуло в море, пережило катастрофу!'::text),
(338118,37569,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡La canoa, ... remo casi se resbala al mar, sobrevivió al desastre!'::text,'cuyo'::text,'que'::text,'la cual'::text,'¡La canoa, cuyo remo casi se resbala al mar, sobrevivió al desastre!'::text),
(338117,37569,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le canoë, ... la pagaie a failli glisser dans la mer, a survécu au désastre !'::text,'dont'::text,'qui'::text,'que'::text,'Le canoë, dont la pagaie a failli glisser dans la mer, a survécu au désastre !'::text),
(338120,37569,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... küreği neredeyse denize kayan kano, felaketten sağ çıktı!'::text,''::text,NULL::text,NULL::text,'Küreği neredeyse denize kayan kano, felaketten sağ çıktı!'::text),
(338121,37569,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A kenu, ... az evezője majdnem a tengerbe csúszott, túlélte a katasztrófát!'::text,'amelynek'::text,'amely'::text,'ami'::text,'A kenu, amelynek az evezője majdnem a tengerbe csúszott, túlélte a katasztrófát!'::text),
(357501,39723,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, nächstes Jahr um diese Zeit wirst du denselben Kranz an diesem See ...'::text,'tragen'::text,'tragen'::text,'trägst'::text,'Ehrlich, nächstes Jahr um diese Zeit wirst du denselben Kranz an diesem See tragen.'::text),
(357505,39723,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, наступного року в цей час ти ... той самий вінок біля цього озера.'::text,'носитимеш'::text,'одягнеш'::text,'носиш'::text,'Чесно, наступного року в цей час ти носитимеш той самий вінок біля цього озера.'::text),
(357504,39723,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sinceramente, el año que viene por estas fechas tú ... la misma guirnalda en este lago.'::text,'estarás llevando'::text,'llevarás'::text,'llevas'::text,'Sinceramente, el año que viene por estas fechas tú estarás llevando la misma guirnalda en este lago.'::text),
(357503,39723,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, l''année prochaine à la même époque, tu ... la même couronne au bord de ce lac.'::text,'porteras'::text,'porteras'::text,'portes'::text,'Franchement, l''année prochaine à la même époque, tu porteras la même couronne au bord de ce lac.'::text),
(357506,39723,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası, seneye bu zamanlar sen bu gölün kenarında aynı çelengi ...'::text,'takıyor olacaksın'::text,'takacaksın'::text,'takıyorsun'::text,'Açıkçası, seneye bu zamanlar sen bu gölün kenarında aynı çelengi takıyor olacaksın.'::text),
(357507,39723,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, jövőre ilyenkor te ugyanazt a koszorút ... ennél a tónál.'::text,'fogod viselni'::text,'viseled majd'::text,'viseled'::text,'Őszintén, jövőre ilyenkor te ugyanazt a koszorút fogod viselni ennél a tónál.'::text),
(351543,39061,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Als es endlich jemand bemerkte, ... der Teig schon über den Rand gequollen. Super aufgepasst, alle zusammen.'::text,'war'::text,'ist'::text,'quillt'::text,'Als es endlich jemand bemerkte, war der Teig schon über den Rand gequollen. Super aufgepasst, alle zusammen.'::text),
(351547,39061,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Поки хтось помітив, тісто вже ... через край. Чудова робота з наглядом, усі.'::text,'розрослося'::text,'розрослося'::text,'розростається'::text,'Поки хтось помітив, тісто вже розрослося через край. Чудова робота з наглядом, усі.'::text),
(351546,39061,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para cuando alguien se dio cuenta, la masa ya ... por encima del borde. Buen trabajo vigilando, chicos.'::text,'había crecido'::text,'ha crecido'::text,'crece'::text,'Para cuando alguien se dio cuenta, la masa ya había crecido por encima del borde. Buen trabajo vigilando, chicos.'::text),
(351545,39061,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le temps que quelqu''un s''en aperçoive, la pâte ... par-dessus le bord. Bravo pour la surveillance, tout le monde.'::text,'avait gonflé'::text,'a gonflé'::text,'gonfle'::text,'Le temps que quelqu''un s''en aperçoive, la pâte avait gonflé par-dessus le bord. Bravo pour la surveillance, tout le monde.'::text),
(351548,39061,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Biri fark ettiğinde hamur çoktan ... kenarın üstüne doğru. Harika gözetim, millet.'::text,'kabarmıştı'::text,'kabardı'::text,'kabarıyor'::text,'Biri fark ettiğinde hamur çoktan kabarmıştı kenarın üstüne doğru. Harika gözetim, millet.'::text),
(351549,39061,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mire bárki észrevette, a tészta már ... a peremen túl. Remek felügyelet, mindenki.'::text,'megdagadt'::text,'megdagadt'::text,'dagad'::text,'Mire bárki észrevette, a tészta már megdagadt a peremen túl. Remek felügyelet, mindenki.'::text),
(351579,39065,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gerade ... das blaue Planschbecken auf dem Rasen vor der Frau.'::text,'wächst'::text,'wächst'::text,'ist gewachsen'::text,'Gerade wächst das blaue Planschbecken auf dem Rasen vor der Frau.'::text),
(351583,39065,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Прямо зараз блакитний дитячий басейн ... на газоні перед жінкою.'::text,'збільшується'::text,'збільшується'::text,'збільшився'::text,'Прямо зараз блакитний дитячий басейн збільшується на газоні перед жінкою.'::text),
(351582,39065,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ahora mismo, la piscina hinchable azul ... en el césped delante de la mujer.'::text,'se está expandiendo'::text,'se expande'::text,'se ha expandido'::text,'Ahora mismo, la piscina hinchable azul se está expandiendo en el césped delante de la mujer.'::text),
(351581,39065,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En ce moment, la piscine gonflable bleue ... sur la pelouse devant la femme.'::text,'est en train de gonfler'::text,'gonfle'::text,'a gonflé'::text,'En ce moment, la piscine gonflable bleue est en train de gonfler sur la pelouse devant la femme.'::text),
(351584,39065,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Şu anda mavi şişme havuz kadının önündeki çimenlikte ...'::text,'genişliyor'::text,'genişler'::text,'genişledi'::text,'Şu anda mavi şişme havuz kadının önündeki çimenlikte genişliyor.'::text),
(351585,39065,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Épp most a kék pancsolómedence ... a pázsiton a nő előtt.'::text,'tágul'::text,'tágul'::text,'kitágult'::text,'Épp most a kék pancsolómedence tágul a pázsiton a nő előtt.'::text)
) v(id, eid, lang, n_intro_text, n_correct_answer, n_distractor_1, n_distractor_2, n_full_sentence, o_intro_text, o_correct_answer, o_distractor_1, o_distractor_2, o_full_sentence)
where l.id = v.id and l.exercise_id = v.eid and l.language_code = v.lang and l.intro_text is not distinct from v.o_intro_text and l.correct_answer is not distinct from v.o_correct_answer and l.distractor_1 is not distinct from v.o_distractor_1 and l.distractor_2 is not distinct from v.o_distractor_2 and l.full_sentence is not distinct from v.o_full_sentence
returning l.id;
commit;
